#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
#[derive(Default)]
pub enum GoalAutomationMode {
    #[default]
    HumanInTheLoop,
    HighAutonomy,
    FullAuto,
}

impl GoalAutomationMode {
    pub fn as_str(&self) -> &'static str {
        match self {
            Self::HumanInTheLoop => "human_in_the_loop",
            Self::HighAutonomy => "high_autonomy",
            Self::FullAuto => "full_auto",
        }
    }

    pub fn from_str(value: &str) -> Option<Self> {
        match value {
            "human_in_the_loop" => Some(Self::HumanInTheLoop),
            "high_autonomy" => Some(Self::HighAutonomy),
            "full_auto" => Some(Self::FullAuto),
            _ => None,
        }
    }
}

