#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct GoalStageTaskSemanticReviewPolicy {
    pub schema_version: String,
    pub mode: String,
    pub source: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub job_id: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub provider: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub model: Option<String>,
    pub updated_at: String,
}

impl GoalStageTaskSemanticReviewPolicy {
    pub fn new(mode: &str, source: &str, job_id: Option<String>) -> Self {
        Self {
            schema_version: "goal_stage_task_semantic_review_policy.v1".to_string(),
            mode: normalize_stage_task_semantic_review_mode(mode),
            source: source.to_string(),
            job_id,
            provider: None,
            model: None,
            updated_at: timestamp_string(),
        }
    }

    pub fn with_route(mut self, provider: Option<String>, model: Option<String>) -> Self {
        self.provider = provider.filter(|value| !value.trim().is_empty());
        self.model = model.filter(|value| !value.trim().is_empty());
        self
    }
}

