impl GoalLoopClosureProjection {
    pub fn compact_line(&self) -> String {
        format!(
            "{} | mode {} | continue {} | next {} | reason {}",
            self.status,
            self.automation_mode.as_str(),
            self.should_continue,
            self.next_recommended_action,
            self.pause_reason.as_deref().unwrap_or("none")
        )
    }
}

impl GoalWatchHealthProjection {
    pub fn new(
        status: impl Into<String>,
        project_id: impl Into<String>,
        interval_ms: u64,
        ticks_completed: usize,
        stop_reason: impl Into<String>,
        watch_lock_path: impl Into<String>,
        last_tick: Option<serde_json::Value>,
    ) -> Self {
        let last_tick_status = last_tick
            .as_ref()
            .and_then(|tick| tick.get("status"))
            .and_then(|status| status.as_str())
            .map(str::to_string);
        let loop_closure = last_tick
            .as_ref()
            .and_then(|tick| tick.get("loop_closure"))
            .cloned()
            .and_then(|value| serde_json::from_value(value).ok());
        Self {
            schema_version: "goal_watch_health_projection.v1".to_string(),
            status: status.into(),
            project_id: project_id.into(),
            interval_ms,
            ticks_completed,
            stop_reason: stop_reason.into(),
            updated_at: timestamp_string(),
            watch_lock_path: watch_lock_path.into(),
            last_tick_status,
            loop_closure,
            last_tick,
        }
    }
}

pub fn loop_closure_projection(
    task_pool: &GoalTaskPoolSnapshot,
    recovery_governance: Option<&crate::routines::RoutineRecoveryGovernanceSummary>,
    dispatch_count: usize,
    accepted: bool,
) -> GoalLoopClosureProjection {
    let open_recovery_wake_count = recovery_governance
        .map(|summary| summary.pending_ingress_failure_count + summary.failed_trigger_count)
        .unwrap_or_default();
    let recovery_status = recovery_governance.map(|summary| summary.status.clone());
    let recovery_action =
        recovery_governance.map(|summary| summary.next_recommended_action.clone());
    let recovery_blocks_loop = recovery_governance
        .map(|summary| {
            summary.budget_exhausted_count > 0
                || summary.pending_ingress_failure_count > 0
                || summary.failed_trigger_count > 0
        })
        .unwrap_or(false);
    let summary = loop_closure_task_pool_summary(task_pool);
    let target_run = task_pool.target_run.as_ref();

    let (status, should_continue, pause_reason, next_action, instruction) = if let Some(recovery) =
        recovery_governance.filter(|_| recovery_blocks_loop)
    {
        let reason = if recovery.budget_exhausted_count > 0 {
            "routine_retry_budget_exhausted"
        } else if recovery.backoff_active_count > 0 {
            "routine_retry_backoff_active"
        } else {
            "routine_recovery_pending"
        };
        (
            if recovery.budget_exhausted_count > 0 {
                "needs_operator"
            } else {
                "recovering"
            },
            recovery.budget_exhausted_count == 0 && recovery.backoff_active_count == 0,
            Some(reason.to_string()),
            recovery.next_recommended_action.clone(),
            "Main agent should resolve routine recovery before advancing the goal loop."
                .to_string(),
        )
    } else if summary.blocked > 0 {
        (
                "blocked",
                false,
                Some("blocked_goal_task".to_string()),
                "resolve_blocked_goal_task".to_string(),
                "Main agent should inspect blocked task-pool items, open or resolve repair review, then tick again."
                    .to_string(),
            )
    } else if summary.needs_approval > 0 {
        (
                "needs_operator",
                false,
                Some("approval_required".to_string()),
                "request_or_apply_user_approval".to_string(),
                "Main agent should keep talking with the user and request or apply approval for waiting task-pool items."
                    .to_string(),
            )
    } else if summary.needs_review > 0 {
        let should_continue = matches!(task_pool.automation_mode, GoalAutomationMode::FullAuto);
        (
            if should_continue {
                "running"
            } else {
                "needs_operator"
            },
            should_continue,
            (!should_continue).then(|| "review_gate_open".to_string()),
            "open_or_complete_review_gate".to_string(),
            if should_continue {
                "Main agent should autonomously review worker output, record acceptance or repair, then continue the loop."
                    .to_string()
            } else {
                "Main agent should review worker output, record acceptance or repair, then continue the loop."
                    .to_string()
            },
        )
    } else if summary.running > 0 {
        (
                "waiting",
                false,
                Some("agent_team_running".to_string()),
                "wait_for_agent_task_output".to_string(),
                "Main agent should monitor running agent-team claims and accept finished manifests when available."
                    .to_string(),
            )
    } else if summary.ready_to_run > 0 {
        let should_continue = !matches!(
            task_pool.automation_mode,
            GoalAutomationMode::HumanInTheLoop
        );
        (
            "running",
            should_continue,
            (!should_continue).then(|| "human_approval_mode".to_string()),
            task_pool.next_recommended_action.clone(),
            if should_continue {
                "Main agent should dispatch the next allowed task from the existing goal task pool and keep the loop moving."
                        .to_string()
            } else {
                "Main agent should discuss the ready task with the user before dispatching agent-team work."
                        .to_string()
            },
        )
    } else if summary.waiting_on_dependencies > 0 {
        (
            "waiting",
            true,
            Some("waiting_on_dependency_evidence".to_string()),
            "advance_research_loop".to_string(),
            "Runtime is waiting for upstream agent-team evidence to be accepted before dispatching dependent board tasks."
                .to_string(),
        )
    } else if target_run
        .map(|run| run.total_steps > 0 && run.done_steps == run.total_steps)
        .unwrap_or(false)
    {
        (
            "completed",
            false,
            None,
            "summarize_goal_completion".to_string(),
            "Main agent should summarize completed evidence and ask whether to set the next goal."
                .to_string(),
        )
    } else if target_run
        .and_then(|run| run.current_step_id.as_ref())
        .is_some()
    {
        (
            "running",
            true,
            None,
            "continue_active_goal_run".to_string(),
            "Main agent should advance the current orchestration step and refresh the task pool."
                .to_string(),
        )
    } else {
        (
                "waiting",
                false,
                Some("goal_needs_refinement".to_string()),
                task_pool.next_recommended_action.clone(),
                "Main agent should discuss or refine the goal so the existing task pool can produce executable work."
                    .to_string(),
            )
    };

    GoalLoopClosureProjection {
        schema_version: "goal_loop_closure_projection.v1".to_string(),
        status: status.to_string(),
        automation_mode: task_pool.automation_mode,
        should_continue,
        next_recommended_action: next_action,
        main_agent_instruction: instruction,
        pause_reason,
        target_run_status: target_run.map(|run| run.status.clone()),
        target_run_progress_percent: target_run.map(|run| run.progress_percent),
        task_pool_summary: summary,
        recovery_governance_status: recovery_status,
        recovery_governance_action: recovery_action,
        open_recovery_wake_count,
        dispatch_count,
        accepted,
    }
}

fn loop_closure_task_pool_summary(task_pool: &GoalTaskPoolSnapshot) -> GoalTaskPoolSummary {
    if task_pool.entries.is_empty() {
        return task_pool.summary.clone();
    }
    let target_done = task_pool
        .target_run
        .as_ref()
        .map(|run| run.total_steps > 0 && run.done_steps == run.total_steps)
        .unwrap_or(false);
    let entries = task_pool
        .entries
        .iter()
        .filter(|entry| {
            if target_done {
                return entry.source.source_kind != "goal_run_automation_policy";
            }
            if entry.source.source_kind != "goal_run_automation_policy" {
                return true;
            }
            entry.title == "dispatch_agent_task"
                && entry.action_policy.as_deref() == Some("allowed")
        })
        .cloned()
        .collect::<Vec<_>>();
    summarize_task_pool(&entries)
}

