#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MissionFrameUpdate {
    pub project_max_goal: String,
    pub milestone_goal: String,
    pub current_implementation_goal: String,
    pub non_goals: Vec<String>,
    pub success_criteria: Vec<String>,
    pub evidence_refs: Vec<String>,
    pub risk_notes: Vec<String>,
    pub automation_mode: Option<GoalAutomationMode>,
}

#[derive(Debug)]
pub enum MissionFrameError {
    MissingRequired(String),
    Invalid(String),
    AgentStart(crate::agents::AgentError),
    ProviderExecution(crate::providers::ProviderExecutionError),
    Io(std::io::Error),
    Serde(serde_json::Error),
}

impl std::fmt::Display for MissionFrameError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::MissingRequired(field) => {
                write!(f, "missing required mission frame field: {field}")
            }
            Self::Invalid(reason) => write!(f, "{reason}"),
            Self::AgentStart(err) => write!(f, "{err}"),
            Self::ProviderExecution(err) => write!(f, "{err}"),
            Self::Io(err) => write!(f, "mission frame IO failed: {err}"),
            Self::Serde(err) => write!(f, "mission frame serialization failed: {err}"),
        }
    }
}

impl std::error::Error for MissionFrameError {}

impl From<std::io::Error> for MissionFrameError {
    fn from(value: std::io::Error) -> Self {
        Self::Io(value)
    }
}

impl From<serde_json::Error> for MissionFrameError {
    fn from(value: serde_json::Error) -> Self {
        Self::Serde(value)
    }
}

impl MissionFrame {
    pub fn projection(&self, frame_ref: String) -> MissionFrameProjection {
        MissionFrameProjection {
            mission_frame_ref: frame_ref,
            project_max_goal: self.project_max_goal.clone(),
            milestone_goal: self.milestone_goal.clone(),
            current_implementation_goal: self.current_implementation_goal.clone(),
            priority_rule: self.priority_rule.clone(),
            automation_mode: self.automation_mode,
        }
    }
}

pub fn frame_path(data_dir: &Path) -> PathBuf {
    data_dir.join("project_goals").join("mission_frame.json")
}

pub fn goal_watch_state_path(data_dir: &Path) -> PathBuf {
    data_dir.join("project_goals").join("goal_watch_state.json")
}

pub fn goal_watch_install_path(data_dir: &Path) -> PathBuf {
    data_dir
        .join("project_goals")
        .join("goal_watch_install.json")
}

pub fn goal_watch_cron_plan_path(data_dir: &Path) -> PathBuf {
    data_dir.join("project_goals").join("goal_watch.cron")
}

pub fn goal_watch_systemd_plan_path(data_dir: &Path) -> PathBuf {
    data_dir.join("project_goals").join("goal_watch.service")
}

pub fn relative_frame_ref(workspace_root: &Path) -> String {
    workspace_root
        .join(".pmcli")
        .join("project_goals")
        .join("mission_frame.json")
        .display()
        .to_string()
}

pub fn mission_frame_ref(data_dir: &Path) -> String {
    frame_path(data_dir).display().to_string()
}

pub fn status(
    data_dir: &Path,
    workspace_root: &Path,
    project_id: &str,
) -> Result<MissionFrameStatus, MissionFrameError> {
    let path = frame_path(data_dir);
    let mission_frame_ref = mission_frame_ref(data_dir);
    if !path.exists() {
        let task_pool = build_task_pool_snapshot(data_dir, workspace_root, project_id, None);
        return Ok(MissionFrameStatus {
            status: "missing".to_string(),
            project_id: project_id.to_string(),
            mission_frame_ref,
            mission_frame: None,
            projection: None,
            stage_decision_policy: stage_decision_policy_projection(
                None,
                task_pool.automation_mode,
            ),
            watch_plan: watch_plan_projection(
                project_id,
                workspace_root,
                task_pool.automation_mode,
            ),
            task_pool,
            warnings: vec!["mission frame has not been created".to_string()],
        });
    }

    let frame = read_frame(data_dir)?;
    validate_project_id(project_id, &frame)?;
    let projection = frame.projection(mission_frame_ref.clone());
    let task_pool = build_task_pool_snapshot(data_dir, workspace_root, project_id, Some(&frame));
    let stage_decision_policy =
        stage_decision_policy_projection(active_goal_run(data_dir).as_ref(), frame.automation_mode);
    let watch_plan = watch_plan_projection(project_id, workspace_root, frame.automation_mode);
    Ok(MissionFrameStatus {
        status: "active".to_string(),
        project_id: project_id.to_string(),
        mission_frame_ref,
        mission_frame: Some(frame),
        projection: Some(projection),
        stage_decision_policy,
        watch_plan,
        task_pool,
        warnings: Vec::new(),
    })
}

pub fn load_goal_watch_health(data_dir: &Path) -> Option<GoalWatchHealthProjection> {
    serde_json::from_str(&fs::read_to_string(goal_watch_state_path(data_dir)).ok()?).ok()
}

fn active_goal_run(data_dir: &Path) -> Option<crate::orchestration::OrchestrationRun> {
    crate::orchestration::load_active_run(data_dir)
        .ok()
        .flatten()
}

pub fn save_goal_watch_health(
    data_dir: &Path,
    health: &GoalWatchHealthProjection,
) -> Result<(), MissionFrameError> {
    write_json_atomic(&goal_watch_state_path(data_dir), health)
}

pub fn install_goal_watch_plan(
    data_dir: &Path,
    project_id: &str,
    workspace_root: &Path,
    automation_mode: GoalAutomationMode,
    executable_path: &Path,
    options: GoalWatchInstallOptions,
) -> Result<GoalWatchInstallResult, MissionFrameError> {
    let plan = watch_plan_projection(project_id, workspace_root, automation_mode);
    let record_path = goal_watch_install_path(data_dir);
    let cron_plan_path = goal_watch_cron_plan_path(data_dir);
    let systemd_plan_path = goal_watch_systemd_plan_path(data_dir);
    let writes_project_files = options.writes_project_files();
    let mut record = build_goal_watch_install_record(
        project_id,
        workspace_root,
        automation_mode,
        executable_path,
        &record_path,
        &cron_plan_path,
        &systemd_plan_path,
        &plan,
        if writes_project_files {
            "installed"
        } else {
            "planned"
        },
    );
    let files_planned = vec![
        record_path.display().to_string(),
        cron_plan_path.display().to_string(),
        systemd_plan_path.display().to_string(),
    ];
    let mut files_written = Vec::new();
    let mut system_actions = Vec::new();
    let mut system_install = None;

    if writes_project_files {
        write_text_atomic(
            &cron_plan_path,
            &render_goal_watch_cron_plan(&record, &plan)?,
        )?;
        files_written.push(cron_plan_path.display().to_string());
        write_text_atomic(
            &systemd_plan_path,
            &render_goal_watch_systemd_plan(&record, &plan)?,
        )?;
        files_written.push(systemd_plan_path.display().to_string());

        if let Some(target) = options.apply_target {
            let applied_artifact_path = system_artifact_path(data_dir, &record, target)?;
            record.install_mode = target.as_str().to_string();
            record.applied_runner = Some(target.as_str().to_string());
            record.applied_at = Some(timestamp_string());
            record.applied_artifact_path = Some(applied_artifact_path);
            let applied = apply_goal_watch_system_install(data_dir, &record, &plan, target)?;
            system_actions = applied.0;
            system_install = Some(applied.1);
        }

        write_json_atomic(&record_path, &record)?;
        files_written.push(record_path.display().to_string());
    }

    Ok(GoalWatchInstallResult {
        schema_version: "goal_watch_install_result.v1".to_string(),
        status: install_result_status(options),
        project_id: project_id.to_string(),
        dry_run: !writes_project_files,
        write_files: writes_project_files,
        record_path: record_path.display().to_string(),
        cron_plan_path: cron_plan_path.display().to_string(),
        systemd_plan_path: systemd_plan_path.display().to_string(),
        files_planned,
        files_written,
        plan,
        system_actions,
        system_install,
        install_record: Some(record),
        next_recommended_action: install_next_action(options),
    })
}

pub fn goal_watch_install_status(
    data_dir: &Path,
    project_id: &str,
    workspace_root: &Path,
    automation_mode: GoalAutomationMode,
) -> Result<GoalWatchInstallStatus, MissionFrameError> {
    let plan = watch_plan_projection(project_id, workspace_root, automation_mode);
    let record_path = goal_watch_install_path(data_dir);
    let cron_plan_path = goal_watch_cron_plan_path(data_dir);
    let systemd_plan_path = goal_watch_systemd_plan_path(data_dir);
    let health = load_goal_watch_health(data_dir);
    let install_record = if record_path.exists() {
        Some(read_goal_watch_install_record(data_dir)?)
    } else {
        None
    };

    let mut warnings = Vec::new();
    let (status, installed, next_recommended_action) = match install_record.as_ref() {
        None => (
            "not_installed".to_string(),
            false,
            "install_watch_plan".to_string(),
        ),
        Some(record)
            if record.project_id != project_id
                || record.workspace_root != workspace_root.display().to_string()
                || record.status != "installed" =>
        {
            warnings.push("install record does not match this project status".to_string());
            (
                "stale_install_record".to_string(),
                false,
                "uninstall_stale_plan".to_string(),
            )
        }
        Some(_) if health.is_none() => {
            ("installed".to_string(), true, "run_goals_watch".to_string())
        }
        Some(_) => (
            "installed".to_string(),
            true,
            "inspect_watch_health".to_string(),
        ),
    };

    Ok(GoalWatchInstallStatus {
        schema_version: "goal_watch_install_status.v1".to_string(),
        status,
        project_id: project_id.to_string(),
        installed,
        record_path: record_path.display().to_string(),
        cron_plan_path: cron_plan_path.display().to_string(),
        systemd_plan_path: systemd_plan_path.display().to_string(),
        plan,
        system_install: install_record
            .as_ref()
            .and_then(goal_watch_record_system_status),
        install_record,
        health,
        next_recommended_action,
        warnings,
    })
}

pub fn uninstall_goal_watch_plan(
    data_dir: &Path,
    project_id: &str,
    options: GoalWatchInstallOptions,
) -> Result<GoalWatchUninstallResult, MissionFrameError> {
    let record_path = goal_watch_install_path(data_dir);
    let cron_plan_path = goal_watch_cron_plan_path(data_dir);
    let systemd_plan_path = goal_watch_systemd_plan_path(data_dir);
    let previous_record = if record_path.exists() {
        Some(read_goal_watch_install_record(data_dir)?)
    } else {
        None
    };
    let files_planned_for_removal = vec![
        record_path.display().to_string(),
        cron_plan_path.display().to_string(),
        systemd_plan_path.display().to_string(),
    ];
    let mut files_removed = Vec::new();
    let mut system_actions = Vec::new();
    let mut system_install = None;

    if let Some(target) = options.apply_target {
        let removed = remove_goal_watch_system_install(
            data_dir,
            project_id,
            previous_record.as_ref(),
            target,
        )?;
        system_actions = removed.0;
        system_install = Some(removed.1);
    }

    if options.writes_project_files() {
        for path in [&record_path, &cron_plan_path, &systemd_plan_path] {
            if path.exists() {
                fs::remove_file(path)?;
                files_removed.push(path.display().to_string());
            }
        }
    }

    Ok(GoalWatchUninstallResult {
        schema_version: "goal_watch_uninstall_result.v1".to_string(),
        status: uninstall_result_status(options),
        project_id: project_id.to_string(),
        dry_run: !options.writes_project_files(),
        write_files: options.writes_project_files(),
        record_path: record_path.display().to_string(),
        cron_plan_path: cron_plan_path.display().to_string(),
        systemd_plan_path: systemd_plan_path.display().to_string(),
        files_planned_for_removal,
        files_removed,
        system_actions,
        system_install,
        previous_record,
        next_recommended_action: uninstall_next_action(options),
    })
}

pub fn watch_plan_projection(
    project_id: &str,
    workspace_root: &Path,
    automation_mode: GoalAutomationMode,
) -> GoalWatchPlanProjection {
    let interval_ms = match automation_mode {
        GoalAutomationMode::HumanInTheLoop => 15_000,
        GoalAutomationMode::HighAutonomy => 5_000,
        GoalAutomationMode::FullAuto => 2_500,
    };
    let workspace = workspace_root.display().to_string();
    let command = vec![
        "research-cli".to_string(),
        "goals".to_string(),
        "watch".to_string(),
        "--interval-ms".to_string(),
        interval_ms.to_string(),
        "--trigger-kind".to_string(),
        "schedule".to_string(),
        "--json".to_string(),
    ];
    let command_line = command.join(" ");
    let cron_line = format!(
        "* * * * * cd {} && {}",
        shell_quote(&workspace),
        command_line
    );
    let unit_name = format!(
        "research-cli-goals-watch-{}.service",
        sanitize_file_component(project_id)
    );
    GoalWatchPlanProjection {
        schema_version: "goal_watch_plan_projection.v1".to_string(),
        status: "planned".to_string(),
        project_id: project_id.to_string(),
        workspace_root: workspace,
        recommended_runner: "local_private_schedule".to_string(),
        install_mode: "dry_run_plan_only".to_string(),
        interval_ms,
        command,
        cron_expression: "* * * * *".to_string(),
        cron_line,
        systemd_user_unit: unit_name,
        status_command: vec![
            "research-cli".to_string(),
            "goals".to_string(),
            "status".to_string(),
            "--json".to_string(),
        ],
        main_agent_instruction:
            "Use this local private plan to keep goals watch running; install it only with explicit operator approval."
                .to_string(),
    }
}

fn read_goal_watch_install_record(
    data_dir: &Path,
) -> Result<GoalWatchInstallRecord, MissionFrameError> {
    let contents = fs::read_to_string(goal_watch_install_path(data_dir))?;
    Ok(serde_json::from_str(&contents)?)
}

fn build_goal_watch_install_record(
    project_id: &str,
    workspace_root: &Path,
    automation_mode: GoalAutomationMode,
    executable_path: &Path,
    record_path: &Path,
    cron_plan_path: &Path,
    systemd_plan_path: &Path,
    plan: &GoalWatchPlanProjection,
    status: &str,
) -> GoalWatchInstallRecord {
    let executable = executable_path.display().to_string();
    let command = vec![
        executable.clone(),
        "goals".to_string(),
        "watch".to_string(),
        "--interval-ms".to_string(),
        plan.interval_ms.to_string(),
        "--trigger-kind".to_string(),
        "schedule".to_string(),
        "--json".to_string(),
    ];
    let cron_command = vec![
        executable.clone(),
        "goals".to_string(),
        "watch".to_string(),
        "--once".to_string(),
        "--interval-ms".to_string(),
        plan.interval_ms.to_string(),
        "--trigger-kind".to_string(),
        "schedule".to_string(),
        "--json".to_string(),
    ];
    let workspace = workspace_root.display().to_string();
    let cron_line = format!(
        "{} cd {} && {}",
        plan.cron_expression,
        shell_quote(&workspace),
        shell_command(&cron_command)
    );
    GoalWatchInstallRecord {
        schema_version: "goal_watch_install_record.v1".to_string(),
        status: status.to_string(),
        project_id: project_id.to_string(),
        workspace_root: workspace,
        automation_mode,
        install_mode: "project_plan_files_only".to_string(),
        installed_at: timestamp_string(),
        executable_path: executable,
        record_path: record_path.display().to_string(),
        cron_plan_path: cron_plan_path.display().to_string(),
        systemd_plan_path: systemd_plan_path.display().to_string(),
        command,
        cron_line,
        systemd_user_unit: plan.systemd_user_unit.clone(),
        system_marker: goal_watch_system_marker(project_id),
        applied_runner: None,
        applied_at: None,
        applied_artifact_path: None,
        next_recommended_action: if status == "installed" {
            "run_goals_watch_status".to_string()
        } else {
            "rerun_with_write_files_to_store_project_plan".to_string()
        },
    }
}

fn render_goal_watch_cron_plan(
    record: &GoalWatchInstallRecord,
    _plan: &GoalWatchPlanProjection,
) -> Result<String, MissionFrameError> {
    Ok(format!(
        concat!(
            "# Research CLI goals watch cron plan\n",
            "# Project: {project_id}\n",
            "# Workspace: {workspace_root}\n",
            "# This file is a project-local plan only. It has not been installed into crontab.\n",
            "# Review it before applying with your own crontab tooling.\n",
            "{cron_line}\n"
        ),
        project_id = record.project_id,
        workspace_root = record.workspace_root,
        cron_line = record.cron_line,
    ))
}

fn render_goal_watch_systemd_plan(
    record: &GoalWatchInstallRecord,
    _plan: &GoalWatchPlanProjection,
) -> Result<String, MissionFrameError> {
    let command_line = shell_command(&record.command);
    let workspace = shell_quote(&record.workspace_root);
    Ok(format!(
        concat!(
            "# Research CLI goals watch systemd user-service plan\n",
            "# This file is a project-local plan only. It has not been installed with systemctl.\n",
            "[Unit]\n",
            "Description=Research CLI goals watch for {project_id}\n",
            "After=default.target\n",
            "\n",
            "[Service]\n",
            "Type=simple\n",
            "ExecStart=/bin/sh -lc {exec_start}\n",
            "Restart=on-failure\n",
            "RestartSec=10\n",
            "\n",
            "[Install]\n",
            "WantedBy=default.target\n"
        ),
        project_id = sanitize_file_component(&record.project_id),
        exec_start = shell_quote(&format!("cd {workspace} && {command_line}")),
    ))
}

fn shell_command(command: &[String]) -> String {
    command
        .iter()
        .map(|part| shell_quote(part))
        .collect::<Vec<_>>()
        .join(" ")
}

fn install_result_status(options: GoalWatchInstallOptions) -> String {
    match options.apply_target {
        Some(target) => format!("installed_{}", target.as_str()),
        None if options.write_files => "installed".to_string(),
        None => "dry_run".to_string(),
    }
}

fn uninstall_result_status(options: GoalWatchInstallOptions) -> String {
    match options.apply_target {
        Some(target) => format!("uninstalled_{}", target.as_str()),
        None if options.write_files => "uninstalled".to_string(),
        None => "dry_run".to_string(),
    }
}

fn install_next_action(options: GoalWatchInstallOptions) -> String {
    match options.apply_target {
        Some(_) => "run_goals_watch_status".to_string(),
        None if options.write_files => "run_goals_watch_status".to_string(),
        None => "rerun_with_write_files_or_apply_target".to_string(),
    }
}

fn uninstall_next_action(options: GoalWatchInstallOptions) -> String {
    match options.apply_target {
        Some(_) => "run_goals_watch_status".to_string(),
        None if options.write_files => "run_goals_watch_status".to_string(),
        None => "rerun_with_write_files_or_apply_target".to_string(),
    }
}

fn goal_watch_record_system_status(
    record: &GoalWatchInstallRecord,
) -> Option<GoalWatchSystemInstallStatus> {
    let runner = record.applied_runner.clone()?;
    Some(GoalWatchSystemInstallStatus {
        schema_version: "goal_watch_system_install_status.v1".to_string(),
        runner,
        status: "recorded".to_string(),
        installed: record.status == "installed",
        marker: record.system_marker.clone(),
        artifact_path: record.applied_artifact_path.clone(),
        next_recommended_action: "inspect_system_scheduler_if_needed".to_string(),
    })
}

fn system_artifact_path(
    data_dir: &Path,
    record: &GoalWatchInstallRecord,
    target: GoalWatchInstallApplyTarget,
) -> Result<String, MissionFrameError> {
    match target {
        GoalWatchInstallApplyTarget::Cron => {
            Ok(crontab_artifact_path(data_dir).display().to_string())
        }
        GoalWatchInstallApplyTarget::SystemdUser => {
            Ok(systemd_user_unit_path(record)?.display().to_string())
        }
    }
}

fn apply_goal_watch_system_install(
    data_dir: &Path,
    record: &GoalWatchInstallRecord,
    plan: &GoalWatchPlanProjection,
    target: GoalWatchInstallApplyTarget,
) -> Result<(Vec<GoalWatchSystemAction>, GoalWatchSystemInstallStatus), MissionFrameError> {
    match target {
        GoalWatchInstallApplyTarget::Cron => apply_goal_watch_cron(data_dir, record),
        GoalWatchInstallApplyTarget::SystemdUser => apply_goal_watch_systemd(record, plan),
    }
}

fn remove_goal_watch_system_install(
    data_dir: &Path,
    project_id: &str,
    record: Option<&GoalWatchInstallRecord>,
    target: GoalWatchInstallApplyTarget,
) -> Result<(Vec<GoalWatchSystemAction>, GoalWatchSystemInstallStatus), MissionFrameError> {
    match target {
        GoalWatchInstallApplyTarget::Cron => remove_goal_watch_cron(data_dir, project_id, record),
        GoalWatchInstallApplyTarget::SystemdUser => remove_goal_watch_systemd(project_id, record),
    }
}

fn apply_goal_watch_cron(
    data_dir: &Path,
    record: &GoalWatchInstallRecord,
) -> Result<(Vec<GoalWatchSystemAction>, GoalWatchSystemInstallStatus), MissionFrameError> {
    let current = read_user_crontab()?;
    let updated = upsert_marked_block(&current.0, &record.system_marker, &record.cron_line);
    let write_action = write_user_crontab(data_dir, &updated)?;
    let artifact_path = current.1.or_else(|| write_action.artifact_path.clone());
    Ok((
        vec![write_action],
        GoalWatchSystemInstallStatus {
            schema_version: "goal_watch_system_install_status.v1".to_string(),
            runner: GoalWatchInstallApplyTarget::Cron.as_str().to_string(),
            status: "installed".to_string(),
            installed: true,
            marker: record.system_marker.clone(),
            artifact_path,
            next_recommended_action: "run_goals_watch_status".to_string(),
        },
    ))
}

fn remove_goal_watch_cron(
    data_dir: &Path,
    project_id: &str,
    record: Option<&GoalWatchInstallRecord>,
) -> Result<(Vec<GoalWatchSystemAction>, GoalWatchSystemInstallStatus), MissionFrameError> {
    let marker = record
        .map(|record| record.system_marker.clone())
        .unwrap_or_else(|| goal_watch_system_marker(project_id));
    let current = read_user_crontab()?;
    let updated = remove_marked_block(&current.0, &marker);
    let write_action = write_user_crontab(data_dir, &updated)?;
    let artifact_path = current.1.or_else(|| write_action.artifact_path.clone());
    Ok((
        vec![write_action],
        GoalWatchSystemInstallStatus {
            schema_version: "goal_watch_system_install_status.v1".to_string(),
            runner: GoalWatchInstallApplyTarget::Cron.as_str().to_string(),
            status: "uninstalled".to_string(),
            installed: false,
            marker,
            artifact_path,
            next_recommended_action: "run_goals_watch_status".to_string(),
        },
    ))
}

fn read_user_crontab() -> Result<(String, Option<String>), MissionFrameError> {
    if let Ok(path) = env::var("RESEARCH_CLI_GOAL_WATCH_CRONTAB_FILE") {
        let path = PathBuf::from(path);
        let contents = fs::read_to_string(&path).unwrap_or_default();
        return Ok((contents, Some(path.display().to_string())));
    }

    let crontab =
        env::var("RESEARCH_CLI_GOAL_WATCH_CRONTAB_BIN").unwrap_or_else(|_| "crontab".to_string());
    let output = Command::new(&crontab).arg("-l").output()?;
    if output.status.success() {
        return Ok((String::from_utf8_lossy(&output.stdout).to_string(), None));
    }
    Ok((String::new(), None))
}

fn write_user_crontab(
    data_dir: &Path,
    contents: &str,
) -> Result<GoalWatchSystemAction, MissionFrameError> {
    if let Ok(path) = env::var("RESEARCH_CLI_GOAL_WATCH_CRONTAB_FILE") {
        let path = PathBuf::from(path);
        write_text_atomic(&path, contents)?;
        return Ok(GoalWatchSystemAction {
            action: "write_fake_crontab".to_string(),
            status: "ok".to_string(),
            command: vec!["fake-crontab".to_string(), path.display().to_string()],
            artifact_path: Some(path.display().to_string()),
            stdout: None,
            stderr: None,
        });
    }

    let apply_path = data_dir
        .join("project_goals")
        .join("goal_watch.crontab.apply");
    write_text_atomic(&apply_path, contents)?;
    let crontab =
        env::var("RESEARCH_CLI_GOAL_WATCH_CRONTAB_BIN").unwrap_or_else(|_| "crontab".to_string());
    let output = Command::new(&crontab).arg(&apply_path).output()?;
    let action = GoalWatchSystemAction {
        action: "write_user_crontab".to_string(),
        status: if output.status.success() {
            "ok".to_string()
        } else {
            "failed".to_string()
        },
        command: vec![crontab, apply_path.display().to_string()],
        artifact_path: Some(apply_path.display().to_string()),
        stdout: Some(String::from_utf8_lossy(&output.stdout).to_string()),
        stderr: Some(String::from_utf8_lossy(&output.stderr).to_string()),
    };
    if action.status == "ok" {
        Ok(action)
    } else {
        Err(MissionFrameError::Invalid(format!(
            "crontab install failed: {}",
            action.stderr.as_deref().unwrap_or("unknown error")
        )))
    }
}

fn crontab_artifact_path(data_dir: &Path) -> PathBuf {
    env::var("RESEARCH_CLI_GOAL_WATCH_CRONTAB_FILE")
        .map(PathBuf::from)
        .unwrap_or_else(|_| {
            data_dir
                .join("project_goals")
                .join("goal_watch.crontab.apply")
        })
}

fn apply_goal_watch_systemd(
    record: &GoalWatchInstallRecord,
    plan: &GoalWatchPlanProjection,
) -> Result<(Vec<GoalWatchSystemAction>, GoalWatchSystemInstallStatus), MissionFrameError> {
    let unit_path = systemd_user_unit_path(record)?;
    write_text_atomic(&unit_path, &render_goal_watch_systemd_plan(record, plan)?)?;
    let actions = vec![
        run_systemctl_user(&["daemon-reload"])?,
        run_systemctl_user(&["enable", "--now", &record.systemd_user_unit])?,
    ];
    Ok((
        actions,
        GoalWatchSystemInstallStatus {
            schema_version: "goal_watch_system_install_status.v1".to_string(),
            runner: GoalWatchInstallApplyTarget::SystemdUser
                .as_str()
                .to_string(),
            status: "installed".to_string(),
            installed: true,
            marker: record.system_marker.clone(),
            artifact_path: Some(unit_path.display().to_string()),
            next_recommended_action: "run_goals_watch_status".to_string(),
        },
    ))
}

fn remove_goal_watch_systemd(
    project_id: &str,
    record: Option<&GoalWatchInstallRecord>,
) -> Result<(Vec<GoalWatchSystemAction>, GoalWatchSystemInstallStatus), MissionFrameError> {
    let unit_name = record
        .map(|record| record.systemd_user_unit.clone())
        .unwrap_or_else(|| {
            format!(
                "research-cli-goals-watch-{}.service",
                sanitize_file_component(project_id)
            )
        });
    let marker = record
        .map(|record| record.system_marker.clone())
        .unwrap_or_else(|| goal_watch_system_marker(project_id));
    let unit_path = record
        .and_then(|record| record.applied_artifact_path.as_ref().map(PathBuf::from))
        .or_else(|| {
            record
                .map(systemd_user_unit_path)
                .transpose()
                .ok()
                .flatten()
        })
        .unwrap_or_else(|| systemd_user_dir().join(&unit_name));
    let mut actions = Vec::new();
    actions.push(run_systemctl_user(&["disable", "--now", &unit_name])?);
    if unit_path.exists() {
        fs::remove_file(&unit_path)?;
        actions.push(GoalWatchSystemAction {
            action: "remove_systemd_user_unit".to_string(),
            status: "ok".to_string(),
            command: vec!["rm".to_string(), unit_path.display().to_string()],
            artifact_path: Some(unit_path.display().to_string()),
            stdout: None,
            stderr: None,
        });
    }
    actions.push(run_systemctl_user(&["daemon-reload"])?);
    Ok((
        actions,
        GoalWatchSystemInstallStatus {
            schema_version: "goal_watch_system_install_status.v1".to_string(),
            runner: GoalWatchInstallApplyTarget::SystemdUser
                .as_str()
                .to_string(),
            status: "uninstalled".to_string(),
            installed: false,
            marker,
            artifact_path: Some(unit_path.display().to_string()),
            next_recommended_action: "run_goals_watch_status".to_string(),
        },
    ))
}

fn run_systemctl_user(args: &[&str]) -> Result<GoalWatchSystemAction, MissionFrameError> {
    let command = std::iter::once("systemctl".to_string())
        .chain(std::iter::once("--user".to_string()))
        .chain(args.iter().map(|arg| (*arg).to_string()))
        .collect::<Vec<_>>();

    if let Ok(log_path) = env::var("RESEARCH_CLI_GOAL_WATCH_SYSTEMCTL_LOG") {
        let log_path = PathBuf::from(log_path);
        if let Some(parent) = log_path.parent() {
            fs::create_dir_all(parent)?;
        }
        let mut file = fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(&log_path)?;
        writeln!(file, "{}", command.join(" "))?;
        return Ok(GoalWatchSystemAction {
            action: "record_fake_systemctl".to_string(),
            status: "ok".to_string(),
            command,
            artifact_path: Some(log_path.display().to_string()),
            stdout: None,
            stderr: None,
        });
    }

    let output = Command::new("systemctl")
        .arg("--user")
        .args(args)
        .output()?;
    let action = GoalWatchSystemAction {
        action: "run_systemctl_user".to_string(),
        status: if output.status.success() {
            "ok".to_string()
        } else {
            "failed".to_string()
        },
        command,
        artifact_path: None,
        stdout: Some(String::from_utf8_lossy(&output.stdout).to_string()),
        stderr: Some(String::from_utf8_lossy(&output.stderr).to_string()),
    };
    if action.status == "ok" {
        Ok(action)
    } else {
        Err(MissionFrameError::Invalid(format!(
            "systemctl --user failed: {}",
            action.stderr.as_deref().unwrap_or("unknown error")
        )))
    }
}

fn systemd_user_unit_path(record: &GoalWatchInstallRecord) -> Result<PathBuf, MissionFrameError> {
    Ok(systemd_user_dir().join(&record.systemd_user_unit))
}

fn systemd_user_dir() -> PathBuf {
    if let Ok(path) = env::var("RESEARCH_CLI_GOAL_WATCH_SYSTEMD_USER_DIR") {
        return PathBuf::from(path);
    }
    if let Ok(path) = env::var("XDG_CONFIG_HOME") {
        return PathBuf::from(path).join("systemd").join("user");
    }
    env::var("HOME")
        .map(PathBuf::from)
        .unwrap_or_else(|_| PathBuf::from("."))
        .join(".config")
        .join("systemd")
        .join("user")
}

fn goal_watch_system_marker(project_id: &str) -> String {
    format!(
        "research-cli-goals-watch-{}",
        sanitize_file_component(project_id)
    )
}

fn upsert_marked_block(contents: &str, marker: &str, body_line: &str) -> String {
    let mut stripped = remove_marked_block(contents, marker);
    if !stripped.is_empty() && !stripped.ends_with('\n') {
        stripped.push('\n');
    }
    stripped.push_str(&format!("# BEGIN {marker}\n{body_line}\n# END {marker}\n"));
    stripped
}

fn remove_marked_block(contents: &str, marker: &str) -> String {
    let begin = format!("# BEGIN {marker}");
    let end = format!("# END {marker}");
    let mut output = Vec::new();
    let mut skipping = false;
    for line in contents.lines() {
        if line.trim() == begin {
            skipping = true;
            continue;
        }
        if skipping && line.trim() == end {
            skipping = false;
            continue;
        }
        if !skipping {
            output.push(line);
        }
    }
    let mut rendered = output.join("\n");
    if !rendered.is_empty() {
        rendered.push('\n');
    }
    rendered
}

pub fn stage_decision_policy_projection(
    run: Option<&crate::orchestration::OrchestrationRun>,
    automation_mode: GoalAutomationMode,
) -> GoalStageDecisionPolicyProjection {
    let policy =
        crate::orchestration::GoalRunAutomationPolicyProjection::from_mode(automation_mode);
    let action_policy = policy
        .action_policy("advance_stage")
        .unwrap_or("requires_approval");
    let decisions = run
        .map(goal_research_stage_decisions_needed)
        .unwrap_or_default()
        .into_iter()
        .map(|decision| {
            let (risk_class, effective_policy, action_id, reason) =
                if action_policy == "allowed" && matches!(automation_mode, GoalAutomationMode::FullAuto)
                {
                    (
                        "low_risk_continue",
                        "auto_approvable",
                        "advance_research_loop",
                        "full-auto may approve the low-risk continue-stage decision during goal advance",
                    )
                } else if action_policy == "hard_blocked" {
                    (
                        "blocked",
                        "review_or_recovery_required",
                        "inspect_recovery_governance",
                        "stage decision is blocked by the current automation policy",
                    )
                } else {
                    (
                        "operator_gate",
                        "operator_approval_required",
                        "decide_research_stage",
                        "operator should approve, reject, or revise the research stage decision",
                    )
                };
            GoalStageDecisionPolicyItem {
                stage_execution_id: decision.stage_execution_id,
                agent_id: decision.agent_id,
                risk_class: risk_class.to_string(),
                policy: effective_policy.to_string(),
                operation: GOAL_STAGE_DECISION_RECOMMENDED_OPERATION.to_string(),
                recommended_action_id: action_id.to_string(),
                reason: reason.to_string(),
            }
        })
        .collect::<Vec<_>>();
    let auto_approvable_count = decisions
        .iter()
        .filter(|decision| decision.policy == "auto_approvable")
        .count();
    let operator_gate_count = decisions
        .iter()
        .filter(|decision| decision.policy == "operator_approval_required")
        .count();
    let review_or_recovery_count = decisions
        .iter()
        .filter(|decision| decision.policy == "review_or_recovery_required")
        .count();
    let (status, next_recommended_action, instruction) = if review_or_recovery_count > 0 {
        (
            "review_or_recovery_required",
            "inspect_recovery_governance",
            "Resolve review or recovery gates before changing research stage.",
        )
    } else if operator_gate_count > 0 {
        (
            "operator_gate",
            "decide_research_stage",
            "Ask the operator to approve, reject, or revise pending research stage decisions.",
        )
    } else if auto_approvable_count > 0 {
        (
            "auto_approvable",
            "advance_research_loop",
            "Continue the goal loop; full-auto can approve low-risk stage continuation.",
        )
    } else {
        (
            "clear",
            "advance_research_loop",
            "No stage decision is pending; continue the research loop when work is available.",
        )
    };
    GoalStageDecisionPolicyProjection {
        schema_version: "goal_stage_decision_policy_projection.v1".to_string(),
        automation_mode,
        status: status.to_string(),
        auto_approvable_count,
        operator_gate_count,
        review_or_recovery_count,
        next_recommended_action: next_recommended_action.to_string(),
        main_agent_instruction: instruction.to_string(),
        decisions,
    }
}

pub fn task_pool_maintenance_projection(
    task_pool: &GoalTaskPoolSnapshot,
    loop_closure: Option<&GoalLoopClosureProjection>,
) -> GoalTaskPoolMaintenanceProjection {
    let summary = task_pool.summary.clone();
    let (status, recommended_action_id, instruction) = if summary.blocked > 0 {
        (
            "blocked",
            "inspect_recovery_governance",
            "Resolve blocked task-pool items or repair reviews before continuing.",
        )
    } else if summary.needs_approval > 0 {
        (
            "needs_approval",
            "open_research",
            "Ask the operator to approve or revise gated research work.",
        )
    } else if summary.needs_review > 0 {
        (
            "needs_review",
            "open_research",
            "Complete pending review or stage-decision items before dispatching more work.",
        )
    } else if summary.ready_to_run > 0 {
        (
            "ready_to_run",
            "advance_research_loop",
            "Advance the research loop to dispatch the next allowed goal task.",
        )
    } else if summary.running > 0 {
        (
            "running",
            "open_research",
            "Wait for active agent claims or inspect the running work.",
        )
    } else if loop_closure
        .map(|closure| closure.status.as_str() == "completed")
        .unwrap_or(false)
    {
        (
            "completed",
            "open_research",
            "The current goal loop is complete; inspect the result and set the next goal.",
        )
    } else {
        (
            "waiting",
            "advance_research_loop",
            "Advance or refine the current goal so the task pool can produce the next action.",
        )
    };
    GoalTaskPoolMaintenanceProjection {
        schema_version: "goal_task_pool_maintenance_projection.v1".to_string(),
        status: status.to_string(),
        automation_mode: task_pool.automation_mode,
        task_pool_summary: summary.clone(),
        next_recommended_action: task_pool.next_recommended_action.clone(),
        recommended_action_id: recommended_action_id.to_string(),
        main_agent_instruction: loop_closure
            .map(|closure| closure.main_agent_instruction.clone())
            .unwrap_or_else(|| instruction.to_string()),
        blocked_count: summary.blocked,
        needs_approval_count: summary.needs_approval,
        needs_review_count: summary.needs_review,
        ready_to_run_count: summary.ready_to_run,
        running_count: summary.running,
    }
}

pub fn projection(
    data_dir: &Path,
    _workspace_root: &Path,
    project_id: &str,
) -> Result<Option<MissionFrameProjection>, MissionFrameError> {
    let path = frame_path(data_dir);
    if !path.exists() {
        return Ok(None);
    }
    let frame = read_frame(data_dir)?;
    validate_project_id(project_id, &frame)?;
    Ok(Some(frame.projection(mission_frame_ref(data_dir))))
}

pub fn set(
    data_dir: &Path,
    workspace_root: &Path,
    project_id: &str,
    update: MissionFrameUpdate,
) -> Result<MissionFrameStatus, MissionFrameError> {
    validate_required("project_max_goal", &update.project_max_goal)?;
    validate_required("milestone_goal", &update.milestone_goal)?;
    validate_required(
        "current_implementation_goal",
        &update.current_implementation_goal,
    )?;

    let existing_frame = if frame_path(data_dir).exists() {
        Some(read_frame(data_dir)?)
    } else {
        None
    };
    let next_version = existing_frame
        .as_ref()
        .map(|frame| frame.version + 1)
        .unwrap_or(1);
    let frame = MissionFrame {
        frame_id: "mission_frame".to_string(),
        version: next_version,
        project_id: project_id.to_string(),
        project_max_goal: update.project_max_goal,
        milestone_goal: update.milestone_goal,
        current_implementation_goal: update.current_implementation_goal,
        priority_rule: PRIORITY_RULE.to_string(),
        non_goals: update.non_goals,
        success_criteria: update.success_criteria,
        evidence_refs: update.evidence_refs,
        risk_notes: update.risk_notes,
        automation_mode: update
            .automation_mode
            .or_else(|| existing_frame.as_ref().map(|frame| frame.automation_mode))
            .unwrap_or_default(),
        updated_at: timestamp_string(),
    };
    write_frame(data_dir, &frame)?;
    status(data_dir, workspace_root, project_id)
}

fn build_task_pool_snapshot(
    data_dir: &Path,
    workspace_root: &Path,
    project_id: &str,
    frame: Option<&MissionFrame>,
) -> GoalTaskPoolSnapshot {
    let automation_mode = frame.map(|frame| frame.automation_mode).unwrap_or_default();
    let active_run = crate::orchestration::load_active_run(data_dir)
        .ok()
        .flatten();
    let automation_policy = active_run
        .as_ref()
        .map(|run| run.automation_policy_projection())
        .or_else(|| {
            frame.map(|frame| {
                crate::orchestration::GoalRunAutomationPolicyProjection::from_mode(
                    frame.automation_mode,
                )
            })
        });
    let research_status = crate::research::status(data_dir, project_id).ok();
    let agents = crate::agents::list(data_dir).ok();
    let reviews = crate::reviews::list(data_dir, None, None).ok();
    let projectops = crate::projectops::status(data_dir, project_id).ok();
    let active_run_progress = active_run.as_ref().map(|run| run.progress_projection());
    let target_run = active_run_progress
        .as_ref()
        .map(GoalTargetRunSnapshot::from_progress);
    let active_goal_agent_ids = active_run
        .as_ref()
        .map(goal_run_agent_ids)
        .unwrap_or_default();
    let active_goal_review_ids = active_run
        .as_ref()
        .map(goal_run_review_ids)
        .unwrap_or_default();
    let main_agent_board_routed_review_ids = if active_run.is_some() {
        main_agent_board_routed_review_ids(data_dir)
    } else {
        BTreeSet::new()
    };
    let mut entries = Vec::new();

    if let Some(run) = active_run.as_ref() {
        for step in &run.steps {
            if step.status == crate::orchestration::OrchestrationStepStatus::Done {
                continue;
            }
            let bucket = bucket_for_step_status(&step.status);
            let mut summary = format!("orchestration step is {}", step.status.as_str());
            if let Some(worker) = step.worker.as_deref() {
                summary.push_str(" | worker: ");
                summary.push_str(worker);
            }
            if !step.gates.is_empty() {
                summary.push_str(" | gates: ");
                summary.push_str(&step.gates.join(", "));
            }
            entries.push(
                GoalTaskPoolEntry::new(
                    format!("orchestration_step::{}::{}", run.run_id, step.step_id),
                    bucket,
                    &step.title,
                    summary,
                    GoalTaskPoolEntrySource::new("orchestration_step", &step.step_id),
                )
                .with_status(step.status.as_str())
                .with_action_ref(GoalTaskPoolEntryActionRef::new(
                    "advance_research_loop",
                    "Advance Loop",
                    "continue_or_dispatch_this_goal_step",
                ))
                .with_recommended_command(recommended_command_for_step(&step.step_id, bucket)),
            );
        }
        for claim in active_goal_task_claims(run) {
            let blocked = goal_task_claim_is_blocked(run, &claim.entry_id, &claim.agent_id);
            let bucket = if blocked { "blocked" } else { "running" };
            let status = if blocked { "blocked" } else { "claimed" };
            entries.push(
                GoalTaskPoolEntry::new(
                    goal_task_claim_ref(&claim.entry_id, &claim.agent_id),
                    bucket,
                    format!("claimed goal task {}", claim.entry_id),
                    format!(
                        "task pool entry {} is claimed by {}",
                        claim.entry_id, claim.agent_id
                    ),
                    GoalTaskPoolEntrySource::new("goal_task_claim", &claim.agent_id),
                )
                .with_status(status)
                .with_action_ref(GoalTaskPoolEntryActionRef::new(
                    "open_research",
                    "Inspect Claim",
                    "inspect_the_claimed_agent_task_before_acceptance",
                ))
                .with_recommended_command([
                    "agents",
                    "inspect",
                    &claim.agent_id,
                    "--json",
                ]),
            );
        }
        if let Some(policy) = automation_policy.as_ref() {
            let runtime_may_project_repair_followups = frame
                .map(|frame| !frame_uses_autonomous_research_stage_protocol(frame))
                .unwrap_or(true);
            if runtime_may_project_repair_followups {
                entries.extend(repair_followup_task_pool_entries(data_dir, run, policy));
            }
            entries.extend(main_agent_published_task_pool_entries(
                data_dir,
                workspace_root,
                Some(run),
                policy,
                research_status
                    .as_ref()
                    .and_then(|status| status.active_stage_execution.as_ref()),
            ));
            entries.extend(stage_decision_task_pool_entries(
                run,
                policy,
                research_status.as_ref(),
            ));
        }
    }

    if let Some(report) = research_status.as_ref() {
        let pending_operations_require_main_agent = frame
            .map(frame_uses_autonomous_research_stage_protocol)
            .unwrap_or(false);
        for (index, operation) in report.pending_operations.iter().enumerate() {
            let action_policy = automation_policy
                .as_ref()
                .and_then(|policy| policy.action_policy("dispatch_agent_task"))
                .unwrap_or("requires_approval");
            let (bucket, status, action_policy_value, action_label, action_intent) =
                if pending_operations_require_main_agent {
                    (
                        "needs_review",
                        "candidate_requires_main_agent_publication",
                        "requires_main_agent_task",
                        "Ask Main Agent",
                        "main_agent_must_publish_board_task_before_research_operation_dispatch",
                    )
                } else {
                    (
                        bucket_for_action_policy("dispatch_agent_task", action_policy),
                        "pending",
                        action_policy,
                        "Dispatch Operation",
                        "dispatch_or_approve_the_pending_research_operation",
                    )
                };
            entries.push(
                GoalTaskPoolEntry::new(
                    format!("research_operation::{index}"),
                    bucket,
                    operation,
                    if pending_operations_require_main_agent {
                        "runtime-observed research operation candidate; main agent must publish a board task before agent-team dispatch"
                    } else {
                        "pending operation from active research state"
                    },
                    GoalTaskPoolEntrySource::new(
                        if pending_operations_require_main_agent {
                            "research_operation_candidate"
                        } else {
                            "research_status_report"
                        },
                        &report.project_id,
                    ),
                )
                .with_status(status)
                .with_action_policy(action_policy_value)
                .with_action_ref(GoalTaskPoolEntryActionRef::new(
                    "advance_research_loop",
                    action_label,
                    action_intent,
                ))
                .with_recommended_command(if pending_operations_require_main_agent {
                    vec![
                        "research".to_string(),
                        "jobs".to_string(),
                        "tick".to_string(),
                        "--json".to_string(),
                    ]
                } else {
                    vec![
                        "research".to_string(),
                        "status".to_string(),
                        "--json".to_string(),
                    ]
                }),
            );
        }
        for gate in &report.middleware_pending_gates {
            entries.push(
                GoalTaskPoolEntry::new(
                    format!("research_gate::{}", gate.gate_id),
                    "needs_approval",
                    &gate.question,
                    format!("{} gate awaiting {}", gate.kind, gate.resume_policy),
                    GoalTaskPoolEntrySource::new("hitl_pending_gate", &gate.gate_id),
                )
                .with_status("pending")
                .with_action_ref(GoalTaskPoolEntryActionRef::new(
                    "decide_research_stage",
                    "Handle Gate",
                    "approve_reject_or_revise_the_pending_research_gate",
                ))
                .with_recommended_command([
                    "research",
                    "middleware",
                    "gates",
                    "--json",
                ]),
            );
        }
        if let Some(stage) = report.active_stage_execution.as_ref() {
            if frame
                .map(frame_uses_autonomous_research_stage_protocol)
                .unwrap_or(false)
            {
                entries.extend(stage_repair_task_candidate_pool_entries(stage));
                entries.extend(stage_local_task_candidate_pool_entries(
                    data_dir,
                    workspace_root,
                    stage,
                    active_run.as_ref(),
                ));
            }
            if stage.status == "blocked" {
                entries.push(
                    GoalTaskPoolEntry::new(
                        format!("research_stage_blocked::{}", stage.execution_id),
                        "blocked",
                        &stage.stage_id,
                        "active research stage is blocked",
                        GoalTaskPoolEntrySource::new(
                            "research_stage_execution",
                            &stage.execution_id,
                        ),
                    )
                    .with_status(&stage.status)
                    .with_action_ref(GoalTaskPoolEntryActionRef::new(
                        "inspect_recovery_governance",
                        "Inspect Block",
                        "inspect_recovery_state_for_the_blocked_research_stage",
                    ))
                    .with_recommended_command(["research", "status", "--json"]),
                );
            } else if !matches!(
                stage.status.as_str(),
                "completed" | "done" | "cancelled" | "failed"
            ) {
                entries.push(
                    GoalTaskPoolEntry::new(
                        format!("research_stage::{}", stage.execution_id),
                        "running",
                        &stage.stage_id,
                        format!("{} stage is {}", stage.stage_class, stage.status),
                        GoalTaskPoolEntrySource::new(
                            "research_stage_execution",
                            &stage.execution_id,
                        ),
                    )
                    .with_status(&stage.status)
                    .with_action_ref(GoalTaskPoolEntryActionRef::new(
                        "open_research",
                        "Open Stage",
                        "inspect_the_running_research_stage",
                    ))
                    .with_recommended_command(["research", "status", "--json"]),
                );
            }
        }
    }

    if let Some(agents) = agents.as_ref() {
        let latest_succeeded_agent_by_stage_task = latest_succeeded_agent_timestamp_by_stage_task(
            data_dir,
            &agents.agents,
            active_run.as_ref(),
            &active_goal_agent_ids,
        );
        for agent in &agents.agents {
            if active_run.is_some() && !active_goal_agent_ids.contains(&agent.agent_id) {
                continue;
            }
            if active_run
                .as_ref()
                .map(|run| goal_agent_already_resolved(run, &agent.agent_id))
                .unwrap_or(false)
            {
                continue;
            }
            if failed_agent_task_superseded_by_later_success(
                data_dir,
                agent,
                &latest_succeeded_agent_by_stage_task,
            ) {
                continue;
            }
            let bucket = bucket_for_agent_status(&agent.lifecycle_status);
            entries.push(
                GoalTaskPoolEntry::new(
                    format!("agent_task::{}", agent.agent_id),
                    bucket,
                    &agent.intent,
                    format!(
                        "{} agent is {} | task packet: {}",
                        agent.role_profile, agent.lifecycle_status, agent.task_packet_ref
                    ),
                    GoalTaskPoolEntrySource::new("agent_task_packet", &agent.agent_id),
                )
                .with_status(&agent.lifecycle_status)
                .with_action_ref(GoalTaskPoolEntryActionRef::new(
                    "open_research",
                    "Inspect Agent",
                    "inspect_agent_output_or_runtime_record",
                ))
                .with_recommended_command([
                    "agents",
                    "inspect",
                    &agent.agent_id,
                    "--json",
                ]),
            );
        }
    }

    if let Some(reviews) = reviews.as_ref() {
        for review in &reviews.reviews {
            if active_run.is_some() && !active_goal_review_ids.contains(&review.review_id) {
                continue;
            }
            let review_is_resolved = review.status.trim().eq_ignore_ascii_case("resolved");
            if active_run
                .as_ref()
                .map(|run| {
                    review_is_resolved
                        && goal_repair_review_is_already_routed_or_handled(
                            run,
                            &main_agent_board_routed_review_ids,
                            &review.review_id,
                        )
                })
                .unwrap_or(false)
            {
                continue;
            }
            let bucket = bucket_for_review_status(&review.status, &review.verdict);
            entries.push(
                GoalTaskPoolEntry::new(
                    format!("review::{}", review.review_id),
                    bucket,
                    &review.objective,
                    format!(
                        "{} review is {} with verdict {} over {} target(s)",
                        review.reviewer_role, review.status, review.verdict, review.target_count
                    ),
                    GoalTaskPoolEntrySource::new("review_packet", &review.review_id),
                )
                .with_status(&review.status)
                .with_action_ref(GoalTaskPoolEntryActionRef::new(
                    "open_research",
                    "Inspect Review",
                    "inspect_review_packet_and_verdict",
                ))
                .with_recommended_command([
                    "reviews",
                    "inspect",
                    &review.review_id,
                    "--json",
                ]),
            );
        }
    }

    if let Some(projectops) = projectops.as_ref() {
        for lease in &projectops.leases {
            let bucket = bucket_for_projectops_lease_state(&lease.state);
            entries.push(
                GoalTaskPoolEntry::new(
                    format!("projectops_lease::{}", lease.lease_id),
                    bucket,
                    &lease.run_id,
                    format!(
                        "run {} supervised by {} | {} pending wake(s) | {}",
                        lease.run_id,
                        lease.owner_agent_id,
                        lease.pending_wake_count,
                        lease.last_summary
                    ),
                    GoalTaskPoolEntrySource::new("projectops_supervisor_lease", &lease.lease_id),
                )
                .with_status(&lease.state)
                .with_action_ref(GoalTaskPoolEntryActionRef::new(
                    "inspect_recovery_governance",
                    "Inspect Supervisor",
                    "inspect_projectops_supervision_state",
                ))
                .with_recommended_command(["projectops", "status", "--json"]),
            );
        }
        for wake in &projectops.wake_events {
            let bucket = bucket_for_projectops_wake_state(&wake.state, wake.requires_main_system);
            entries.push(
                GoalTaskPoolEntry::new(
                    format!("projectops_wake::{}", wake.wake_id),
                    bucket,
                    &wake.summary,
                    format!(
                        "{} wake for run {} owned by {} | urgency {}",
                        wake.kind, wake.run_id, wake.owner_agent_id, wake.urgency
                    ),
                    GoalTaskPoolEntrySource::new("projectops_wake_event", &wake.wake_id),
                )
                .with_status(&wake.state)
                .with_action_ref(GoalTaskPoolEntryActionRef::new(
                    "inspect_recovery_governance",
                    "Inspect Wake",
                    "inspect_projectops_wake_or_recovery_request",
                ))
                .with_recommended_command(["projectops", "status", "--json"]),
            );
        }
        for cleanup in &projectops.cleanup_proposals {
            let Some(bucket) = bucket_for_projectops_cleanup_status(&cleanup.status) else {
                continue;
            };
            entries.push(
                GoalTaskPoolEntry::new(
                    format!("repo_cleanup::{}", cleanup.plan_id),
                    bucket,
                    format!("Review cleanup plan {}", cleanup.plan_id),
                    format!(
                        "{} cleanup action(s): {} archive move(s), {} removal(s), {} canonical repair(s), {} tracked git deletion(s), commit required: {}",
                        cleanup.proposed_action_count,
                        cleanup.move_to_archive_count,
                        cleanup.remove_count,
                        cleanup.canonical_repair_count,
                        cleanup.expected_tracked_deletion_count,
                        cleanup.git_commit_required
                    ),
                    GoalTaskPoolEntrySource::new("repo_cleanup_proposal", &cleanup.plan_id),
                )
                .with_status(&cleanup.status)
                .with_action_ref(GoalTaskPoolEntryActionRef::new(
                    "inspect_recovery_governance",
                    "Inspect Cleanup",
                    "inspect_repo_cleanup_proposal_and_apply_or_restore",
                ))
                .with_recommended_command(cleanup.recommended_command.clone()),
            );
        }
    }

    if let Some(policy) = automation_policy.as_ref() {
        let main_agent_task_publication_required = frame
            .map(frame_uses_autonomous_research_stage_protocol)
            .unwrap_or(false)
            && research_status
                .as_ref()
                .and_then(|status| status.active_stage_execution.as_ref())
                .is_some();
        entries.extend(policy_task_pool_entries(
            policy,
            main_agent_task_publication_required,
        ));
    }

    let next_recommended_action = next_recommended_action(
        &entries,
        active_run_progress.as_ref(),
        research_status.as_ref(),
    );
    GoalTaskPoolSnapshot {
        schema_version: "goal_task_pool_snapshot.v1".to_string(),
        authority_model: "derived_from_existing_goal_orchestration_research_authorities"
            .to_string(),
        source: "mission_frame_orchestration_research_agents_reviews_projectops_policy".to_string(),
        project_id: project_id.to_string(),
        automation_mode,
        target_run,
        summary: summarize_task_pool(&entries),
        entries,
        next_recommended_action,
    }
}

fn goal_run_agent_ids(run: &crate::orchestration::OrchestrationRun) -> BTreeSet<String> {
    let mut ids = BTreeSet::new();
    for step in &run.steps {
        for artifact in &step.artifacts {
            if let Some(claim) = parse_goal_task_claim_ref(artifact) {
                ids.insert(claim.agent_id);
                continue;
            }
            if let Some(agent_id) = artifact.strip_prefix("goal_acceptance::agent:") {
                ids.insert(agent_id.to_string());
                continue;
            }
            if let Some(agent_id) = artifact.strip_prefix("goal_repair_review::agent:") {
                ids.insert(agent_id.to_string());
                continue;
            }
            if let Some(path) = artifact.strip_prefix("agent_task_packet:") {
                if let Some(agent_id) = agent_id_from_agent_artifact_path(path) {
                    ids.insert(agent_id);
                }
                continue;
            }
            if let Some(path) = artifact.strip_prefix("agent_runtime_record:") {
                if let Some(agent_id) = agent_id_from_agent_artifact_path(path) {
                    ids.insert(agent_id);
                }
            }
        }
    }
    ids
}

fn goal_run_review_ids(run: &crate::orchestration::OrchestrationRun) -> BTreeSet<String> {
    let mut ids = BTreeSet::new();
    for step in &run.steps {
        for artifact in &step.artifacts {
            if let Some((kind, review_id)) = review_refs::parse_review_artifact_ref(artifact) {
                if matches!(kind, review_refs::ReviewArtifactKind::Packet) {
                    ids.insert(review_id);
                }
                continue;
            }
            if let Some(repair) = parse_goal_repair_review_link_ref(artifact) {
                ids.insert(repair.review_id);
            }
        }
    }
    ids
}

fn goal_repair_review_has_followup_task(
    run: &crate::orchestration::OrchestrationRun,
    review_id: &str,
) -> bool {
    run.steps.iter().any(|step| {
        step.artifacts
            .iter()
            .filter_map(|artifact| parse_goal_repair_followup_task_ref(artifact))
            .any(|repair| repair.review_id == review_id)
    })
}

fn goal_repair_review_is_already_routed_or_handled(
    run: &crate::orchestration::OrchestrationRun,
    main_agent_board_routed_review_ids: &BTreeSet<String>,
    review_id: &str,
) -> bool {
    goal_repair_review_has_followup_task(run, review_id)
        || goal_repair_review_has_outcome_artifact(run, review_id)
        || main_agent_board_routed_review_ids.contains(review_id)
}

fn goal_repair_review_has_outcome_artifact(
    run: &crate::orchestration::OrchestrationRun,
    review_id: &str,
) -> bool {
    let review_marker = format!("::review:{review_id}::");
    run.steps.iter().any(|step| {
        step.artifacts.iter().any(|artifact| {
            (artifact.starts_with("goal_repair_review_consumed::")
                || artifact.starts_with("goal_repair_review_failed::")
                || artifact.starts_with("goal_repair_review_waiting_main_agent_decision::"))
                && artifact.contains(&review_marker)
        })
    })
}

fn agent_id_from_agent_artifact_path(path: &str) -> Option<String> {
    let mut parts = Path::new(path).components().peekable();
    while let Some(part) = parts.next() {
        if part.as_os_str() == "agents" {
            let next = parts.next()?;
            let id = next.as_os_str().to_str()?;
            if !id.trim().is_empty() {
                return Some(id.to_string());
            }
        }
    }
    None
}

fn main_agent_published_task_pool_entries(
    data_dir: &Path,
    workspace_root: &Path,
    run: Option<&crate::orchestration::OrchestrationRun>,
    policy: &crate::orchestration::GoalRunAutomationPolicyProjection,
    active_stage: Option<&crate::research::ResearchStageExecution>,
) -> Vec<GoalTaskPoolEntry> {
    let action_policy = policy
        .action_policy("dispatch_agent_task")
        .unwrap_or("requires_approval");
    let bucket = bucket_for_action_policy("dispatch_agent_task", action_policy);
    let mut entries = Vec::new();
    let tasks = main_agent_board_task_refs(data_dir, run, active_stage)
        .into_iter()
        .filter_map(|task_ref| {
            let task = load_main_agent_published_stage_task(data_dir, &task_ref)?;
            main_agent_board_task_matches_active_stage(&task, active_stage)
                .then_some((task_ref, task))
        })
        .collect::<Vec<_>>();
    let published_task_ids = tasks
        .iter()
        .map(|(_, task)| normalize_board_dependency_id(&task.task_id))
        .collect::<BTreeSet<_>>();
    for (task_ref, mut task) in tasks {
        if let Some(violation) = main_agent_board_stage_task_contract_violation(&task, active_stage)
        {
            task.status = "contract_invalid".to_string();
            let task_id = task.task_id.clone();
            let stage_id = task.stage_id.clone();
            let task_type = task.task_type.clone();
            entries.push(
                GoalTaskPoolEntry::new(
                    task_id,
                    "blocked",
                    format!("{stage_id}: {task_type}"),
                    format!(
                        "main-agent-published task for stage {stage_id} has an invalid board-task contract: {violation}. Update or merge this board task before dispatch; invalid tasks are not worker-dispatchable."
                    ),
                    GoalTaskPoolEntrySource::new("main_agent_published_task", &task_ref),
                )
                .with_status("contract_invalid")
                .with_action_policy("requires_main_agent_update")
                .with_action_ref(GoalTaskPoolEntryActionRef::new(
                    "advance_research_loop",
                    "Ask Main Agent",
                    "main_agent_must_update_contract_invalid_board_task_before_dispatch",
                ))
                .with_recommended_command(["research", "jobs", "tick", "--json"])
                .with_stage_task(task),
            );
            continue;
        }
        let task_revision = main_agent_board_task_revision_timestamp(data_dir, &task_ref);
        let active_same_task_claim = run.and_then(|run| {
            active_goal_task_claim_for_entry_with_active_runtime(data_dir, run, &task.task_id)
        });
        if active_same_task_claim.is_none()
            && run
                .map(|run| {
                    goal_task_entry_already_dispatched_or_claimed_for_revision(
                        run,
                        &task.task_id,
                        task_revision,
                    )
                })
                .unwrap_or(false)
        {
            continue;
        }
        let dependency_status = resolve_main_agent_board_task_dependencies(
            data_dir,
            workspace_root,
            active_stage,
            &task,
            &published_task_ids,
        );
        let has_missing_board_tasks = !dependency_status.missing_board_task_ids.is_empty();
        let has_missing_dependencies = !dependency_status.missing_dependency_ids.is_empty();
        let has_adoption_ready_candidate = !has_missing_board_tasks
            && !has_missing_dependencies
            && main_agent_board_task_has_adoption_ready_candidate(
                data_dir,
                workspace_root,
                active_stage,
                &task,
                task_revision,
            );
        let has_active_same_type_evidence = !has_missing_board_tasks
            && !has_missing_dependencies
            && !has_adoption_ready_candidate
            && main_agent_board_task_has_active_same_type_evidence(
                data_dir,
                workspace_root,
                active_stage,
                &task,
                task_revision,
            );
        let has_active_same_task_claim = active_same_task_claim.is_some();
        let bucket = if has_active_same_task_claim {
            "running"
        } else if has_missing_board_tasks {
            "blocked"
        } else if has_missing_dependencies {
            "waiting_on_dependencies"
        } else if has_adoption_ready_candidate {
            "waiting_on_main_agent_adoption"
        } else if has_active_same_type_evidence {
            "waiting_on_main_agent_adoption"
        } else {
            bucket
        };
        let entry_status = if has_active_same_task_claim {
            "running"
        } else if has_missing_board_tasks {
            "contract_invalid"
        } else if has_missing_dependencies {
            "waiting_on_dependency_evidence"
        } else if has_adoption_ready_candidate {
            "waiting_on_main_agent_adoption"
        } else if has_active_same_type_evidence {
            "waiting_on_active_same_type_evidence"
        } else if action_policy == "allowed" {
            "ready"
        } else {
            "pending_policy"
        };
        let entry_action_policy = if has_active_same_task_claim {
            "waiting_on_active_worker_attempt"
        } else if has_missing_board_tasks {
            "requires_main_agent_update"
        } else if has_missing_dependencies {
            "waiting_on_dependencies"
        } else if has_adoption_ready_candidate {
            "waiting_on_main_agent_adoption"
        } else if has_active_same_type_evidence {
            "waiting_on_main_agent_decision"
        } else {
            action_policy
        };
        augment_stage_evidence_consuming_task_inputs(
            data_dir,
            workspace_root,
            active_stage,
            &mut task,
        );
        if !dependency_status.resolved_refs.is_empty() {
            for reference in dependency_status.resolved_refs {
                push_unique(&mut task.input_artifact_refs, reference);
            }
        }
        let canonical_artifact_blockers = if !has_missing_dependencies
            && !has_missing_board_tasks
            && !has_adoption_ready_candidate
            && !has_active_same_task_claim
            && action_policy == "allowed"
        {
            goal_stage_task_canonical_artifact_dependency_blockers(data_dir, &task)
        } else {
            Vec::new()
        };
        let has_canonical_artifact_blockers = !canonical_artifact_blockers.is_empty();
        let bucket = if has_canonical_artifact_blockers {
            "waiting_on_dependencies"
        } else {
            bucket
        };
        let entry_status = if has_canonical_artifact_blockers {
            "waiting_on_canonical_artifact_dependency"
        } else {
            entry_status
        };
        let entry_action_policy = if has_canonical_artifact_blockers {
            "waiting_on_dependencies"
        } else {
            entry_action_policy
        };
        task.status = if !has_missing_dependencies
            && !has_missing_board_tasks
            && !has_adoption_ready_candidate
            && !has_active_same_type_evidence
            && !has_active_same_task_claim
            && !has_canonical_artifact_blockers
            && action_policy == "allowed"
        {
            "ready".to_string()
        } else if has_active_same_task_claim {
            "running".to_string()
        } else {
            "gated".to_string()
        };
        task.claimed_by_agent_id = active_same_task_claim
            .clone()
            .map(|claim| claim.agent_id)
            .or_else(|| {
                run.and_then(|run| {
                    active_goal_task_claims(run)
                        .into_iter()
                        .find(|claim| {
                            claim.entry_id == task.task_id
                                && !goal_task_claim_superseded_by_task_revision(
                                    task_revision,
                                    &claim.agent_id,
                                )
                        })
                        .map(|claim| claim.agent_id)
                })
            });
        let task_id = task.task_id.clone();
        let stage_id = task.stage_id.clone();
        let task_type = task.task_type.clone();
        let required_output_artifact_type = task.required_output_artifact_type.clone();
        let entry_summary = if let Some(claim) = active_same_task_claim.as_ref() {
            format!(
                "main-agent-published task for stage {stage_id}; active worker attempt {} is already running for this task slot; wait for worker output before dispatching a revised attempt; required output: {required_output_artifact_type}",
                claim.agent_id
            )
        } else if has_missing_board_tasks {
            format!(
                "main-agent-published task for stage {stage_id} has stale or nonexistent upstream board-task dependencies: {}. Update `depends_on_task_ids`/`input_artifact_refs` or publish the missing upstream task before dispatch; required output: {required_output_artifact_type}",
                dependency_status.missing_board_task_ids.join(", ")
            )
        } else if has_missing_dependencies {
            format!(
                "main-agent-published task for stage {stage_id}; waiting for accepted upstream evidence: {}; required output: {required_output_artifact_type}",
                dependency_status.missing_dependency_ids.join(", ")
            )
        } else if has_adoption_ready_candidate {
            format!(
                "main-agent-published task for stage {stage_id}; adoption-ready accepted worker evidence already exists for task type {task_type} and required output {required_output_artifact_type}; wait for main-agent accept/reject/adopt decision"
            )
        } else if has_active_same_type_evidence {
            format!(
                "main-agent-published task for stage {stage_id}; active main-agent-accepted evidence already exists for task type {task_type} and required output {required_output_artifact_type}; update/replace/reject/adopt the current evidence before dispatching duplicate same-type work"
            )
        } else if has_canonical_artifact_blockers {
            format!(
                "main-agent-published task for stage {stage_id}; waiting for canonical artifact dependency: {}; required output: {required_output_artifact_type}",
                canonical_artifact_blockers
                    .iter()
                    .map(|blocker| blocker.render_for_prompt())
                    .collect::<Vec<_>>()
                    .join("; ")
            )
        } else {
            format!(
                "main-agent-published task for stage {stage_id}; required output: {required_output_artifact_type}"
            )
        };
        entries.push(
            GoalTaskPoolEntry::new(
                task_id.clone(),
                bucket,
                format!("{stage_id}: {task_type}"),
                entry_summary,
                GoalTaskPoolEntrySource::new("main_agent_published_task", &task_ref),
            )
            .with_status(entry_status)
            .with_action_policy(entry_action_policy)
            .with_action_ref(if has_active_same_task_claim {
                GoalTaskPoolEntryActionRef::new(
                    "advance_research_loop",
                    "Wait For Worker",
                    "wait_for_active_worker_attempt_before_dispatching_revision",
                )
            } else if has_missing_board_tasks {
                GoalTaskPoolEntryActionRef::new(
                    "advance_research_loop",
                    "Ask Main Agent",
                    "main_agent_must_update_missing_board_task_dependency_before_dispatch",
                )
            } else if has_missing_dependencies {
                GoalTaskPoolEntryActionRef::new(
                    "advance_research_loop",
                    "Wait For Dependencies",
                    "wait_for_upstream_accepted_worker_evidence_before_dispatch",
                )
            } else if has_canonical_artifact_blockers {
                GoalTaskPoolEntryActionRef::new(
                    "inspect_canonical_artifact_dependency",
                    "Wait For Canonical Artifact",
                    "main_agent_must_adopt_materialize_baseline_verify_replace_route_or_cleanup_the_blocking_canonical_artifact",
                )
            } else if has_adoption_ready_candidate || has_active_same_type_evidence {
                GoalTaskPoolEntryActionRef::new(
                    "main_agent_artifact_decision",
                    "Wait For Adoption",
                    "main_agent_must_accept_reject_update_replace_or_adopt_existing_evidence_before_dispatching_more_same_type_work",
                )
            } else {
                GoalTaskPoolEntryActionRef::new(
                    "advance_research_loop",
                    "Dispatch Main-Agent Task",
                    "dispatch_main_agent_published_research_task_to_agent_team",
                )
            })
            .with_recommended_command(["goals", "advance", "--json"])
            .with_stage_task(task),
        );
    }
    entries
}

#[derive(Debug, Clone, Default)]
struct MainAgentBoardTaskDependencyResolution {
    missing_board_task_ids: Vec<String>,
    missing_dependency_ids: Vec<String>,
    resolved_refs: Vec<String>,
}

#[derive(Debug, Clone, Default)]
struct AcceptedWorkerEvidenceLookup {
    by_task_id: BTreeMap<String, Vec<String>>,
    by_task_key: BTreeMap<String, Vec<String>>,
    by_evidence_set_id: BTreeMap<String, Vec<String>>,
    known_task_ids: BTreeSet<String>,
}

fn augment_stage_evidence_consuming_task_inputs(
    data_dir: &Path,
    workspace_root: &Path,
    active_stage: Option<&crate::research::ResearchStageExecution>,
    task: &mut GoalStageTaskMetadata,
) {
    if !is_stage_evidence_consuming_task(&task.task_type) {
        return;
    }
    let lookup = accepted_worker_evidence_lookup_for_board_task(
        data_dir,
        workspace_root,
        active_stage,
        task,
    );
    let mut refs = Vec::new();

    if is_stage_synthesis_task(&task.task_type) {
        for task_refs in lookup.by_task_id.values() {
            for reference in task_refs {
                push_unique(&mut refs, reference.clone());
            }
        }
        for task_refs in lookup.by_task_key.values() {
            for reference in task_refs {
                push_unique(&mut refs, reference.clone());
            }
        }
    } else {
        for dependency_id in targeted_evidence_dependency_ids_for_repair(task) {
            push_lookup_refs_for_dependency_id(&lookup, &dependency_id, &mut refs);
        }
        for evidence_ref in &task.review_target_evidence_refs {
            push_lookup_refs_for_review_target_evidence_ref(&lookup, evidence_ref, &mut refs);
        }
        if let Some(evidence_set_id) = task
            .current_evidence_set_id
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty())
        {
            push_lookup_refs_for_review_target_evidence_ref(&lookup, evidence_set_id, &mut refs);
        }
    }

    refs.sort();
    refs.dedup();
    for reference in refs {
        push_unique(&mut task.input_artifact_refs, reference);
    }
}

fn is_stage_evidence_consuming_task(task_type: &str) -> bool {
    is_stage_synthesis_task(task_type) || is_stage_artifact_repair_task(task_type)
}

fn is_stage_synthesis_task(task_type: &str) -> bool {
    normalize_task_key(task_type).contains("synthesis")
}

fn is_stage_artifact_repair_task(task_type: &str) -> bool {
    let key = normalize_task_key(task_type);
    key.contains("artifact repair")
}

fn targeted_evidence_dependency_ids_for_repair(task: &GoalStageTaskMetadata) -> Vec<String> {
    let mut dependency_ids = Vec::new();
    for dependency_id in main_agent_board_task_dependency_ids(task) {
        push_unique(&mut dependency_ids, dependency_id);
    }
    for dependency_id in &task.review_target_task_ids {
        push_unique(
            &mut dependency_ids,
            normalize_board_dependency_id(dependency_id),
        );
    }
    for dependency_id in &task.replacement_of_task_ids {
        push_unique(
            &mut dependency_ids,
            normalize_board_dependency_id(dependency_id),
        );
    }
    for dependency_id in &task.supersedes_task_ids {
        push_unique(
            &mut dependency_ids,
            normalize_board_dependency_id(dependency_id),
        );
    }
    dependency_ids
}

fn push_lookup_refs_for_dependency_id(
    lookup: &AcceptedWorkerEvidenceLookup,
    dependency_id: &str,
    refs: &mut Vec<String>,
) {
    let normalized_dependency_id = normalize_board_dependency_id(dependency_id);
    if let Some(task_refs) = lookup.by_task_id.get(&normalized_dependency_id) {
        for reference in task_refs {
            push_unique(refs, reference.clone());
        }
        return;
    }
    if let Some(task_key) = task_type_key_from_explicit_dependency_ref(&normalized_dependency_id) {
        if let Some(task_refs) = lookup.by_task_key.get(&task_key) {
            for reference in task_refs {
                push_unique(refs, reference.clone());
            }
        }
    }
}

fn push_lookup_refs_for_review_target_evidence_ref(
    lookup: &AcceptedWorkerEvidenceLookup,
    evidence_ref: &str,
    refs: &mut Vec<String>,
) {
    let trimmed = evidence_ref.trim();
    if trimmed.is_empty() {
        return;
    }
    if let Some(task_id) = trimmed.strip_prefix("accepted_worker_evidence_task:") {
        push_lookup_refs_for_dependency_id(lookup, task_id, refs);
        return;
    }
    if let Some(task_type) = trimmed.strip_prefix("accepted_worker_evidence:") {
        let task_key = normalize_task_key(task_type);
        if let Some(task_refs) = lookup.by_task_key.get(&task_key) {
            for reference in task_refs {
                push_unique(refs, reference.clone());
            }
        }
        return;
    }
    if let Some(task_refs) = lookup.by_evidence_set_id.get(trimmed) {
        for reference in task_refs {
            push_unique(refs, reference.clone());
        }
        return;
    }
    push_lookup_refs_for_dependency_id(lookup, trimmed, refs);
}

fn resolve_main_agent_board_task_dependencies(
    data_dir: &Path,
    workspace_root: &Path,
    active_stage: Option<&crate::research::ResearchStageExecution>,
    task: &GoalStageTaskMetadata,
    published_task_ids: &BTreeSet<String>,
) -> MainAgentBoardTaskDependencyResolution {
    let dependency_ids = main_agent_board_task_dependency_ids(task);
    if dependency_ids.is_empty() {
        return MainAgentBoardTaskDependencyResolution::default();
    }
    let lookup = accepted_worker_evidence_lookup_for_board_task(
        data_dir,
        workspace_root,
        active_stage,
        task,
    );
    let mut resolved_refs = Vec::new();
    let mut missing_board_task_ids = Vec::new();
    let mut missing_dependency_ids = Vec::new();
    for dependency_id in dependency_ids {
        let mut dependency_refs = lookup
            .by_task_id
            .get(&dependency_id)
            .cloned()
            .unwrap_or_default();
        if dependency_refs.is_empty() {
            if let Some(task_key) = task_type_key_from_explicit_dependency_ref(&dependency_id) {
                dependency_refs = lookup
                    .by_task_key
                    .get(&task_key)
                    .cloned()
                    .unwrap_or_default();
            }
        }
        if dependency_refs.is_empty() {
            if dependency_id_requires_published_board_task(&dependency_id)
                && !published_task_ids.contains(&dependency_id)
                && !lookup.known_task_ids.contains(&dependency_id)
            {
                missing_board_task_ids.push(dependency_id);
            } else {
                missing_dependency_ids.push(dependency_id);
            }
            continue;
        }
        for reference in dependency_refs {
            push_unique(&mut resolved_refs, reference);
        }
    }
    MainAgentBoardTaskDependencyResolution {
        missing_board_task_ids,
        missing_dependency_ids,
        resolved_refs,
    }
}

fn main_agent_board_task_dependency_ids(task: &GoalStageTaskMetadata) -> Vec<String> {
    let mut dependency_ids = Vec::new();
    for dependency_id in &task.depends_on_task_ids {
        push_unique(
            &mut dependency_ids,
            normalize_board_dependency_id(dependency_id),
        );
    }
    for reference in &task.input_artifact_refs {
        if let Some(dependency_id) = board_dependency_id_from_input_ref(reference) {
            push_unique(&mut dependency_ids, dependency_id);
        }
    }
    for requirement in &task.required_canonical_artifacts {
        if let Some(dependency_id) =
            accepted_worker_evidence_dependency_id_from_ref(&requirement.target_artifact_path)
        {
            push_unique(&mut dependency_ids, dependency_id);
        }
    }
    dependency_ids
}

fn board_dependency_id_from_input_ref(reference: &str) -> Option<String> {
    let trimmed = reference.trim();
    if let Some(dependency_id) = accepted_worker_evidence_dependency_id_from_ref(trimmed) {
        return Some(dependency_id);
    }
    if trimmed.starts_with("board::") {
        return Some(trimmed.to_string());
    }
    trimmed
        .strip_prefix("main_agent_board_task::")
        .filter(|task_id| task_id.starts_with("board::"))
        .map(ToString::to_string)
}

fn accepted_worker_evidence_dependency_id_from_ref(reference: &str) -> Option<String> {
    let trimmed = reference.trim();
    if let Some(task_id) = trimmed.strip_prefix("accepted_worker_evidence_task:") {
        let task_id = normalize_board_dependency_id(task_id);
        if !task_id.trim().is_empty() {
            return Some(task_id);
        }
    }
    if let Some(task_or_type) = trimmed.strip_prefix("accepted_worker_evidence:") {
        let task_or_type = task_or_type.trim();
        if task_or_type.is_empty() || task_or_type.starts_with('/') {
            return None;
        }
        if task_or_type.contains("::") {
            return Some(normalize_board_dependency_id(task_or_type));
        }
        return Some(format!("accepted_worker_evidence:{task_or_type}"));
    }
    None
}

fn dependency_id_requires_published_board_task(dependency_id: &str) -> bool {
    !dependency_id
        .trim()
        .starts_with("accepted_worker_evidence:")
}

fn normalize_board_dependency_id(dependency_id: &str) -> String {
    dependency_id
        .trim()
        .strip_prefix("main_agent_board_task::")
        .unwrap_or_else(|| dependency_id.trim())
        .to_string()
}

fn accepted_worker_evidence_lookup_for_board_task(
    data_dir: &Path,
    workspace_root: &Path,
    active_stage: Option<&crate::research::ResearchStageExecution>,
    task: &GoalStageTaskMetadata,
) -> AcceptedWorkerEvidenceLookup {
    let mut stage_execution_ids = Vec::new();
    if let Some(stage) = active_stage {
        push_unique(&mut stage_execution_ids, stage.execution_id.clone());
        if let Some(parent_execution_id) = stage.parent_execution_id.as_ref() {
            push_unique(&mut stage_execution_ids, parent_execution_id.clone());
        }
        push_unique(&mut stage_execution_ids, stage.root_execution_id.clone());
        for superseded_stage_execution_id in &stage.supersedes {
            push_unique(
                &mut stage_execution_ids,
                superseded_stage_execution_id.clone(),
            );
        }
    }
    if !task.stage_execution_id.trim().is_empty() {
        push_unique(&mut stage_execution_ids, task.stage_execution_id.clone());
    }
    if stage_execution_ids.is_empty() {
        return AcceptedWorkerEvidenceLookup::default();
    }

    let mut roots = Vec::new();
    roots.push(workspace_root.to_path_buf());
    if data_dir != workspace_root {
        roots.push(data_dir.to_path_buf());
    }

    let mut lookup = AcceptedWorkerEvidenceLookup::default();
    let task_current_evidence_set_id = task
        .current_evidence_set_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty());
    for root in roots {
        for stage_execution_id in &stage_execution_ids {
            for path in accepted_stage_task_index_candidates(&root, stage_execution_id) {
                let Ok(content) = fs::read_to_string(&path) else {
                    continue;
                };
                let Ok(value) = serde_json::from_str::<serde_json::Value>(&content) else {
                    continue;
                };
                if !task.stage_id.trim().is_empty()
                    && value.get("stage_id").and_then(|value| value.as_str())
                        != Some(task.stage_id.as_str())
                {
                    continue;
                }
                let Some(entries) = value.get("entries").and_then(|entries| entries.as_array())
                else {
                    continue;
                };
                for entry in entries {
                    if let Some(task_id) = entry.get("task_id").and_then(|value| value.as_str()) {
                        lookup.known_task_ids.insert(task_id.to_string());
                    }
                    let entry_current_evidence_set_id = entry
                        .get("current_evidence_set_id")
                        .and_then(|value| value.as_str())
                        .map(str::trim)
                        .filter(|value| !value.is_empty());
                    let is_main_agent_accepted =
                        crate::accepted_worker_evidence::json_entry_is_main_agent_accepted(entry);
                    let is_explicit_current_evidence_input = task_current_evidence_set_id
                        .zip(entry_current_evidence_set_id)
                        .map(|(task_evidence_set_id, entry_evidence_set_id)| {
                            task_evidence_set_id == entry_evidence_set_id
                        })
                        .unwrap_or(false)
                        && !accepted_worker_evidence_entry_is_retired_json(entry);
                    if !is_main_agent_accepted && !is_explicit_current_evidence_input {
                        continue;
                    }
                    let refs = accepted_worker_evidence_refs_from_entry(entry, &path);
                    if refs.is_empty() {
                        continue;
                    }
                    if is_main_agent_accepted {
                        if let Some(task_id) = entry.get("task_id").and_then(|value| value.as_str())
                        {
                            for reference in &refs {
                                lookup
                                    .by_task_id
                                    .entry(task_id.to_string())
                                    .or_default()
                                    .push(reference.clone());
                            }
                        }
                        if let Some(task_type) =
                            entry.get("task_type").and_then(|value| value.as_str())
                        {
                            let key = normalize_task_key(task_type);
                            for reference in &refs {
                                lookup
                                    .by_task_key
                                    .entry(key.clone())
                                    .or_default()
                                    .push(reference.clone());
                            }
                        }
                    }
                    if let Some(evidence_set_id) = entry_current_evidence_set_id {
                        for reference in &refs {
                            lookup
                                .by_evidence_set_id
                                .entry(evidence_set_id.to_string())
                                .or_default()
                                .push(reference.clone());
                        }
                    }
                }
            }
        }
    }
    for refs in lookup.by_task_id.values_mut() {
        refs.sort();
        refs.dedup();
    }
    for refs in lookup.by_task_key.values_mut() {
        refs.sort();
        refs.dedup();
    }
    for refs in lookup.by_evidence_set_id.values_mut() {
        refs.sort();
        refs.dedup();
    }
    lookup
}

fn accepted_worker_evidence_refs_from_entry(
    entry: &serde_json::Value,
    index_path: &Path,
) -> Vec<String> {
    let mut refs = Vec::new();
    if let Some(task_type) = entry.get("task_type").and_then(|value| value.as_str()) {
        push_unique(&mut refs, format!("accepted_worker_evidence:{task_type}"));
    }
    if let Some(task_id) = entry.get("task_id").and_then(|value| value.as_str()) {
        push_unique(
            &mut refs,
            format!("accepted_worker_evidence_task:{task_id}"),
        );
    }
    push_unique(
        &mut refs,
        format!("accepted_worker_evidence_index:{}", index_path.display()),
    );
    for key in ["output_manifest_ref", "task_packet_ref"] {
        if let Some(reference) = entry.get(key).and_then(|value| value.as_str()) {
            push_unique(&mut refs, reference.to_string());
        }
    }
    if let Some(evidence_refs) = entry
        .get("evidence_refs")
        .and_then(|value| value.as_array())
    {
        for reference in evidence_refs.iter().filter_map(|value| value.as_str()) {
            push_unique(&mut refs, reference.to_string());
        }
    }
    if let Some(semantic_review) = entry.get("semantic_review") {
        for key in ["review_packet_ref", "review_trace_ref"] {
            if let Some(reference) = semantic_review.get(key).and_then(|value| value.as_str()) {
                push_unique(&mut refs, reference.to_string());
            }
        }
    }
    refs
}

fn main_agent_board_task_has_adoption_ready_candidate(
    data_dir: &Path,
    workspace_root: &Path,
    active_stage: Option<&crate::research::ResearchStageExecution>,
    task: &GoalStageTaskMetadata,
    task_revision: Option<u128>,
) -> bool {
    if task.task_type.trim().is_empty() || task.required_output_artifact_type.trim().is_empty() {
        return false;
    }
    let mut stage_execution_ids = Vec::new();
    if let Some(stage) = active_stage {
        push_unique(&mut stage_execution_ids, stage.execution_id.clone());
        push_unique(&mut stage_execution_ids, stage.root_execution_id.clone());
        if let Some(parent_execution_id) = stage.parent_execution_id.as_ref() {
            push_unique(&mut stage_execution_ids, parent_execution_id.clone());
        }
    }
    if !task.stage_execution_id.trim().is_empty() {
        push_unique(&mut stage_execution_ids, task.stage_execution_id.clone());
    }
    if stage_execution_ids.is_empty() {
        return false;
    }
    let mut roots = vec![workspace_root.to_path_buf()];
    if data_dir != workspace_root {
        roots.push(data_dir.to_path_buf());
    }
    for root in roots {
        for stage_execution_id in &stage_execution_ids {
            for path in accepted_stage_task_index_candidates(&root, stage_execution_id) {
                let Ok(content) = fs::read_to_string(&path) else {
                    continue;
                };
                let Ok(value) = serde_json::from_str::<serde_json::Value>(&content) else {
                    continue;
                };
                if !task.stage_id.trim().is_empty()
                    && value.get("stage_id").and_then(|value| value.as_str())
                        != Some(task.stage_id.as_str())
                {
                    continue;
                }
                let Some(entries) = value.get("entries").and_then(|entries| entries.as_array())
                else {
                    continue;
                };
                if entries.iter().any(|entry| {
                    accepted_worker_evidence_entry_is_adoption_ready_for_board_task(
                        entry,
                        task,
                        task_revision,
                    )
                }) {
                    return true;
                }
            }
        }
    }
    false
}

fn accepted_worker_evidence_entry_is_adoption_ready_for_board_task(
    entry: &serde_json::Value,
    task: &GoalStageTaskMetadata,
    task_revision: Option<u128>,
) -> bool {
    if accepted_worker_evidence_entry_is_retired_json(entry) {
        return false;
    }
    if !crate::accepted_worker_evidence::json_entry_is_current_for_task_revision(
        entry,
        task_revision,
    ) {
        return false;
    }
    if !accepted_worker_evidence_entry_targets_board_task(entry, task) {
        return false;
    }
    let expected_artifact_type = stage_artifact_type_for_stage(&task.stage_id);
    if !crate::accepted_worker_evidence::stage_synthesis_matches_artifact(
        &task.worker_role,
        &task.task_type,
        &task.required_output_artifact_type,
        expected_artifact_type,
    ) || !crate::accepted_worker_evidence::json_entry_is_stage_synthesis_for_artifact(
        entry,
        expected_artifact_type,
    ) {
        return false;
    }
    if entry
        .get("task_type")
        .and_then(|value| value.as_str())
        .map(normalize_task_key)
        != Some(normalize_task_key(&task.task_type))
    {
        return false;
    }
    let Some(review) = entry.get("semantic_review") else {
        return false;
    };
    let verdict_passes = review
        .get("verdict")
        .and_then(|value| value.as_str())
        .map(|value| value.eq_ignore_ascii_case("pass"))
        .unwrap_or(false);
    let score_passes = review
        .get("score")
        .and_then(|value| value.as_u64())
        .map(|score| score >= 75)
        .unwrap_or(false);
    let independent_review = review
        .get("execution_mode")
        .and_then(|value| value.as_str())
        .map(|value| value != "main_agent_authority_projection")
        .unwrap_or(false)
        && review
            .get("reviewer_role")
            .and_then(|value| value.as_str())
            .map(|value| value != "main_agent_worker_artifact_acceptance")
            .unwrap_or(false);
    verdict_passes && score_passes && independent_review
}

fn main_agent_board_task_has_active_same_type_evidence(
    data_dir: &Path,
    workspace_root: &Path,
    active_stage: Option<&crate::research::ResearchStageExecution>,
    task: &GoalStageTaskMetadata,
    task_revision: Option<u128>,
) -> bool {
    let mut stage_execution_ids = Vec::new();
    if let Some(stage) = active_stage {
        if stage.stage_id == task.stage_id || task.stage_id.trim().is_empty() {
            push_unique(&mut stage_execution_ids, stage.execution_id.clone());
            push_unique(&mut stage_execution_ids, stage.root_execution_id.clone());
            if let Some(parent_execution_id) = stage.parent_execution_id.as_ref() {
                push_unique(&mut stage_execution_ids, parent_execution_id.clone());
            }
        }
    }
    if !task.stage_execution_id.trim().is_empty() {
        push_unique(&mut stage_execution_ids, task.stage_execution_id.clone());
    }
    if stage_execution_ids.is_empty() {
        return false;
    }
    let mut roots = vec![workspace_root.to_path_buf()];
    if data_dir != workspace_root {
        roots.push(data_dir.to_path_buf());
    }
    for root in roots {
        for stage_execution_id in &stage_execution_ids {
            for path in accepted_stage_task_index_candidates(&root, stage_execution_id) {
                let Ok(content) = fs::read_to_string(&path) else {
                    continue;
                };
                let Ok(value) = serde_json::from_str::<serde_json::Value>(&content) else {
                    continue;
                };
                if !task.stage_id.trim().is_empty()
                    && value.get("stage_id").and_then(|value| value.as_str())
                        != Some(task.stage_id.as_str())
                {
                    continue;
                }
                let Some(entries) = value.get("entries").and_then(|entries| entries.as_array())
                else {
                    continue;
                };
                if entries.iter().any(|entry| {
                    accepted_worker_evidence_entry_is_active_same_type(
                        &root,
                        entry,
                        task,
                        task_revision,
                    )
                }) {
                    return true;
                }
            }
        }
    }
    false
}

fn accepted_worker_evidence_entry_is_active_same_type(
    root: &Path,
    entry: &serde_json::Value,
    task: &GoalStageTaskMetadata,
    task_revision: Option<u128>,
) -> bool {
    if accepted_worker_evidence_entry_is_retired_json(entry) {
        return false;
    }
    if !crate::accepted_worker_evidence::json_entry_is_current_for_task_revision(
        entry,
        task_revision,
    ) {
        return false;
    }
    if entry
        .get("active_status")
        .and_then(|value| value.as_str())
        .map(|status| status.eq_ignore_ascii_case("active"))
        != Some(true)
    {
        return false;
    }
    if entry
        .get("main_agent_decision_ref")
        .and_then(|value| value.as_str())
        .map(|value| !value.trim().is_empty())
        != Some(true)
    {
        return false;
    }
    if entry
        .get("task_id")
        .and_then(|value| value.as_str())
        .map(|task_id| task_id.trim() == task.task_id.trim())
        .unwrap_or(false)
    {
        return false;
    }
    if entry
        .get("task_type")
        .and_then(|value| value.as_str())
        .map(normalize_task_key)
        != Some(normalize_task_key(&task.task_type))
    {
        return false;
    }
    if entry
        .get("required_output_artifact_type")
        .and_then(|value| value.as_str())
        != Some(task.required_output_artifact_type.as_str())
    {
        return false;
    }
    if main_agent_board_task_has_repair_lineage(task)
        && !accepted_worker_evidence_entry_matches_repair_lineage(root, entry, task)
    {
        return false;
    }
    true
}

fn main_agent_board_task_has_repair_lineage(task: &GoalStageTaskMetadata) -> bool {
    let has_repair_contract = task
        .review_findings_refs
        .iter()
        .any(|reference| !reference.trim().is_empty())
        || task
            .replacement_of_task_ids
            .iter()
            .any(|reference| !reference.trim().is_empty())
        || task
            .supersedes_task_ids
            .iter()
            .any(|reference| !reference.trim().is_empty());
    has_repair_contract && !main_agent_board_task_repair_anchor_refs(task).is_empty()
}

fn main_agent_board_task_repair_anchor_refs(task: &GoalStageTaskMetadata) -> Vec<String> {
    let mut refs = Vec::new();
    for reference in task
        .blocker_refs
        .iter()
        .chain(task.review_target_evidence_refs.iter())
        .chain(task.replacement_of_task_ids.iter())
        .chain(task.supersedes_task_ids.iter())
    {
        push_repair_lineage_anchor(&mut refs, reference);
    }
    for reference in &task.review_findings_refs {
        push_review_lineage_anchor(&mut refs, reference);
    }
    refs
}

fn accepted_worker_evidence_entry_matches_repair_lineage(
    root: &Path,
    entry: &serde_json::Value,
    task: &GoalStageTaskMetadata,
) -> bool {
    let task_anchors = main_agent_board_task_repair_anchor_refs(task);
    if task_anchors.is_empty() {
        return false;
    }
    if let Some(entry_task_id) = entry.get("task_id").and_then(|value| value.as_str()) {
        if task
            .replacement_of_task_ids
            .iter()
            .chain(task.supersedes_task_ids.iter())
            .any(|task_id| normalize_board_dependency_id(task_id) == entry_task_id.trim())
        {
            return false;
        }
    }
    accepted_worker_evidence_entry_repair_anchor_refs(root, entry)
        .iter()
        .any(|entry_anchor| {
            task_anchors
                .iter()
                .any(|task_anchor| task_anchor == entry_anchor)
        })
}

fn accepted_worker_evidence_entry_repair_anchor_refs(
    root: &Path,
    entry: &serde_json::Value,
) -> Vec<String> {
    let mut refs = Vec::new();
    for key in ["task_id", "current_evidence_set_id"] {
        if let Some(reference) = entry.get(key).and_then(|value| value.as_str()) {
            push_repair_lineage_anchor(&mut refs, reference);
        }
    }
    if let Some(evidence_refs) = entry
        .get("evidence_refs")
        .and_then(|value| value.as_array())
    {
        for reference in evidence_refs.iter().filter_map(|value| value.as_str()) {
            push_repair_lineage_anchor(&mut refs, reference);
        }
    }
    if let Some(task_packet) = accepted_worker_evidence_entry_task_packet(root, entry) {
        let contract = task_packet
            .get("stage_task_contract")
            .unwrap_or(&task_packet);
        for field in [
            "blocker_refs",
            "review_target_evidence_refs",
            "replacement_of_task_ids",
            "supersedes_task_ids",
        ] {
            push_repair_lineage_anchors_from_json_array(&mut refs, contract.get(field));
        }
        push_review_lineage_anchors_from_json_array(
            &mut refs,
            contract.get("review_findings_refs"),
        );
    }
    refs
}

fn accepted_worker_evidence_entry_task_packet(
    root: &Path,
    entry: &serde_json::Value,
) -> Option<serde_json::Value> {
    let mut candidates = Vec::new();
    if let Some(reference) = entry
        .get("task_packet_ref")
        .and_then(|value| value.as_str())
    {
        push_unique(&mut candidates, reference.to_string());
    }
    if let Some(evidence_refs) = entry
        .get("evidence_refs")
        .and_then(|value| value.as_array())
    {
        for reference in evidence_refs.iter().filter_map(|value| value.as_str()) {
            if reference.trim().ends_with("task_packet.json") {
                push_unique(&mut candidates, reference.to_string());
            }
        }
    }
    for reference in candidates {
        let Some(path) = resolve_evidence_ref_path(root, &reference) else {
            continue;
        };
        let Ok(content) = fs::read_to_string(path) else {
            continue;
        };
        let Ok(value) = serde_json::from_str::<serde_json::Value>(&content) else {
            continue;
        };
        return Some(value);
    }
    None
}

fn resolve_evidence_ref_path(root: &Path, reference: &str) -> Option<PathBuf> {
    let trimmed = reference.trim();
    if trimmed.is_empty()
        || trimmed.starts_with("accepted_worker_evidence:")
        || trimmed.starts_with("accepted_worker_evidence_task:")
        || trimmed.starts_with("accepted_worker_evidence_index:")
        || trimmed.starts_with("main_agent_worker_artifact_decision::")
        || trimmed.starts_with("review_packet:")
        || trimmed.starts_with("review_trace:")
    {
        return None;
    }
    let path = PathBuf::from(trimmed);
    if path.is_absolute() {
        return Some(path);
    }
    let joined = root.join(trimmed);
    if joined.exists() {
        return Some(joined);
    }
    if root.file_name().and_then(|value| value.to_str()) == Some(".pmcli") {
        if let Some(stripped) = trimmed.strip_prefix(".pmcli/") {
            let joined = root.join(stripped);
            if joined.exists() {
                return Some(joined);
            }
        }
        if let Some(parent) = root.parent() {
            let joined = parent.join(trimmed);
            if joined.exists() {
                return Some(joined);
            }
        }
    }
    Some(joined)
}

fn push_repair_lineage_anchors_from_json_array(
    refs: &mut Vec<String>,
    value: Option<&serde_json::Value>,
) {
    if let Some(values) = value.and_then(|value| value.as_array()) {
        for reference in values.iter().filter_map(|value| value.as_str()) {
            push_repair_lineage_anchor(refs, reference);
        }
    }
}

fn push_review_lineage_anchors_from_json_array(
    refs: &mut Vec<String>,
    value: Option<&serde_json::Value>,
) {
    if let Some(values) = value.and_then(|value| value.as_array()) {
        for reference in values.iter().filter_map(|value| value.as_str()) {
            push_review_lineage_anchor(refs, reference);
        }
    }
}

fn push_review_lineage_anchor(refs: &mut Vec<String>, reference: &str) {
    if let Some(anchor) = normalize_review_lineage_anchor(reference) {
        push_unique(refs, anchor);
    }
}

fn push_repair_lineage_anchor(refs: &mut Vec<String>, reference: &str) {
    if let Some(anchor) = normalize_repair_lineage_anchor(reference) {
        push_unique(refs, anchor);
    }
}

fn normalize_review_lineage_anchor(reference: &str) -> Option<String> {
    let trimmed = reference.trim();
    if trimmed.is_empty() {
        return None;
    }
    if let Some(review_id) = extract_review_id(trimmed) {
        return Some(format!("review:{review_id}"));
    }
    None
}

fn normalize_repair_lineage_anchor(reference: &str) -> Option<String> {
    let trimmed = reference.trim();
    if trimmed.is_empty() {
        return None;
    }
    if let Some(review_id) = extract_review_id(trimmed) {
        return Some(format!("review:{review_id}"));
    }
    if let Some(obligation_id) = extract_obligation_id(trimmed) {
        return Some(format!("obligation:{obligation_id}"));
    }
    let lower = trimmed.to_ascii_lowercase();
    if lower.starts_with("failed_stage_review:") || lower.starts_with("failed_review:") {
        return Some(format!("failed_review:{lower}"));
    }
    None
}

fn extract_review_id(reference: &str) -> Option<String> {
    extract_identifier_with_prefix(reference, "rev_")
}

fn extract_obligation_id(reference: &str) -> Option<String> {
    extract_identifier_with_prefix(reference, "obl_")
}

fn extract_identifier_with_prefix(reference: &str, prefix: &str) -> Option<String> {
    let start = reference.find(prefix)?;
    let tail = &reference[start..];
    let identifier: String = tail
        .chars()
        .take_while(|ch| ch.is_ascii_alphanumeric() || *ch == '_' || *ch == '-')
        .collect();
    if identifier.len() > prefix.len() {
        Some(identifier)
    } else {
        None
    }
}

fn accepted_worker_evidence_entry_targets_board_task(
    entry: &serde_json::Value,
    task: &GoalStageTaskMetadata,
) -> bool {
    entry
        .get("task_id")
        .and_then(|value| value.as_str())
        .map(|task_id| task_id.trim() == task.task_id.trim())
        .unwrap_or(false)
}

fn accepted_worker_evidence_entry_is_retired_json(entry: &serde_json::Value) -> bool {
    crate::accepted_worker_evidence::json_entry_is_retired(entry)
}

fn task_type_key_from_explicit_dependency_ref(dependency_id: &str) -> Option<String> {
    let trimmed = dependency_id.trim();
    if let Some(task_type) = trimmed.strip_prefix("accepted_worker_evidence:") {
        if task_type.contains("::") {
            return None;
        }
        return Some(normalize_task_key(task_type));
    }
    None
}

fn normalize_task_key(value: &str) -> String {
    value
        .chars()
        .map(|ch| {
            if ch.is_ascii_alphanumeric() {
                ch.to_ascii_lowercase()
            } else {
                ' '
            }
        })
        .collect::<String>()
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
}

fn main_agent_board_task_refs(
    data_dir: &Path,
    run: Option<&crate::orchestration::OrchestrationRun>,
    active_stage: Option<&crate::research::ResearchStageExecution>,
) -> Vec<String> {
    let mut refs = Vec::new();
    if let Some(run) = run {
        for step in &run.steps {
            for artifact in &step.artifacts {
                if artifact.starts_with("main_agent_board_task::") {
                    push_unique(&mut refs, artifact.clone());
                }
            }
        }
    }
    let task_dir = data_dir.join("main-agent-board").join("tasks");
    let Ok(entries) = fs::read_dir(&task_dir) else {
        return refs;
    };
    let active_stage_execution_id = active_stage.map(|stage| stage.execution_id.as_str());
    let active_stage_id = active_stage.map(|stage| stage.stage_id.as_str());
    let mut persisted = Vec::new();
    for entry in entries.flatten() {
        let path = entry.path();
        if path.extension().and_then(|value| value.to_str()) != Some("json") {
            continue;
        }
        let Ok(content) = fs::read_to_string(&path) else {
            continue;
        };
        let Ok(value) = serde_json::from_str::<serde_json::Value>(&content) else {
            continue;
        };
        if value.get("schema_version").and_then(|value| value.as_str())
            != Some("main_agent_board_task.v1")
        {
            continue;
        }
        if value
            .get("merged_into")
            .and_then(|value| value.as_str())
            .is_some()
            || !main_agent_board_task_status_is_dispatchable(
                value
                    .get("status")
                    .and_then(|value| value.as_str())
                    .unwrap_or_default(),
            )
        {
            continue;
        }
        if let Some(stage_execution_id) = active_stage_execution_id {
            let task_stage_execution_id = value
                .get("stage_execution_id")
                .and_then(|value| value.as_str())
                .unwrap_or_default();
            if !task_stage_execution_id.is_empty() && task_stage_execution_id != stage_execution_id
            {
                continue;
            }
        }
        if let Some(stage_id) = active_stage_id {
            let task_stage_id = value
                .get("stage_id")
                .and_then(|value| value.as_str())
                .unwrap_or_default();
            if !task_stage_id.is_empty() && task_stage_id != stage_id {
                continue;
            }
        }
        let Some(task_id) = value.get("task_id").and_then(|value| value.as_str()) else {
            continue;
        };
        let created_at = value
            .get("updated_at")
            .or_else(|| value.get("created_at"))
            .and_then(|value| value.as_str())
            .unwrap_or_default()
            .to_string();
        persisted.push((created_at, format!("main_agent_board_task::{task_id}")));
    }
    persisted.sort_by(|left, right| left.0.cmp(&right.0).then_with(|| left.1.cmp(&right.1)));
    for (_, task_ref) in persisted {
        push_unique(&mut refs, task_ref);
    }
    refs
}

fn main_agent_board_task_matches_active_stage(
    task: &GoalStageTaskMetadata,
    active_stage: Option<&crate::research::ResearchStageExecution>,
) -> bool {
    let Some(stage) = active_stage else {
        return true;
    };
    !task.stage_id.trim().is_empty()
        && !task.stage_execution_id.trim().is_empty()
        && task.stage_id == stage.stage_id
        && task.stage_execution_id == stage.execution_id
}

fn main_agent_board_routed_review_ids(data_dir: &Path) -> BTreeSet<String> {
    let mut review_ids = BTreeSet::new();
    let board_dir = data_dir.join("main-agent-board");
    let task_dirs = [board_dir.join("tasks"), board_dir.join("task-updates")];

    for task_dir in task_dirs {
        let Ok(entries) = fs::read_dir(&task_dir) else {
            continue;
        };
        for entry in entries.flatten() {
            let path = entry.path();
            if path.extension().and_then(|value| value.to_str()) != Some("json") {
                continue;
            }
            let Ok(content) = fs::read_to_string(&path) else {
                continue;
            };
            let Ok(value) = serde_json::from_str::<serde_json::Value>(&content) else {
                continue;
            };
            if path
                .parent()
                .and_then(|parent| parent.file_name())
                .and_then(|name| name.to_str())
                == Some("tasks")
            {
                collect_repair_review_ids_from_board_task(&value, &mut review_ids);
            } else {
                collect_repair_review_ids_from_task_update(&value, &mut review_ids);
            }
        }
    }

    let obligation_dir = board_dir.join("obligation-decisions");
    let Ok(entries) = fs::read_dir(&obligation_dir) else {
        return review_ids;
    };
    for entry in entries.flatten() {
        let path = entry.path();
        if path.extension().and_then(|value| value.to_str()) != Some("json") {
            continue;
        }
        let Ok(content) = fs::read_to_string(&path) else {
            continue;
        };
        let Ok(value) = serde_json::from_str::<serde_json::Value>(&content) else {
            continue;
        };
        collect_repair_review_ids_from_obligation_decision(&value, &mut review_ids);
    }

    review_ids
}

fn collect_repair_review_ids_from_board_task(
    value: &serde_json::Value,
    review_ids: &mut BTreeSet<String>,
) {
    if value.get("schema_version").and_then(|value| value.as_str())
        != Some("main_agent_board_task.v1")
    {
        return;
    }
    let task_type = json_string(value, "task_type").unwrap_or_default();
    let task_id = json_string(value, "task_id").unwrap_or_default();
    let objective = json_string(value, "objective").unwrap_or_default();
    let input_artifact_refs = json_string_vec(value, "input_artifact_refs");
    let review_findings_refs = json_string_vec(value, "review_findings_refs");
    let blocker_refs = json_string_vec(value, "blocker_refs");
    let review_target_task_ids = json_string_vec(value, "review_target_task_ids");
    let review_target_evidence_refs = json_string_vec(value, "review_target_evidence_refs");
    let supersedes_task_ids = json_string_vec(value, "supersedes_task_ids");
    let replacement_of_task_ids = json_string_vec(value, "replacement_of_task_ids");
    let repair_like = main_agent_board_task_is_repair_like(
        &task_id,
        &task_type,
        &objective,
        &input_artifact_refs,
        &review_findings_refs,
        &blocker_refs,
        &review_target_task_ids,
        &review_target_evidence_refs,
        &supersedes_task_ids,
        &replacement_of_task_ids,
    );
    if repair_like {
        collect_repair_review_ids_from_text(review_ids, &task_id);
        collect_repair_review_ids_from_text(review_ids, &task_type);
        collect_repair_review_ids_from_text(review_ids, &objective);
        for reference in input_artifact_refs {
            collect_repair_review_ids_from_text(review_ids, &reference);
        }
    }
    for field in [
        "review_findings_refs",
        "blocker_refs",
        "review_target_task_ids",
        "review_target_evidence_refs",
        "supersedes_task_ids",
        "replacement_of_task_ids",
    ] {
        for reference in json_string_vec(value, field) {
            collect_repair_review_ids_from_text(review_ids, &reference);
        }
    }
}

fn collect_repair_review_ids_from_task_update(
    value: &serde_json::Value,
    review_ids: &mut BTreeSet<String>,
) {
    if value.get("schema_version").and_then(|value| value.as_str())
        != Some("main_agent_control_record.v1")
        || value.get("tool_name").and_then(|value| value.as_str()) != Some("update_board_task")
    {
        return;
    }
    let Some(arguments) = value.get("arguments") else {
        return;
    };
    let patch = arguments.get("patch").unwrap_or(&serde_json::Value::Null);
    let task_id = json_string(patch, "task_id")
        .or_else(|| json_string(arguments, "task_id"))
        .or_else(|| json_string(value, "target_id"))
        .unwrap_or_default();
    let task_type = json_string(patch, "task_type")
        .or_else(|| json_string(arguments, "task_type"))
        .unwrap_or_default();
    let objective = json_string(patch, "objective")
        .or_else(|| json_string(arguments, "objective"))
        .unwrap_or_default();
    let input_artifact_refs = json_string_vec(patch, "input_artifact_refs");
    let review_findings_refs = json_string_vec(patch, "review_findings_refs");
    let blocker_refs = json_string_vec(patch, "blocker_refs");
    let review_target_task_ids = json_string_vec(patch, "review_target_task_ids");
    let review_target_evidence_refs = json_string_vec(patch, "review_target_evidence_refs");
    let supersedes_task_ids = json_string_vec(patch, "supersedes_task_ids");
    let replacement_of_task_ids = json_string_vec(patch, "replacement_of_task_ids");
    let repair_like = main_agent_board_task_is_repair_like(
        &task_id,
        &task_type,
        &objective,
        &input_artifact_refs,
        &review_findings_refs,
        &blocker_refs,
        &review_target_task_ids,
        &review_target_evidence_refs,
        &supersedes_task_ids,
        &replacement_of_task_ids,
    );
    if repair_like {
        collect_repair_review_ids_from_text(review_ids, &task_id);
        collect_repair_review_ids_from_text(review_ids, &task_type);
        collect_repair_review_ids_from_text(review_ids, &objective);
        for reference in input_artifact_refs {
            collect_repair_review_ids_from_text(review_ids, &reference);
        }
        for field in ["target_id", "record_ref"] {
            if let Some(reference) = json_string(value, field) {
                collect_repair_review_ids_from_text(review_ids, &reference);
            }
        }
    }
    for field in [
        "review_findings_refs",
        "blocker_refs",
        "review_target_task_ids",
        "review_target_evidence_refs",
        "supersedes_task_ids",
        "replacement_of_task_ids",
    ] {
        for reference in json_string_vec(patch, field) {
            collect_repair_review_ids_from_text(review_ids, &reference);
        }
    }
}

fn collect_repair_review_ids_from_obligation_decision(
    value: &serde_json::Value,
    review_ids: &mut BTreeSet<String>,
) {
    if value.get("schema_version").and_then(|value| value.as_str())
        != Some("main_agent_obligation_decision.v1")
    {
        return;
    }
    let route = json_string(value, "route").unwrap_or_default();
    if !task_type_declares_repair_or_replacement(&route) {
        return;
    }
    collect_repair_review_ids_from_text(review_ids, &route);
    for field in ["obligation_id", "decision_id"] {
        if let Some(reference) = json_string(value, field) {
            collect_repair_review_ids_from_text(review_ids, &reference);
        }
    }
    for field in ["readiness_refs", "task_refs"] {
        for reference in json_string_vec(value, field) {
            collect_repair_review_ids_from_text(review_ids, &reference);
        }
    }
}

fn collect_repair_review_ids_from_text(review_ids: &mut BTreeSet<String>, value: &str) {
    review_ids.extend(review_refs::review_ids_in_text(value));
}

fn load_main_agent_published_stage_task(
    data_dir: &Path,
    task_ref: &str,
) -> Option<GoalStageTaskMetadata> {
    let task_id = task_ref.strip_prefix("main_agent_board_task::")?;
    let path = data_dir
        .join("main-agent-board")
        .join("tasks")
        .join(format!("{}.json", sanitize_file_component(task_id)));
    let content = fs::read_to_string(path).ok()?;
    let value: serde_json::Value = serde_json::from_str(&content).ok()?;
    let status = json_string(&value, "status").unwrap_or_default();
    if status == "merged" || !main_agent_board_task_status_is_dispatchable(&status) {
        return None;
    }
    Some(GoalStageTaskMetadata {
        task_id: json_string(&value, "task_id").unwrap_or_else(|| task_id.to_string()),
        stage_execution_id: json_string(&value, "stage_execution_id").unwrap_or_default(),
        stage_id: json_string(&value, "stage_id").unwrap_or_default(),
        task_type: json_string(&value, "task_type")?,
        worker_role: json_string(&value, "worker_role")?,
        objective: json_string(&value, "objective")?,
        input_artifact_refs: json_string_vec(&value, "input_artifact_refs"),
        required_canonical_artifacts: json_required_canonical_artifacts(
            &value,
            "required_canonical_artifacts",
        ),
        required_output_artifact_type: json_string(&value, "required_output_artifact_type")?,
        required_output_fields: json_string_vec(&value, "required_output_fields"),
        acceptance_checks: json_string_vec(&value, "acceptance_checks"),
        failure_signals: json_string_vec(&value, "failure_signals"),
        depends_on_task_ids: json_string_vec(&value, "depends_on_task_ids"),
        priority: value
            .get("priority")
            .and_then(|value| value.as_u64())
            .unwrap_or(1),
        status: "projected".to_string(),
        claimed_by_agent_id: None,
        output_artifact_refs: Vec::new(),
        review_findings_refs: json_string_vec(&value, "review_findings_refs"),
        blocker_refs: json_string_vec(&value, "blocker_refs"),
        review_target_task_ids: json_string_vec(&value, "review_target_task_ids"),
        review_target_evidence_refs: json_string_vec(&value, "review_target_evidence_refs"),
        supersedes_task_ids: json_string_vec(&value, "supersedes_task_ids"),
        replacement_of_task_ids: json_string_vec(&value, "replacement_of_task_ids"),
        current_evidence_set_id: json_string(&value, "current_evidence_set_id"),
        consumed_input_required: value
            .get("consumed_input_required")
            .and_then(|value| value.as_bool())
            .unwrap_or(false),
    })
}

fn main_agent_board_task_status_is_dispatchable(status: &str) -> bool {
    match status.trim() {
        "" | "published" | "ready" | "pending" | "open" | "gated" => true,
        "accepted" | "complete" | "completed" | "closed" | "merged" | "cancelled" | "canceled" => {
            false
        }
        _ => true,
    }
}

fn main_agent_board_stage_task_contract_violation(
    task: &GoalStageTaskMetadata,
    active_stage: Option<&crate::research::ResearchStageExecution>,
) -> Option<String> {
    if let Some(violation) = main_agent_board_stage_task_ref_contract_violation(task) {
        return Some(violation);
    }
    if let Some(violation) = crate::board_task_contract::self_reference_contract_violation(
        &task.task_id,
        &task.supersedes_task_ids,
        &task.replacement_of_task_ids,
    ) {
        return Some(violation);
    }
    if stage_task_type_is_synthesis(&task.task_type) && task.worker_role != "research_synthesizer" {
        return Some(format!(
            "stage artifact synthesis task `{}` must use worker_role `research_synthesizer`, but worker_role is `{}`",
            task.task_id, task.worker_role
        ));
    }
    if stage_task_type_is_synthesis(&task.task_type)
        && task
            .input_artifact_refs
            .iter()
            .chain(task.review_target_evidence_refs.iter())
            .map(|reference| reference.to_ascii_lowercase())
            .any(|reference| {
                reference.contains("runtime_diagnosis")
                    || reference.contains("repair_loop_strategy_diagnosis")
                    || reference.contains("adoption_snapshot_binding_diagnosis")
            })
    {
        return Some(format!(
            "stage artifact synthesis task `{}` consumes control-plane diagnosis evidence; runtime/adoption/repair-loop diagnosis may guide main-agent routing but is not stage-content evidence and must not be dispatched into canonical synthesis",
            task.task_id
        ));
    }
    if crate::board_task_contract::task_type_is_lifecycle_only(&task.task_type) {
        return Some(format!(
            "task `{}` uses task_type `{}` as a lifecycle label; task_type must name the concrete stage evidence slot, while repair context belongs in review_findings_refs, blocker_refs, replacement_of_task_ids, review_target_task_ids, and acceptance_checks",
            task.task_id, task.task_type
        ));
    }
    if let Some(violation) = main_agent_board_repair_task_contract_violation(
        &task.task_id,
        &task.task_type,
        &task.objective,
        &task.input_artifact_refs,
        &task.review_findings_refs,
        &task.blocker_refs,
        &task.review_target_task_ids,
        &task.review_target_evidence_refs,
        &task.supersedes_task_ids,
        &task.replacement_of_task_ids,
        &task.acceptance_checks,
    ) {
        return Some(violation);
    }
    if !stage_task_type_is_synthesis(&task.task_type)
        && !is_stage_artifact_repair_task(&task.task_type)
    {
        return None;
    }
    let stage_id = if !task.stage_id.trim().is_empty() {
        task.stage_id.as_str()
    } else {
        active_stage
            .map(|stage| stage.stage_id.as_str())
            .unwrap_or("")
    };
    if stage_id.trim().is_empty() {
        return None;
    }
    let expected = stage_artifact_type_for_stage(stage_id);
    if task.required_output_artifact_type.trim() == expected {
        return None;
    }
    Some(format!(
        "stage artifact synthesis or repair task `{}` must output `{expected}` for stage `{stage_id}`, but required_output_artifact_type is `{}`",
        task.task_id,
        task.required_output_artifact_type
    ))
}

#[cfg(test)]
fn main_agent_board_task_value_contract_violation(
    value: &serde_json::Value,
    active_stage: Option<&crate::research::ResearchStageExecution>,
) -> Option<String> {
    let task_type = value
        .get("task_type")
        .and_then(|value| value.as_str())
        .unwrap_or_default();
    let worker_role = value
        .get("worker_role")
        .and_then(|value| value.as_str())
        .unwrap_or_default();
    let task_id = value
        .get("task_id")
        .and_then(|value| value.as_str())
        .unwrap_or("unknown");
    if let Some(violation) = main_agent_board_task_value_ref_contract_violation(task_id, value) {
        return Some(violation);
    }
    if stage_task_type_is_synthesis(task_type) && worker_role != "research_synthesizer" {
        return Some(format!(
            "stage artifact synthesis task `{task_id}` must use worker_role `research_synthesizer`, but worker_role is `{worker_role}`"
        ));
    }
    if crate::board_task_contract::task_type_is_lifecycle_only(task_type) {
        return Some(format!(
            "task `{task_id}` uses task_type `{task_type}` as a lifecycle label; task_type must name the concrete stage evidence slot, while repair context belongs in review_findings_refs, blocker_refs, replacement_of_task_ids, review_target_task_ids, and acceptance_checks"
        ));
    }
    let objective = json_string(value, "objective").unwrap_or_default();
    let input_artifact_refs = json_string_vec(value, "input_artifact_refs");
    let review_findings_refs = json_string_vec(value, "review_findings_refs");
    let blocker_refs = json_string_vec(value, "blocker_refs");
    let review_target_task_ids = json_string_vec(value, "review_target_task_ids");
    let review_target_evidence_refs = json_string_vec(value, "review_target_evidence_refs");
    let supersedes_task_ids = json_string_vec(value, "supersedes_task_ids");
    let replacement_of_task_ids = json_string_vec(value, "replacement_of_task_ids");
    let acceptance_checks = json_string_vec(value, "acceptance_checks");
    if let Some(violation) = main_agent_board_repair_task_contract_violation(
        task_id,
        task_type,
        &objective,
        &input_artifact_refs,
        &review_findings_refs,
        &blocker_refs,
        &review_target_task_ids,
        &review_target_evidence_refs,
        &supersedes_task_ids,
        &replacement_of_task_ids,
        &acceptance_checks,
    ) {
        return Some(violation);
    }
    if !stage_task_type_is_synthesis(task_type) && !is_stage_artifact_repair_task(task_type) {
        return None;
    }
    let stage_id = value
        .get("stage_id")
        .and_then(|value| value.as_str())
        .filter(|stage_id| !stage_id.trim().is_empty())
        .or_else(|| active_stage.map(|stage| stage.stage_id.as_str()))?;
    let expected = stage_artifact_type_for_stage(stage_id);
    let required = value
        .get("required_output_artifact_type")
        .and_then(|value| value.as_str())
        .unwrap_or_default();
    if required.trim() == expected {
        return None;
    }
    Some(format!(
        "stage artifact synthesis or repair task `{task_id}` must output `{expected}` for stage `{stage_id}`, but required_output_artifact_type is `{required}`"
    ))
}

fn main_agent_board_stage_task_ref_contract_violation(
    task: &GoalStageTaskMetadata,
) -> Option<String> {
    for (field, refs) in [
        (
            board_task_refs::BoardTaskRefField::InputArtifactRefs,
            task.input_artifact_refs.as_slice(),
        ),
        (
            board_task_refs::BoardTaskRefField::DependsOnTaskIds,
            task.depends_on_task_ids.as_slice(),
        ),
        (
            board_task_refs::BoardTaskRefField::ReviewFindingsRefs,
            task.review_findings_refs.as_slice(),
        ),
        (
            board_task_refs::BoardTaskRefField::BlockerRefs,
            task.blocker_refs.as_slice(),
        ),
        (
            board_task_refs::BoardTaskRefField::ReviewTargetTaskIds,
            task.review_target_task_ids.as_slice(),
        ),
        (
            board_task_refs::BoardTaskRefField::ReviewTargetEvidenceRefs,
            task.review_target_evidence_refs.as_slice(),
        ),
        (
            board_task_refs::BoardTaskRefField::SupersedesTaskIds,
            task.supersedes_task_ids.as_slice(),
        ),
        (
            board_task_refs::BoardTaskRefField::ReplacementOfTaskIds,
            task.replacement_of_task_ids.as_slice(),
        ),
    ] {
        if let Some(err) = board_task_refs::first_ref_field_violation(field, refs) {
            return Some(format!("task `{}` {}", task.task_id, err.message()));
        }
    }
    None
}

#[cfg(test)]
fn main_agent_board_task_value_ref_contract_violation(
    task_id: &str,
    value: &serde_json::Value,
) -> Option<String> {
    for (field, field_name) in board_task_refs::BOARD_TASK_REF_ARRAY_FIELDS {
        let refs = json_string_vec(value, field_name);
        if let Some(err) = board_task_refs::first_ref_field_violation(*field, &refs) {
            return Some(format!("task `{task_id}` {}", err.message()));
        }
    }
    None
}

