fn normalize_stage_task_semantic_review_mode(mode: &str) -> String {
    match mode.trim().to_ascii_lowercase().as_str() {
        "provider" | "provider-backed" | "provider_backed" | "live" | "" => "provider".to_string(),
        "local" | "local-preflight" | "local_preflight" => "local".to_string(),
        "off" | "disabled" | "none" => "off".to_string(),
        other => other.to_string(),
    }
}

fn normalize_agent_team_worker_mode(mode: &str) -> String {
    match mode.trim().to_ascii_lowercase().as_str() {
        "provider" | "provider-backed" | "provider_backed" | "live" => "provider".to_string(),
        "local" | "local-preflight" | "local_preflight" | "" => "local".to_string(),
        "off" | "disabled" | "none" => "off".to_string(),
        other => other.to_string(),
    }
}

fn write_json_atomic<T: Serialize>(path: &Path, value: &T) -> Result<(), MissionFrameError> {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent)?;
    }
    let temp_path = path.with_extension("json.tmp");
    fs::write(&temp_path, serde_json::to_string_pretty(value)?)?;
    fs::rename(temp_path, path)?;
    Ok(())
}

fn write_text_atomic(path: &Path, contents: &str) -> Result<(), MissionFrameError> {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent)?;
    }
    let temp_path = path.with_extension("tmp");
    fs::write(&temp_path, contents)?;
    fs::rename(temp_path, path)?;
    Ok(())
}

impl GoalTargetRunSnapshot {
    fn from_progress(progress: &crate::orchestration::OrchestrationProgressProjection) -> Self {
        Self {
            run_id: progress.run_id.clone(),
            objective: progress.objective.clone(),
            status: progress.status.clone(),
            progress_percent: progress.percent,
            done_steps: progress.done_steps,
            total_steps: progress.total_steps,
            blocked_steps: progress.blocked_steps,
            current_step_id: progress.current_step_id.clone(),
            current_step_title: progress.current_step_title.clone(),
        }
    }
}

impl GoalTaskPoolEntry {
    fn new(
        entry_id: impl Into<String>,
        bucket_id: impl Into<String>,
        title: impl Into<String>,
        summary: impl Into<String>,
        source: GoalTaskPoolEntrySource,
    ) -> Self {
        Self {
            entry_id: entry_id.into(),
            bucket_id: bucket_id.into(),
            title: title.into(),
            summary: summary.into(),
            status: "projected".to_string(),
            source,
            action_policy: None,
            action_refs: Vec::new(),
            recommended_command: Vec::new(),
            stage_task: None,
        }
    }

    fn with_status(mut self, status: impl Into<String>) -> Self {
        self.status = status.into();
        self
    }

    fn with_action_policy(mut self, policy: impl Into<String>) -> Self {
        self.action_policy = Some(policy.into());
        self
    }

    fn with_action_ref(mut self, action: GoalTaskPoolEntryActionRef) -> Self {
        self.action_refs.push(action);
        self
    }

    fn with_recommended_command<I, S>(mut self, command: I) -> Self
    where
        I: IntoIterator<Item = S>,
        S: Into<String>,
    {
        self.recommended_command = command.into_iter().map(Into::into).collect();
        self
    }

    fn with_stage_task(mut self, stage_task: GoalStageTaskMetadata) -> Self {
        self.stage_task = Some(stage_task);
        self
    }
}

impl GoalTaskPoolEntryActionRef {
    fn new(action_id: &str, label: &str, intent: &str) -> Self {
        Self {
            action_id: action_id.to_string(),
            label: label.to_string(),
            requires_input: false,
            input_key: None,
            input_value: None,
            intent: intent.to_string(),
        }
    }

    fn with_input(mut self, key: &str, value: impl Into<String>) -> Self {
        self.requires_input = true;
        self.input_key = Some(key.to_string());
        self.input_value = Some(value.into());
        self
    }
}

impl GoalTaskPoolEntrySource {
    fn new(source_kind: impl Into<String>, source_id: impl Into<String>) -> Self {
        Self {
            source_kind: source_kind.into(),
            source_id: source_id.into(),
        }
    }
}

