pub fn advance(
    data_dir: &Path,
    workspace_root: &Path,
    project_id: &str,
) -> Result<GoalAdvanceResult, MissionFrameError> {
    let frame = read_frame(data_dir)?;
    validate_project_id(project_id, &frame)?;
    let mut warnings = Vec::new();
    let mut run = crate::orchestration::load_active_run(data_dir)
        .map_err(|err| MissionFrameError::Invalid(err.to_string()))?
        .unwrap_or_else(|| seed_goal_run(data_dir, &frame, workspace_root));
    run.automation_mode = frame.automation_mode;
    let mut action = consume_resolved_goal_repair_review(data_dir, &frame, &mut run)?
        .unwrap_or_else(|| advance_run_once(&mut run));
    let consumed_repair_review = action == "consume_resolved_repair_review";
    crate::orchestration::save_run(data_dir, &run)
        .map_err(|err| MissionFrameError::Invalid(err.to_string()))?;
    let mut task_pool =
        build_task_pool_snapshot(data_dir, workspace_root, project_id, Some(&frame));
    if !consumed_repair_review && goal_run_needs_dispatch_reopen(&run, &task_pool) {
        reopen_goal_run_for_dispatch(&mut run);
        action = "reopen_dispatch_for_ready_task".to_string();
        crate::orchestration::save_run(data_dir, &run)
            .map_err(|err| MissionFrameError::Invalid(err.to_string()))?;
        task_pool = build_task_pool_snapshot(data_dir, workspace_root, project_id, Some(&frame));
    }
    let mut acceptance =
        accept_next_goal_task_output(data_dir, workspace_root, project_id, &frame, &mut run)?;
    if acceptance.is_some() {
        crate::orchestration::save_run(data_dir, &run)
            .map_err(|err| MissionFrameError::Invalid(err.to_string()))?;
        task_pool = build_task_pool_snapshot(data_dir, workspace_root, project_id, Some(&frame));
    }
    let provider_failure_acceptance = acceptance
        .as_ref()
        .map(|acceptance| acceptance.status == "provider_failed")
        .unwrap_or(false);
    let dispatches = if provider_failure_acceptance {
        Vec::new()
    } else {
        dispatch_next_goal_tasks(data_dir, workspace_root, &frame, &mut run, &task_pool)?
    };
    let dispatch = dispatches.first().cloned();
    crate::orchestration::save_run(data_dir, &run)
        .map_err(|err| MissionFrameError::Invalid(err.to_string()))?;
    if !dispatches.is_empty() {
        mark_goal_run_step_running(&mut run, "goal_acceptance");
        crate::orchestration::save_run(data_dir, &run)
            .map_err(|err| MissionFrameError::Invalid(err.to_string()))?;
    }
    if acceptance.is_none() && dispatches.is_empty() {
        acceptance =
            accept_next_goal_task_output(data_dir, workspace_root, project_id, &frame, &mut run)?;
    }
    if acceptance.is_some() {
        crate::orchestration::save_run(data_dir, &run)
            .map_err(|err| MissionFrameError::Invalid(err.to_string()))?;
    }
    let stage_decision = auto_handle_low_risk_stage_decision(
        data_dir,
        workspace_root,
        project_id,
        &frame,
        &mut run,
    )?;
    crate::orchestration::save_run(data_dir, &run)
        .map_err(|err| MissionFrameError::Invalid(err.to_string()))?;
    task_pool = build_task_pool_snapshot(data_dir, workspace_root, project_id, Some(&frame));
    if mark_idle_acceptance_blocked_by_task_pool(&mut run, &task_pool) {
        crate::orchestration::save_run(data_dir, &run)
            .map_err(|err| MissionFrameError::Invalid(err.to_string()))?;
        task_pool = build_task_pool_snapshot(data_dir, workspace_root, project_id, Some(&frame));
    }
    if task_pool.summary.blocked > 0 {
        warnings.push("goal task pool has blocked entries".to_string());
    }
    if task_pool.summary.needs_approval > 0 {
        warnings.push("goal task pool has entries waiting for approval".to_string());
    }
    Ok(GoalAdvanceResult {
        schema_version: "goal_advance_result.v1".to_string(),
        status: "advanced".to_string(),
        action,
        project_id: project_id.to_string(),
        mission_frame_ref: mission_frame_ref(data_dir),
        run,
        dispatches,
        dispatch,
        acceptance,
        stage_decision,
        next_recommended_action: task_pool.next_recommended_action.clone(),
        task_pool,
        warnings,
    })
}

fn frame_uses_autonomous_research_stage_protocol(frame: &MissionFrame) -> bool {
    frame
        .evidence_refs
        .iter()
        .any(|reference| reference == AUTONOMOUS_RESEARCH_STAGE_PROTOCOL_REF)
}

pub fn start_fresh_goal_run(
    data_dir: &Path,
    workspace_root: &Path,
    frame: &MissionFrame,
    reason: &str,
) -> Result<crate::orchestration::OrchestrationRun, MissionFrameError> {
    let mut run = seed_goal_run(data_dir, frame, workspace_root);
    run.control_commands
        .push(crate::orchestration::RunControlCommand::new(
            "start",
            reason.to_string(),
        ));
    crate::orchestration::save_run(data_dir, &run)
        .map_err(|err| MissionFrameError::Invalid(err.to_string()))?;
    Ok(run)
}

fn seed_goal_run(
    data_dir: &Path,
    frame: &MissionFrame,
    _workspace_root: &Path,
) -> crate::orchestration::OrchestrationRun {
    let mut run = crate::orchestration::OrchestrationRun::new(
        format!("goal_run_{}", timestamp_string()),
        frame.current_implementation_goal.clone(),
        frame.automation_mode.as_str(),
    );
    run.status = "running".to_string();
    run.automation_mode = frame.automation_mode;
    run.steps = vec![
        crate::orchestration::OrchestrationStep::new(
            "goal_scope",
            "Confirm goal boundary and success criteria",
            crate::orchestration::OrchestrationStepStatus::Done,
        )
        .with_artifact(mission_frame_ref(data_dir)),
        crate::orchestration::OrchestrationStep::new(
            "goal_task_pool",
            "Derive goal task pool from research, agents, reviews, and ProjectOps",
            crate::orchestration::OrchestrationStepStatus::Running,
        )
        .with_worker("main-agent")
        .with_gate(format!(
            "automation_mode:{}",
            frame.automation_mode.as_str()
        ))
        .with_continuation("inspect goal task pool before dispatch"),
        crate::orchestration::OrchestrationStep::new(
            "goal_dispatch",
            "Dispatch or request approval for the next eligible agent task",
            crate::orchestration::OrchestrationStepStatus::Pending,
        )
        .with_gate("task_packet_review_gate"),
        crate::orchestration::OrchestrationStep::new(
            "goal_acceptance",
            "Review agent outputs and decide continue, repair, review, or complete",
            crate::orchestration::OrchestrationStepStatus::Pending,
        )
        .with_gate("review_packet_or_user_acceptance"),
    ];
    run
}

fn advance_run_once(run: &mut crate::orchestration::OrchestrationRun) -> String {
    if run_has_pending_goal_repair_review(run) {
        run.status = "blocked".to_string();
        run.control_commands
            .push(crate::orchestration::RunControlCommand::with_step(
                "status",
                Some("goal_acceptance".to_string()),
                "goal advance is waiting for repair review before retrying acceptance",
            ));
        return "await_repair_review".to_string();
    }
    if matches!(run.status.as_str(), "paused" | "blocked" | "replanning") {
        run.status = "running".to_string();
        run.control_commands
            .push(crate::orchestration::RunControlCommand::new(
                "resume",
                "goal advance resumed the active goal run",
            ));
        return "resume_goal_run".to_string();
    }
    if let Some(blocked_step) = run
        .steps
        .iter_mut()
        .find(|step| step.status == crate::orchestration::OrchestrationStepStatus::Blocked)
    {
        let step_id = blocked_step.step_id.clone();
        blocked_step.status = crate::orchestration::OrchestrationStepStatus::Running;
        run.status = "running".to_string();
        run.control_commands
            .push(crate::orchestration::RunControlCommand::with_step(
                "retry",
                Some(step_id),
                "goal advance retried a blocked goal-run step",
            ));
        return "retry_blocked_step".to_string();
    }
    if let Some(pending_step) = run
        .steps
        .iter_mut()
        .find(|step| step.status == crate::orchestration::OrchestrationStepStatus::Pending)
    {
        let step_id = pending_step.step_id.clone();
        pending_step.status = crate::orchestration::OrchestrationStepStatus::Running;
        run.status = "running".to_string();
        run.control_commands
            .push(crate::orchestration::RunControlCommand::with_step(
                "advance",
                Some(step_id),
                "goal advance selected the next pending goal-run step",
            ));
        return "start_pending_step".to_string();
    }
    if run
        .steps
        .iter()
        .all(|step| step.status == crate::orchestration::OrchestrationStepStatus::Done)
    {
        run.status = "accepted".to_string();
        run.control_commands
            .push(crate::orchestration::RunControlCommand::new(
                "accept",
                "goal advance found all goal-run steps done",
            ));
        return "accept_completed_run".to_string();
    }
    run.status = "running".to_string();
    run.control_commands
        .push(crate::orchestration::RunControlCommand::new(
            "status",
            "goal advance refreshed active goal-run state",
        ));
    "refresh_goal_state".to_string()
}

fn goal_run_needs_dispatch_reopen(
    run: &crate::orchestration::OrchestrationRun,
    task_pool: &GoalTaskPoolSnapshot,
) -> bool {
    matches!(run.status.as_str(), "accepted" | "blocked" | "running")
        && !goal_dispatch_step_is_running(run)
        && goal_run_has_real_dispatchable_entry(run, task_pool)
}

fn mark_idle_acceptance_blocked_by_task_pool(
    run: &mut crate::orchestration::OrchestrationRun,
    task_pool: &GoalTaskPoolSnapshot,
) -> bool {
    if task_pool.summary.blocked == 0
        || !active_goal_task_claims(run).is_empty()
        || goal_run_has_real_dispatchable_entry(run, task_pool)
    {
        return false;
    }
    let Some(step) = run
        .steps
        .iter_mut()
        .find(|step| step.step_id == "goal_acceptance")
    else {
        return false;
    };
    if step.status != crate::orchestration::OrchestrationStepStatus::Running {
        return false;
    }
    step.status = crate::orchestration::OrchestrationStepStatus::Blocked;
    push_unique(
        &mut step.continuation_points,
        "goal acceptance has no active worker claim to accept; blocked task-pool entries must be resolved before the loop can continue".to_string(),
    );
    run.status = "blocked".to_string();
    run.updated_at = timestamp_string();
    run.control_commands
        .push(crate::orchestration::RunControlCommand::with_step(
            "blocked_task_pool",
            Some("goal_acceptance".to_string()),
            "goal acceptance had no active claim or dispatchable task and the task pool still contains blocked entries",
        ));
    true
}

fn goal_run_has_real_dispatchable_entry(
    run: &crate::orchestration::OrchestrationRun,
    task_pool: &GoalTaskPoolSnapshot,
) -> bool {
    task_pool.entries.iter().any(|entry| {
        matches!(
            entry.source.source_kind.as_str(),
            "goal_repair_followup_task" | "research_status_report" | "main_agent_published_task"
        ) && entry.bucket_id == "ready_to_run"
            && entry.action_policy.as_deref() == Some("allowed")
            && entry_is_dispatchable_goal_task(entry)
            && (entry.source.source_kind == "main_agent_published_task"
                || !goal_task_entry_already_dispatched_or_claimed(run, &entry.entry_id))
    })
}

fn reopen_goal_run_for_dispatch(run: &mut crate::orchestration::OrchestrationRun) {
    run.status = "running".to_string();
    mark_goal_run_step_done(run, "goal_task_pool");
    mark_goal_run_step_running(run, "goal_dispatch");
    if let Some(step) = run
        .steps
        .iter_mut()
        .find(|step| step.step_id == "goal_acceptance")
    {
        if step.status == crate::orchestration::OrchestrationStepStatus::Done {
            step.status = crate::orchestration::OrchestrationStepStatus::Pending;
        }
    }
    run.updated_at = timestamp_string();
    run.control_commands
        .push(crate::orchestration::RunControlCommand::with_step(
            "continue",
            Some("goal_dispatch".to_string()),
            "goal run reopened dispatch because accepted run still has ready stage-local task-pool work",
        ));
}

fn run_has_pending_goal_repair_review(run: &crate::orchestration::OrchestrationRun) -> bool {
    run.steps.iter().any(|step| {
        step.step_id == "goal_acceptance"
            && step.status == crate::orchestration::OrchestrationStepStatus::Blocked
            && goal_repair_review_refs_from_step(step)
                .iter()
                .any(|repair| !goal_repair_review_has_outcome_artifact(run, &repair.review_id))
    })
}

fn consume_resolved_goal_repair_review(
    data_dir: &Path,
    frame: &MissionFrame,
    run: &mut crate::orchestration::OrchestrationRun,
) -> Result<Option<String>, MissionFrameError> {
    let repairs = run
        .steps
        .iter()
        .find(|step| {
            step.step_id == "goal_acceptance"
                && step.status == crate::orchestration::OrchestrationStepStatus::Blocked
        })
        .map(goal_repair_review_refs_from_step)
        .unwrap_or_default();

    for repair in repairs {
        if goal_repair_review_is_consumed(run, &repair) {
            continue;
        }
        let review = crate::reviews::inspect(data_dir, &repair.review_id)
            .map_err(|err| MissionFrameError::Invalid(err.to_string()))?;
        if review.status != "resolved" {
            continue;
        }
        if review_verdict_passes(&review.latest_trace.verdict) {
            record_goal_repair_review_consumed(
                run,
                &repair,
                &review.latest_trace.verdict,
                "passed",
            );
            if frame_uses_autonomous_research_stage_protocol(frame) {
                record_goal_repair_review_waiting_for_main_agent_decision(
                    run, &repair, &review, "passed",
                );
            } else {
                record_goal_repair_followup_task(run, &repair, &review);
            }
            close_goal_task_claim(run, &repair.agent_id, "repair_review_passed");
            if let Some(step) = run
                .steps
                .iter_mut()
                .find(|step| step.step_id == "goal_acceptance")
            {
                push_unique(
                    &mut step.continuation_points,
                    format!(
                        "repair review {} passed; goal loop recorded the result for main-agent routing",
                        repair.review_id
                    ),
                );
            }
            run.status = "running".to_string();
            run.updated_at = timestamp_string();
            run.control_commands
                .push(crate::orchestration::RunControlCommand::with_step(
                    "resume",
                    Some("goal_acceptance".to_string()),
                    format!(
                        "goal advance consumed passing repair review {} for {}",
                        repair.review_id, repair.agent_id
                    ),
                ));
            return Ok(Some("consume_resolved_repair_review".to_string()));
        }

        if goal_repair_review_is_failed(run, &repair) {
            continue;
        }
        record_goal_repair_review_failed(
            run,
            &repair,
            &review.latest_trace.verdict,
            !frame_uses_autonomous_research_stage_protocol(frame),
        );
        run.status = "running".to_string();
        run.updated_at = timestamp_string();
        run.control_commands
            .push(crate::orchestration::RunControlCommand::with_step(
                "repair",
                Some("goal_acceptance".to_string()),
                format!(
                "goal repair review {} resolved with blocking verdict {}; waiting for main-agent routing",
                repair.review_id, review.latest_trace.verdict
            ),
            ));
        return Ok(Some(
            if frame_uses_autonomous_research_stage_protocol(frame) {
                "repair_review_resolved_waiting_main_agent_decision"
            } else {
                "repair_review_resolved_repair_queued"
            }
            .to_string(),
        ));
    }

    Ok(None)
}

fn record_goal_repair_review_failed(
    run: &mut crate::orchestration::OrchestrationRun,
    repair: &GoalRepairReviewRef,
    verdict: &str,
    queue_followup: bool,
) {
    close_goal_task_claim(run, &repair.agent_id, "repair_review_failed");
    let has_remaining_claims = !active_goal_task_claims(run).is_empty();
    if let Some(step) = run
        .steps
        .iter_mut()
        .find(|step| step.step_id == "goal_acceptance")
    {
        push_unique(
            &mut step.artifacts,
            goal_repair_review_failed_ref(repair, verdict),
        );
        if queue_followup {
            push_unique(&mut step.artifacts, goal_repair_followup_task_ref(repair));
        }
        push_unique(
            &mut step.continuation_points,
            if queue_followup {
                format!(
                    "repair review {} for {} failed with verdict {}; released the blocked claim and queued a repair follow-up task",
                    repair.review_id, repair.agent_id, verdict
                )
            } else if has_remaining_claims {
                format!(
                    "repair review {} for {} failed with verdict {}; released the blocked claim and will continue accepting remaining active claims before main-agent routing",
                    repair.review_id, repair.agent_id, verdict
                )
            } else {
                format!(
                    "repair review {} for {} failed with verdict {}; released the blocked claim and requires main-agent task routing",
                    repair.review_id, repair.agent_id, verdict
                )
            },
        );
        step.status = if queue_followup {
            crate::orchestration::OrchestrationStepStatus::Pending
        } else if has_remaining_claims {
            crate::orchestration::OrchestrationStepStatus::Running
        } else {
            crate::orchestration::OrchestrationStepStatus::Blocked
        };
    }
    if queue_followup {
        if let Some(step) = run
            .steps
            .iter_mut()
            .find(|step| step.step_id == "goal_dispatch")
        {
            step.status = crate::orchestration::OrchestrationStepStatus::Pending;
            push_unique(
                &mut step.continuation_points,
                format!(
                    "dispatch repair follow-up task after failed repair review {}",
                    repair.review_id
                ),
            );
        }
    }
}

fn record_goal_repair_review_waiting_for_main_agent_decision(
    run: &mut crate::orchestration::OrchestrationRun,
    repair: &GoalRepairReviewRef,
    review: &crate::reviews::ReviewInspectionResult,
    outcome: &str,
) {
    if let Some(step) = run
        .steps
        .iter_mut()
        .find(|step| step.step_id == "goal_acceptance")
    {
        push_unique(
            &mut step.artifacts,
            format!(
                "goal_repair_review_waiting_main_agent_decision::agent:{}::review:{}::{}",
                repair.agent_id, repair.review_id, outcome
            ),
        );
        push_unique(
            &mut step.continuation_points,
            format!(
                "repair review {} was consumed with outcome {}; main agent must publish or update board work before another repair attempt: {}",
                repair.review_id,
                outcome,
                compact_single_line(&review.latest_trace.response_text, 120)
            ),
        );
        step.status = crate::orchestration::OrchestrationStepStatus::Blocked;
    }
    if let Some(step) = run
        .steps
        .iter_mut()
        .find(|step| step.step_id == "goal_dispatch")
    {
        push_unique(
            &mut step.continuation_points,
            format!(
                "runtime did not dispatch repair follow-up for review {}; waiting for main-agent board task decision",
                repair.review_id
            ),
        );
    }
}

fn record_goal_repair_review_consumed(
    run: &mut crate::orchestration::OrchestrationRun,
    repair: &GoalRepairReviewRef,
    verdict: &str,
    outcome: &str,
) {
    if let Some(step) = run
        .steps
        .iter_mut()
        .find(|step| step.step_id == "goal_acceptance")
    {
        push_unique(
            &mut step.artifacts,
            goal_repair_review_consumed_ref(repair, verdict, outcome),
        );
        push_unique(
            &mut step.continuation_points,
            format!(
                "repair review {} for {} consumed as {} with verdict {}",
                repair.review_id, repair.agent_id, outcome, verdict
            ),
        );
    }
}

fn goal_repair_review_refs_from_step(
    step: &crate::orchestration::OrchestrationStep,
) -> Vec<GoalRepairReviewRef> {
    let mut repairs = Vec::new();
    for artifact in &step.artifacts {
        if let Some(repair) = parse_goal_repair_review_link_ref(artifact) {
            repairs.push(repair);
        }
    }
    if !repairs.is_empty() {
        return repairs;
    }

    let agents = step
        .artifacts
        .iter()
        .filter_map(|artifact| {
            artifact
                .strip_prefix("goal_repair_review::agent:")
                .map(str::to_string)
        })
        .collect::<Vec<_>>();
    let reviews = step
        .artifacts
        .iter()
        .filter_map(|artifact| {
            review_refs::parse_review_artifact_ref(artifact).and_then(|(kind, review_id)| {
                if matches!(kind, review_refs::ReviewArtifactKind::Packet) {
                    Some(review_id)
                } else {
                    None
                }
            })
        })
        .collect::<Vec<_>>();

    if agents.len() == 1 && reviews.len() == 1 {
        repairs.push(GoalRepairReviewRef {
            agent_id: agents[0].clone(),
            review_id: reviews[0].clone(),
        });
    }
    repairs
}

fn goal_repair_review_is_consumed(
    run: &crate::orchestration::OrchestrationRun,
    repair: &GoalRepairReviewRef,
) -> bool {
    let prefix = format!(
        "goal_repair_review_consumed::agent:{}::review:{}::",
        repair.agent_id, repair.review_id
    );
    run.steps.iter().any(|step| {
        step.artifacts
            .iter()
            .any(|artifact| artifact.starts_with(&prefix))
    })
}

fn goal_repair_review_is_failed(
    run: &crate::orchestration::OrchestrationRun,
    repair: &GoalRepairReviewRef,
) -> bool {
    let prefix = format!(
        "goal_repair_review_failed::agent:{}::review:{}::",
        repair.agent_id, repair.review_id
    );
    run.steps.iter().any(|step| {
        step.artifacts
            .iter()
            .any(|artifact| artifact.starts_with(&prefix))
    })
}

fn review_verdict_passes(verdict: &str) -> bool {
    matches!(verdict, "pass" | "passed" | "approved" | "ok")
}

