fn metric_parse_action_shell(safe_name: &str) -> String {
    let metrics = shell_quote(&format!(
        ".pmcli/goal-worker-output/actions/{safe_name}_metrics.tsv"
    ));
    format!(
        "metrics_ref={metrics}\n\
         {{\n\
           printf 'metric\\tvalue\\tsource\\n'\n\
           find . -path './.git' -prune -o -path './.pmcli' -prune -o \\( -iname '*.json' -o -iname '*.jsonl' -o -iname '*.csv' -o -iname '*.log' \\) -type f -print 2>/dev/null | head -n 20 | while read -r f; do\n\
             awk -v file=\"$f\" 'BEGIN{{IGNORECASE=1}} /accuracy|acc|score|loss|metric|reward/ {{gsub(/[`\\r]/,\"\",$0); print \"observed\\t\" substr($0,1,120) \"\\t\" file; found=1}} END{{}}' \"$f\" 2>/dev/null | head -n 5\n\
           done\n\
         }} > \"$metrics_ref\"\n\
         if test \"$(wc -l < \"$metrics_ref\" | tr -d ' ')\" = 1; then printf 'missing\\tmissing evidence: no metric-like rows parsed\\tbounded_parser\\n' >> \"$metrics_ref\"; fi\n\
         printf -- '- metric table: `%s`\\n' \"$metrics_ref\"\n\
         printf -- '- parsing script or command: `awk metric parser over json jsonl csv log refs`\\n'\n\
         printf -- '- raw result refs: `%s`\\n' \"$(find . -path './.git' -prune -o -path './.pmcli' -prune -o \\( -iname '*.json' -o -iname '*.jsonl' -o -iname '*.csv' -o -iname '*.log' \\) -type f -print 2>/dev/null | head -n 20 | sed 's#^./##' | paste -sd ',' -)\"\n\
         printf -- '- anomaly list: `%s`\\n' \"$(grep -Ei 'nan|inf|error|fail|missing' \"$metrics_ref\" 2>/dev/null | head -n 5 | paste -sd ';' -)\"\n"
    )
}

