fn comma_or_none(values: &[String]) -> String {
    if values.is_empty() {
        "none".to_string()
    } else {
        values.join(", ")
    }
}

fn goal_dispatch_local_command(
    frame: &MissionFrame,
    run: &crate::orchestration::OrchestrationRun,
    entry: &GoalTaskPoolEntry,
) -> String {
    let recommended = if entry.recommended_command.is_empty() {
        "none".to_string()
    } else {
        entry.recommended_command.join(" ")
    };
    let safe_name = sanitize_file_component(&entry.entry_id);
    let stage_contract = entry
        .stage_task
        .as_ref()
        .map(render_stage_task_dispatch_contract)
        .unwrap_or_else(|| "No stage-local task metadata on this entry.".to_string());
    let stage_worker_evidence =
        render_stage_task_worker_evidence(entry.stage_task.as_ref(), &safe_name);
    let collaboration_protocol = render_goal_worker_collaboration_protocol_summary();
    let stage_probe_command = entry
        .stage_task
        .as_ref()
        .map(render_stage_task_local_probe_shell)
        .unwrap_or_else(|| {
            "printf -- '- stage_real_probe_status: `not_stage_task`\\n'".to_string()
        });
    let stage_action_command = entry
        .stage_task
        .as_ref()
        .map(|stage_task| render_stage_task_local_action_shell(stage_task, &safe_name))
        .unwrap_or_else(|| "printf -- '- local_action_status: `not_stage_task`\\n'".to_string());
    let brief = format!(
        "# Astra Goal Worker Evidence Brief\n\n\
         ## Claimed Task\n\n\
         - task_pool_entry_id: `{}`\n\
         - entry_title: `{}`\n\
         - entry_source: `{}:{}`\n\
         - run_id: `{}`\n\
         - automation_mode: `{}`\n\
         - recommended_command: `{}`\n\n\
         ## Stage-Local Contract\n\n\
         {}\n\n\
         {}\n\n\
         ## Astra Collaboration Protocol\n\n\
         {}\n\n\
         ## Goal Context\n\n\
         - project_max_goal: {}\n\
         - milestone_goal: {}\n\
         - current_implementation_goal: {}\n\n\
         ## Worker Contract\n\n\
         This bounded local worker claimed the board-visible task for the main agent. It must not decide final research quality by itself. The main autonomous research agent must inspect this brief, the task packet, runtime record, stdout/stderr, and output manifest before writing or revising the canonical paper.\n\n\
         ## Evidence Probe\n\n\
         The command below records local repository facts from the worker worktree so the supervisor can distinguish a real claimed task from a policy-only placeholder.\n",
        entry.entry_id,
        entry.title,
        entry.source.source_kind,
        entry.source.source_id,
        run.run_id,
        frame.automation_mode.as_str(),
        recommended,
        stage_contract,
        stage_worker_evidence,
        collaboration_protocol,
        frame.project_max_goal,
        frame.milestone_goal,
        goal_dispatch_current_implementation_goal(frame, entry)
    );
    format!(
        "set -eu\n\
         mkdir -p .pmcli/goal-worker-output\n\
         out=.pmcli/goal-worker-output/{safe_name}.md\n\
         cat > \"$out\" <<'ASTRA_GOAL_WORKER_BRIEF'\n\
         {brief}\n\
         ASTRA_GOAL_WORKER_BRIEF\n\
         {{\n\
           printf '\\n## Repository Snapshot\\n\\n'\n\
           printf -- '- cwd: `%s`\\n' \"$(pwd)\"\n\
           printf -- '- git_head: `%s`\\n' \"$(git rev-parse --short HEAD 2>/dev/null || printf unknown)\"\n\
           printf -- '- dirty_path_count: `%s`\\n' \"$(git status --short 2>/dev/null | wc -l | tr -d ' ')\"\n\
           if test -f Cargo.toml; then printf -- '- cargo_manifest: `Cargo.toml`\\n'; fi\n\
           if test -d src; then printf -- '- src_file_count: `%s`\\n' \"$(find src -type f 2>/dev/null | wc -l | tr -d ' ')\"; fi\n\
           printf '\\n## Bounded Real Tool Probe Results\\n\\n'\n\
           {stage_probe_command}\n\
           printf '\\n## Bounded Local Tool Action Results\\n\\n'\n\
           {stage_action_command}\n\
           printf '\\n## Handoff\\n\\n'\n\
           printf 'Main agent should use this claimed task as evidence of board dispatch/agent claiming, then perform substantive research, implementation, experiment, review repair, and cleanup through the durable supervisor.\\n'\n\
         }} >> \"$out\"\n\
         cat \"$out\"",
        safe_name = safe_name,
        brief = brief,
        stage_probe_command = stage_probe_command,
        stage_action_command = stage_action_command
    )
}

fn record_goal_dispatch_artifact(
    run: &mut crate::orchestration::OrchestrationRun,
    dispatch_ref: &str,
    agent_result: &crate::agents::AgentStartResult,
) {
    if let Some(step) = run
        .steps
        .iter_mut()
        .find(|step| step.step_id == "goal_dispatch")
    {
        if step.worker.is_none() {
            step.worker = Some("main-agent".to_string());
        }
        push_unique(&mut step.artifacts, dispatch_ref.to_string());
        push_unique(
            &mut step.artifacts,
            format!("agent_task_packet:{}", agent_result.task_packet_path),
        );
        push_unique(
            &mut step.artifacts,
            format!("agent_runtime_record:{}", agent_result.runtime_record_path),
        );
        push_unique(
            &mut step.continuation_points,
            "wait for agent output manifest and run acceptance gate".to_string(),
        );
    }
    mark_goal_run_step_done(run, "goal_task_pool");
    mark_goal_run_step_done(run, "goal_dispatch");
    run.updated_at = timestamp_string();
    run.control_commands
        .push(crate::orchestration::RunControlCommand::with_step(
            "dispatch",
            Some("goal_dispatch".to_string()),
            format!(
                "goal advance dispatched {} from the goal task pool",
                agent_result.agent_id
            ),
        ));
}

fn record_goal_dispatch_wait(
    run: &mut crate::orchestration::OrchestrationRun,
    reason_code: &str,
    reason: &str,
) {
    if let Some(step) = run
        .steps
        .iter_mut()
        .find(|step| step.step_id == "goal_dispatch")
    {
        push_unique(
            &mut step.continuation_points,
            format!("dispatch_wait:{reason_code}:{reason}"),
        );
    }
    run.updated_at = timestamp_string();
    run.control_commands
        .push(crate::orchestration::RunControlCommand::with_step(
            "status",
            Some("goal_dispatch".to_string()),
            reason.to_string(),
        ));
}

fn record_goal_task_claim(
    run: &mut crate::orchestration::OrchestrationRun,
    entry: &GoalTaskPoolEntry,
    agent_result: &crate::agents::AgentStartResult,
) -> String {
    let claim_ref = goal_task_claim_ref(&entry.entry_id, &agent_result.agent_id);
    if let Some(step) = run
        .steps
        .iter_mut()
        .find(|step| step.step_id == "goal_dispatch")
    {
        push_unique(&mut step.artifacts, claim_ref.clone());
        push_unique(
            &mut step.continuation_points,
            format!(
                "goal task claim granted for {} to {}",
                entry.entry_id, agent_result.agent_id
            ),
        );
    }
    claim_ref
}

fn close_goal_task_claim(
    run: &mut crate::orchestration::OrchestrationRun,
    agent_id: &str,
    status: &str,
) -> Option<GoalTaskClaim> {
    let claim = active_goal_task_claims(run)
        .into_iter()
        .find(|claim| claim.agent_id == agent_id)?;
    let closed_ref = goal_task_claim_closed_ref(&claim.entry_id, &claim.agent_id, status);
    let target_step_id = if run
        .steps
        .iter()
        .any(|step| step.step_id == "goal_acceptance")
    {
        "goal_acceptance"
    } else {
        "goal_dispatch"
    };
    if let Some(step) = run
        .steps
        .iter_mut()
        .find(|step| step.step_id == target_step_id)
    {
        push_unique(&mut step.artifacts, closed_ref);
        push_unique(
            &mut step.continuation_points,
            format!(
                "goal task claim {} for {} is {}",
                claim.entry_id, claim.agent_id, status
            ),
        );
    }
    Some(claim)
}

fn block_goal_task_claim(
    run: &mut crate::orchestration::OrchestrationRun,
    agent_id: &str,
    status: &str,
) -> Option<GoalTaskClaim> {
    let claim = active_goal_task_claims(run)
        .into_iter()
        .find(|claim| claim.agent_id == agent_id)?;
    let blocked_ref = goal_task_claim_blocked_ref(&claim.entry_id, &claim.agent_id, status);
    let target_step_id = if run
        .steps
        .iter()
        .any(|step| step.step_id == "goal_acceptance")
    {
        "goal_acceptance"
    } else {
        "goal_dispatch"
    };
    if let Some(step) = run
        .steps
        .iter_mut()
        .find(|step| step.step_id == target_step_id)
    {
        push_unique(&mut step.artifacts, blocked_ref);
        push_unique(
            &mut step.continuation_points,
            format!(
                "goal task claim {} for {} is blocked by {}",
                claim.entry_id, claim.agent_id, status
            ),
        );
    }
    Some(claim)
}

pub fn active_goal_task_claims(run: &crate::orchestration::OrchestrationRun) -> Vec<GoalTaskClaim> {
    let mut claims = Vec::new();
    for step in &run.steps {
        for artifact in &step.artifacts {
            if let Some(claim) = parse_goal_task_claim_ref(artifact) {
                if !goal_task_claim_is_closed(run, &claim.entry_id, &claim.agent_id) {
                    claims.push(claim);
                }
            }
        }
    }
    claims
}

fn goal_task_claim_is_closed(
    run: &crate::orchestration::OrchestrationRun,
    entry_id: &str,
    agent_id: &str,
) -> bool {
    let prefix = format!("goal_task_claim_closed::{entry_id}::agent:{agent_id}::");
    run.steps.iter().any(|step| {
        step.artifacts
            .iter()
            .any(|artifact| artifact.starts_with(&prefix))
    })
}

pub fn goal_task_claim_is_blocked(
    run: &crate::orchestration::OrchestrationRun,
    entry_id: &str,
    agent_id: &str,
) -> bool {
    let prefix = format!("goal_task_claim_blocked::{entry_id}::agent:{agent_id}::");
    run.steps.iter().any(|step| {
        step.artifacts
            .iter()
            .any(|artifact| artifact.starts_with(&prefix))
    })
}

fn active_goal_task_claim_for_agent(
    run: &crate::orchestration::OrchestrationRun,
    agent_id: &str,
) -> Option<GoalTaskClaim> {
    active_goal_task_claims(run)
        .into_iter()
        .find(|claim| claim.agent_id == agent_id)
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct GoalTaskClaim {
    pub entry_id: String,
    pub agent_id: String,
}

fn goal_task_claim_ref(entry_id: &str, agent_id: &str) -> String {
    format!("goal_task_claim::{entry_id}::agent:{agent_id}")
}

fn goal_task_claim_closed_ref(entry_id: &str, agent_id: &str, status: &str) -> String {
    format!("goal_task_claim_closed::{entry_id}::agent:{agent_id}::{status}")
}

fn goal_task_claim_blocked_ref(entry_id: &str, agent_id: &str, status: &str) -> String {
    format!("goal_task_claim_blocked::{entry_id}::agent:{agent_id}::{status}")
}

fn parse_goal_task_claim_ref(value: &str) -> Option<GoalTaskClaim> {
    let rest = value.strip_prefix("goal_task_claim::")?;
    let (entry_id, agent_id) = rest.rsplit_once("::agent:")?;
    if entry_id.trim().is_empty() || agent_id.trim().is_empty() {
        return None;
    }
    Some(GoalTaskClaim {
        entry_id: entry_id.to_string(),
        agent_id: agent_id.to_string(),
    })
}

fn accept_next_goal_task_output(
    data_dir: &Path,
    workspace_root: &Path,
    project_id: &str,
    frame: &MissionFrame,
    run: &mut crate::orchestration::OrchestrationRun,
) -> Result<Option<GoalTaskAcceptanceResult>, MissionFrameError> {
    if !matches!(frame.automation_mode, GoalAutomationMode::FullAuto) {
        return Ok(None);
    }
    if !goal_acceptance_step_is_running(run) {
        return Ok(None);
    }
    if !automation_policy_allows_acceptance(frame.automation_mode) {
        return Ok(None);
    }

    let agents =
        crate::agents::list(data_dir).map_err(|err| MissionFrameError::Invalid(err.to_string()))?;
    let active_research_stage_ref = active_research_stage_execution_ref(data_dir, project_id);
    let active_claims = active_goal_task_claims(run);
    let ordered_agents = order_agents_for_goal_acceptance(agents.agents, &active_claims);
    for prefer_valid_acceptance in [true, false] {
        for agent in ordered_agents.clone() {
            if goal_agent_already_resolved(run, &agent.agent_id) {
                continue;
            }
            let claim = active_goal_task_claim_for_agent(run, &agent.agent_id);
            if !active_claims.is_empty() && claim.is_none() {
                continue;
            }
            if prefer_valid_acceptance && agent.lifecycle_status == "running" {
                continue;
            }
            let reclaimed = if agent.lifecycle_status == "running" {
                match crate::agents::reclaim_stale_running_agent(
                    data_dir,
                    &agent.agent_id,
                    STALE_RUNNING_AGENT_RECLAIM_AFTER_MS,
                ) {
                    Ok(reclaim) => reclaim.reclaimed,
                    Err(crate::agents::AgentError::UnknownAgent(_)) => false,
                    Err(err) => return Err(MissionFrameError::Invalid(err.to_string())),
                }
            } else {
                false
            };
            let inspection = match crate::agents::inspect(data_dir, &agent.agent_id) {
                Ok(inspection) => inspection,
                Err(crate::agents::AgentError::UnknownAgent(_)) => continue,
                Err(err) => return Err(MissionFrameError::Invalid(err.to_string())),
            };
            let lifecycle_status = inspection.runtime_record.lifecycle_status.as_str();
            if lifecycle_status == "running" {
                continue;
            }
            let valid_completed_output = lifecycle_status == "succeeded"
                && inspection.output_manifest.status == "complete"
                && inspection.output_manifest.validation_status == "valid";
            if agent_output_manifest_is_still_finalizing(
                lifecycle_status,
                &inspection.output_manifest,
            ) {
                continue;
            }
            if prefer_valid_acceptance && !valid_completed_output {
                continue;
            }
            if !prefer_valid_acceptance && valid_completed_output {
                continue;
            }
            if valid_completed_output {
                let mut stage_task_acceptance = claim
                    .as_ref()
                    .and_then(|claim| {
                        stage_task_for_claim(
                            data_dir,
                            workspace_root,
                            project_id,
                            frame,
                            run,
                            claim,
                        )
                    })
                    .map(|stage_task| evaluate_stage_task_acceptance(&inspection, &stage_task));
                if let Some(stage_task_acceptance) = stage_task_acceptance.as_ref() {
                    if !stage_task_acceptance.is_accepted() {
                        let review = open_goal_repair_review(
                            data_dir,
                            frame.automation_mode,
                            &inspection,
                            Some(stage_task_acceptance),
                        )
                        .map_err(|err| MissionFrameError::Invalid(err.to_string()))?;
                        let mut stage_task_acceptance = stage_task_acceptance.clone();
                        let review_packet_refs = review
                            .as_ref()
                            .map(|review| vec![review.packet_path.clone()])
                            .unwrap_or_default();
                        stage_task_acceptance.review_packet_refs = review_packet_refs.clone();
                        let diagnostic_refs = if review.is_none() {
                            vec![write_goal_acceptance_diagnostic(
                                data_dir,
                                "stage_task_acceptance_failed",
                                &inspection,
                                Some(&stage_task_acceptance),
                                stage_task_acceptance.repair_reason.as_deref(),
                            )?]
                        } else {
                            Vec::new()
                        };
                        let result = GoalTaskAcceptanceResult {
                            schema_version: "goal_task_acceptance_result.v1".to_string(),
                            status: "blocked".to_string(),
                            automation_mode: frame.automation_mode,
                            agent_id: agent.agent_id.clone(),
                            task_packet_ref: agent.task_packet_ref.clone(),
                            output_manifest_ref: agent.output_manifest_ref.clone(),
                            trace_refs: inspection.runtime_record.trace_refs.clone(),
                            worker_artifact_candidate_refs: worker_artifact_candidate_refs(
                                &inspection,
                            ),
                            verdict: review
                                .as_ref()
                                .map(|_| "stage_task_repair_review_opened")
                                .unwrap_or("stage_task_acceptance_failed")
                                .to_string(),
                            review_packet_refs,
                            diagnostic_refs,
                            stage_task_acceptance: Some(stage_task_acceptance),
                            research_stage_execution_ref: active_research_stage_ref.clone(),
                            task_pool_entry_id: claim.as_ref().map(|claim| claim.entry_id.clone()),
                            claim_ref: claim
                                .as_ref()
                                .map(|claim| goal_task_claim_ref(&claim.entry_id, &claim.agent_id)),
                            claim_status: claim.as_ref().map(|_| {
                                if review.is_some() {
                                    "blocked_repair_review_opened".to_string()
                                } else {
                                    "blocked_stage_task_acceptance_failed".to_string()
                                }
                            }),
                            provider_failure: None,
                        };
                        if let Some(review) = review.as_ref() {
                            record_goal_repair_review_artifact(run, frame, &result, review);
                        } else {
                            record_goal_acceptance_diagnostic_artifact(
                                run,
                                &result,
                                "stage task output failed deterministic acceptance; main agent must route repair or rejection",
                            );
                        }
                        return Ok(Some(result));
                    }
                }
                if let Some(stage_task_acceptance_value) = stage_task_acceptance.as_mut() {
                    let semantic_review = open_goal_stage_task_semantic_review(
                        data_dir,
                        frame.automation_mode,
                        &inspection,
                        stage_task_acceptance_value,
                    )
                    .map_err(|err| MissionFrameError::Invalid(err.to_string()))?;
                    stage_task_acceptance_value.review_packet_refs = semantic_review
                        .review
                        .as_ref()
                        .map(|review| vec![review.packet_path.clone()])
                        .unwrap_or_default();
                    stage_task_acceptance_value.semantic_review =
                        Some(semantic_review.result.clone());
                    if !stage_task_semantic_review_passes(&semantic_review.result) {
                        let review_packet_refs = semantic_review
                            .review
                            .as_ref()
                            .map(|review| vec![review.packet_path.clone()])
                            .unwrap_or_default();
                        let diagnostic_refs = semantic_review
                            .diagnostic_ref
                            .iter()
                            .cloned()
                            .collect::<Vec<_>>();
                        let result = GoalTaskAcceptanceResult {
                            schema_version: "goal_task_acceptance_result.v1".to_string(),
                            status: "blocked".to_string(),
                            automation_mode: frame.automation_mode,
                            agent_id: agent.agent_id.clone(),
                            task_packet_ref: agent.task_packet_ref.clone(),
                            output_manifest_ref: agent.output_manifest_ref.clone(),
                            trace_refs: inspection.runtime_record.trace_refs.clone(),
                            worker_artifact_candidate_refs: worker_artifact_candidate_refs(
                                &inspection,
                            ),
                            verdict: semantic_review
                                .review
                                .as_ref()
                                .map(|_| "stage_task_semantic_review_failed")
                                .unwrap_or("local_acceptance_preflight_failed")
                                .to_string(),
                            review_packet_refs,
                            diagnostic_refs,
                            stage_task_acceptance,
                            research_stage_execution_ref: active_research_stage_ref.clone(),
                            task_pool_entry_id: claim.as_ref().map(|claim| claim.entry_id.clone()),
                            claim_ref: claim
                                .as_ref()
                                .map(|claim| goal_task_claim_ref(&claim.entry_id, &claim.agent_id)),
                            claim_status: claim.as_ref().map(|_| {
                                if semantic_review.review.is_some() {
                                    "closed_semantic_review_failed".to_string()
                                } else {
                                    "blocked_local_acceptance_preflight_failed".to_string()
                                }
                            }),
                            provider_failure: None,
                        };
                        if let Some(review) = semantic_review.review.as_ref() {
                            record_goal_repair_review_artifact(run, frame, &result, review);
                        } else {
                            record_goal_acceptance_diagnostic_artifact(
                                run,
                                &result,
                                "local acceptance preflight blocked worker evidence; no semantic review was opened",
                            );
                        }
                        return Ok(Some(result));
                    }
                }
                let diagnostic_refs = stage_task_acceptance
                    .as_ref()
                    .and_then(|acceptance| acceptance.semantic_review.as_ref())
                    .filter(|review| review.execution_mode == "local_acceptance_preflight")
                    .map(|review| vec![review.review_packet_ref.clone()])
                    .unwrap_or_default();
                let result = GoalTaskAcceptanceResult {
                    schema_version: "goal_task_acceptance_result.v1".to_string(),
                    status: "accepted".to_string(),
                    automation_mode: frame.automation_mode,
                    agent_id: agent.agent_id.clone(),
                    task_packet_ref: agent.task_packet_ref.clone(),
                    output_manifest_ref: agent.output_manifest_ref.clone(),
                    trace_refs: inspection.runtime_record.trace_refs.clone(),
                    worker_artifact_candidate_refs: worker_artifact_candidate_refs(&inspection),
                    verdict: stage_task_acceptance
                        .as_ref()
                        .map(|_| "accepted_stage_task")
                        .unwrap_or("accepted_normal_task")
                        .to_string(),
                    review_packet_refs: stage_task_acceptance
                        .as_ref()
                        .map(|acceptance| acceptance.review_packet_refs.clone())
                        .unwrap_or_default(),
                    diagnostic_refs,
                    stage_task_acceptance,
                    research_stage_execution_ref: active_research_stage_ref.clone(),
                    task_pool_entry_id: claim.as_ref().map(|claim| claim.entry_id.clone()),
                    claim_ref: claim
                        .as_ref()
                        .map(|claim| goal_task_claim_ref(&claim.entry_id, &claim.agent_id)),
                    claim_status: claim.as_ref().map(|_| "closed_accepted".to_string()),
                    provider_failure: None,
                };
                record_goal_acceptance_artifact(run, &result);
                return Ok(Some(result));
            }

            if !agent_output_needs_repair_review(lifecycle_status, &inspection.output_manifest) {
                continue;
            }
            if let Some(provider_failure) =
                agent_team_worker_provider_failure(data_dir, &inspection)
            {
                let claim_ref = claim
                    .as_ref()
                    .map(|claim| goal_task_claim_ref(&claim.entry_id, &claim.agent_id));
                let claim_status = if claim.is_some() {
                    close_goal_task_claim(run, &agent.agent_id, "provider_execution_failed");
                    Some("closed_provider_execution_failed".to_string())
                } else {
                    None
                };
                let result = GoalTaskAcceptanceResult {
                    schema_version: "goal_task_acceptance_result.v1".to_string(),
                    status: "provider_failed".to_string(),
                    automation_mode: frame.automation_mode,
                    agent_id: agent.agent_id.clone(),
                    task_packet_ref: agent.task_packet_ref.clone(),
                    output_manifest_ref: agent.output_manifest_ref.clone(),
                    trace_refs: inspection.runtime_record.trace_refs.clone(),
                    worker_artifact_candidate_refs: worker_artifact_candidate_refs(&inspection),
                    verdict: "provider_execution_failed".to_string(),
                    review_packet_refs: Vec::new(),
                    diagnostic_refs: Vec::new(),
                    stage_task_acceptance: None,
                    research_stage_execution_ref: active_research_stage_ref.clone(),
                    task_pool_entry_id: claim.as_ref().map(|claim| claim.entry_id.clone()),
                    claim_ref,
                    claim_status,
                    provider_failure: Some(provider_failure),
                };
                record_goal_provider_failure_artifact(run, &result);
                return Ok(Some(result));
            }
            if reclaimed {
                let claim_ref = claim
                    .as_ref()
                    .map(|claim| goal_task_claim_ref(&claim.entry_id, &claim.agent_id));
                let claim_status = if claim.is_some() {
                    close_goal_task_claim(run, &agent.agent_id, "execution_lifecycle_failed");
                    Some("closed_execution_lifecycle_failed".to_string())
                } else {
                    None
                };
                let result = GoalTaskAcceptanceResult {
                    schema_version: "goal_task_acceptance_result.v1".to_string(),
                    status: "execution_failed".to_string(),
                    automation_mode: frame.automation_mode,
                    agent_id: agent.agent_id.clone(),
                    task_packet_ref: agent.task_packet_ref.clone(),
                    output_manifest_ref: inspection.runtime_record.output_manifest_ref.clone(),
                    trace_refs: inspection.runtime_record.trace_refs.clone(),
                    worker_artifact_candidate_refs: worker_artifact_candidate_refs(&inspection),
                    verdict: "stale_running_worker_reclaimed".to_string(),
                    review_packet_refs: Vec::new(),
                    diagnostic_refs: Vec::new(),
                    stage_task_acceptance: None,
                    research_stage_execution_ref: active_research_stage_ref.clone(),
                    task_pool_entry_id: claim.as_ref().map(|claim| claim.entry_id.clone()),
                    claim_ref,
                    claim_status,
                    provider_failure: None,
                };
                record_goal_execution_failure_artifact(run, &result);
                return Ok(Some(result));
            }
            let review =
                open_goal_repair_review(data_dir, frame.automation_mode, &inspection, None)
                    .map_err(|err| MissionFrameError::Invalid(err.to_string()))?;
            let review_packet_refs = review
                .as_ref()
                .map(|review| vec![review.packet_path.clone()])
                .unwrap_or_default();
            let diagnostic_refs = if review.is_none() {
                vec![write_goal_acceptance_diagnostic(
                    data_dir,
                    "worker_output_repair_required",
                    &inspection,
                    None,
                    Some("worker output failed lifecycle, manifest, or validation checks"),
                )?]
            } else {
                Vec::new()
            };
            let result = GoalTaskAcceptanceResult {
                schema_version: "goal_task_acceptance_result.v1".to_string(),
                status: "blocked".to_string(),
                automation_mode: frame.automation_mode,
                agent_id: agent.agent_id.clone(),
                task_packet_ref: agent.task_packet_ref.clone(),
                output_manifest_ref: agent.output_manifest_ref.clone(),
                trace_refs: inspection.runtime_record.trace_refs.clone(),
                worker_artifact_candidate_refs: worker_artifact_candidate_refs(&inspection),
                verdict: review
                    .as_ref()
                    .map(|_| "repair_review_opened")
                    .unwrap_or("worker_output_repair_required")
                    .to_string(),
                review_packet_refs,
                diagnostic_refs,
                stage_task_acceptance: None,
                research_stage_execution_ref: active_research_stage_ref.clone(),
                task_pool_entry_id: claim.as_ref().map(|claim| claim.entry_id.clone()),
                claim_ref: claim
                    .as_ref()
                    .map(|claim| goal_task_claim_ref(&claim.entry_id, &claim.agent_id)),
                claim_status: claim.as_ref().map(|_| {
                    if review.is_some() {
                        "blocked_repair_review_opened".to_string()
                    } else {
                        "blocked_worker_output_repair_required".to_string()
                    }
                }),
                provider_failure: None,
            };
            if let Some(review) = review.as_ref() {
                record_goal_repair_review_artifact(run, frame, &result, review);
            } else {
                record_goal_acceptance_diagnostic_artifact(
                    run,
                    &result,
                    "worker output failed deterministic acceptance; no repair review was opened",
                );
            }
            return Ok(Some(result));
        }
    }

    Ok(None)
}

fn order_agents_for_goal_acceptance(
    agents: Vec<crate::agents::AgentListEntry>,
    active_claims: &[GoalTaskClaim],
) -> Vec<crate::agents::AgentListEntry> {
    let mut enumerated = agents.into_iter().enumerate().collect::<Vec<_>>();
    enumerated.sort_by(|(left_index, left), (right_index, right)| {
        let left_rank = active_claims
            .iter()
            .position(|claim| claim.agent_id == left.agent_id)
            .unwrap_or(usize::MAX);
        let right_rank = active_claims
            .iter()
            .position(|claim| claim.agent_id == right.agent_id)
            .unwrap_or(usize::MAX);
        left_rank
            .cmp(&right_rank)
            .then_with(|| left_index.cmp(right_index))
    });
    enumerated.into_iter().map(|(_, agent)| agent).collect()
}

fn goal_acceptance_step_is_running(run: &crate::orchestration::OrchestrationRun) -> bool {
    run.steps.iter().any(|step| {
        step.step_id == "goal_acceptance"
            && step.status == crate::orchestration::OrchestrationStepStatus::Running
    })
}

fn automation_policy_allows_acceptance(mode: GoalAutomationMode) -> bool {
    crate::orchestration::GoalRunAutomationPolicyProjection::from_mode(mode)
        .action_policy("accept_normal_task")
        == Some("allowed")
}

fn goal_agent_already_resolved(
    run: &crate::orchestration::OrchestrationRun,
    agent_id: &str,
) -> bool {
    let acceptance_ref = format!("goal_acceptance::agent:{agent_id}");
    let diagnostic_ref = format!("goal_acceptance_diagnostic::agent:{agent_id}");
    let repair_ref = format!("goal_repair_review::agent:{agent_id}");
    let provider_failure_ref = format!("goal_provider_failure::agent:{agent_id}");
    let execution_failure_ref = format!("goal_execution_failure::agent:{agent_id}");
    run.steps.iter().any(|step| {
        step.artifacts.iter().any(|artifact| {
            artifact == &acceptance_ref
                || artifact == &diagnostic_ref
                || artifact == &repair_ref
                || artifact == &provider_failure_ref
                || artifact == &execution_failure_ref
        })
    })
}

fn record_goal_acceptance_artifact(
    run: &mut crate::orchestration::OrchestrationRun,
    acceptance: &GoalTaskAcceptanceResult,
) {
    if acceptance.claim_ref.is_some() {
        close_goal_task_claim(run, &acceptance.agent_id, "accepted");
    }
    if let Some(step) = run
        .steps
        .iter_mut()
        .find(|step| step.step_id == "goal_acceptance")
    {
        if step.worker.is_none() {
            step.worker = Some("main-agent".to_string());
        }
        push_unique(
            &mut step.artifacts,
            format!("goal_acceptance::agent:{}", acceptance.agent_id),
        );
        push_unique(
            &mut step.artifacts,
            format!("agent_output_manifest:{}", acceptance.output_manifest_ref),
        );
        if let Some(stage_ref) = acceptance.research_stage_execution_ref.as_deref() {
            push_unique(
                &mut step.artifacts,
                format!("research_stage_execution:{stage_ref}"),
            );
        }
        push_unique(
            &mut step.continuation_points,
            "accepted normal agent output; continue or finish goal based on remaining tasks"
                .to_string(),
        );
    }
    record_goal_research_stage_decision_needed(run, acceptance);
    mark_goal_run_step_done(run, "goal_task_pool");
    mark_goal_run_step_done(run, "goal_dispatch");
    if active_goal_task_claims(run).is_empty() {
        mark_goal_run_step_done(run, "goal_acceptance");
        maybe_finish_goal_run_after_acceptance(run);
    } else if let Some(step) = run
        .steps
        .iter_mut()
        .find(|step| step.step_id == "goal_acceptance")
    {
        step.status = crate::orchestration::OrchestrationStepStatus::Running;
        push_unique(
            &mut step.continuation_points,
            "accepted one agent output; continue acceptance for remaining active claims"
                .to_string(),
        );
        run.status = "running".to_string();
    }
    run.updated_at = timestamp_string();
    run.control_commands
        .push(crate::orchestration::RunControlCommand::with_step(
            "accept",
            Some("goal_acceptance".to_string()),
            format!(
                "goal advance accepted output manifest from {}",
                acceptance.agent_id
            ),
        ));
}

fn record_goal_repair_review_artifact(
    run: &mut crate::orchestration::OrchestrationRun,
    frame: &MissionFrame,
    acceptance: &GoalTaskAcceptanceResult,
    review: &crate::reviews::ReviewOpenResult,
) {
    if acceptance.claim_ref.is_some() {
        if acceptance.verdict == "stage_task_semantic_review_failed" {
            close_goal_task_claim(run, &acceptance.agent_id, "semantic_review_failed");
        } else {
            block_goal_task_claim(run, &acceptance.agent_id, "repair_review_opened");
        }
    }
    if let Some(step) = run
        .steps
        .iter_mut()
        .find(|step| step.step_id == "goal_acceptance")
    {
        if step.worker.is_none() {
            step.worker = Some("main-agent".to_string());
        }
        push_unique(
            &mut step.artifacts,
            format!("goal_repair_review::agent:{}", acceptance.agent_id),
        );
        push_unique(
            &mut step.artifacts,
            goal_repair_review_link_ref(&acceptance.agent_id, &review.packet.review_id),
        );
        push_unique(
            &mut step.artifacts,
            format!("agent_output_manifest:{}", acceptance.output_manifest_ref),
        );
        push_unique(
            &mut step.artifacts,
            format!("review_packet:{}", review.packet.review_id),
        );
        push_unique(&mut step.artifacts, review.packet_path.clone());
        if let Some(stage_ref) = acceptance.research_stage_execution_ref.as_deref() {
            push_unique(
                &mut step.artifacts,
                format!("research_stage_execution:{stage_ref}"),
            );
        }
        push_unique(
            &mut step.continuation_points,
            "failed agent output opened a repair review; inspect review before retry, repair, or pivot"
                .to_string(),
        );
    }
    mark_goal_run_step_done(run, "goal_task_pool");
    mark_goal_run_step_done(run, "goal_dispatch");
    mark_goal_run_step_blocked(run, "goal_acceptance");
    run.status = "blocked".to_string();
    run.updated_at = timestamp_string();
    run.control_commands
        .push(crate::orchestration::RunControlCommand::with_step(
            "replan",
            Some("goal_acceptance".to_string()),
            format!(
                "goal advance opened repair review {} for {}",
                review.packet.review_id, acceptance.agent_id
            ),
        ));
    if review.trace.verdict != "pending" && !review_verdict_passes(&review.trace.verdict) {
        let repair = GoalRepairReviewRef {
            agent_id: acceptance.agent_id.clone(),
            review_id: review.packet.review_id.clone(),
        };
        let runtime_may_queue_followup = !frame_uses_autonomous_research_stage_protocol(frame);
        record_goal_repair_review_failed(
            run,
            &repair,
            &review.trace.verdict,
            runtime_may_queue_followup,
        );
        let has_remaining_claims = !active_goal_task_claims(run).is_empty();
        run.status = if runtime_may_queue_followup || has_remaining_claims {
            "running".to_string()
        } else {
            "blocked".to_string()
        };
        run.updated_at = timestamp_string();
        run.control_commands
            .push(crate::orchestration::RunControlCommand::with_step(
                if runtime_may_queue_followup {
                    "repair"
                } else {
                    "await_main_agent_decision"
                },
                Some("goal_acceptance".to_string()),
                if runtime_may_queue_followup {
                    format!(
                        "goal advance converted resolved failed review {} into board-visible repair follow-up",
                        review.packet.review_id
                    )
                } else {
                    format!(
                        "goal advance recorded resolved failed review {} without runtime repair follow-up; main agent must route it",
                        review.packet.review_id
                    )
                },
        ));
    }
}

fn record_goal_acceptance_diagnostic_artifact(
    run: &mut crate::orchestration::OrchestrationRun,
    acceptance: &GoalTaskAcceptanceResult,
    continuation: &str,
) {
    if acceptance.claim_ref.is_some() {
        let claim_status = acceptance
            .claim_status
            .as_deref()
            .and_then(|status| status.strip_prefix("blocked_"))
            .unwrap_or(acceptance.verdict.as_str());
        block_goal_task_claim(run, &acceptance.agent_id, claim_status);
    }
    if let Some(step) = run
        .steps
        .iter_mut()
        .find(|step| step.step_id == "goal_acceptance")
    {
        if step.worker.is_none() {
            step.worker = Some("runtime".to_string());
        }
        push_unique(
            &mut step.artifacts,
            format!("goal_acceptance_diagnostic::agent:{}", acceptance.agent_id),
        );
        for diagnostic_ref in &acceptance.diagnostic_refs {
            push_unique(
                &mut step.artifacts,
                format!("goal_acceptance_diagnostic:{diagnostic_ref}"),
            );
        }
        push_unique(
            &mut step.artifacts,
            format!("agent_output_manifest:{}", acceptance.output_manifest_ref),
        );
        if let Some(stage_ref) = acceptance.research_stage_execution_ref.as_deref() {
            push_unique(
                &mut step.artifacts,
                format!("research_stage_execution:{stage_ref}"),
            );
        }
        push_unique(&mut step.continuation_points, continuation.to_string());
    }
    mark_goal_run_step_done(run, "goal_task_pool");
    mark_goal_run_step_done(run, "goal_dispatch");
    mark_goal_run_step_blocked(run, "goal_acceptance");
    run.status = "blocked".to_string();
    run.updated_at = timestamp_string();
    run.control_commands
        .push(crate::orchestration::RunControlCommand::with_step(
            "await_main_agent_decision",
            Some("goal_acceptance".to_string()),
            format!(
                "goal acceptance recorded diagnostic evidence for {}; main agent must route repair, retry, or rejection",
                acceptance.agent_id
            ),
        ));
}

fn record_goal_provider_failure_artifact(
    run: &mut crate::orchestration::OrchestrationRun,
    acceptance: &GoalTaskAcceptanceResult,
) {
    if let Some(step) = run
        .steps
        .iter_mut()
        .find(|step| step.step_id == "goal_acceptance")
    {
        if step.worker.is_none() {
            step.worker = Some("runtime".to_string());
        }
        push_unique(
            &mut step.artifacts,
            format!("goal_provider_failure::agent:{}", acceptance.agent_id),
        );
        push_unique(
            &mut step.artifacts,
            format!("agent_output_manifest:{}", acceptance.output_manifest_ref),
        );
        push_unique(
            &mut step.continuation_points,
            "agent-team worker provider failure released the claim for retry/failover without opening a research repair review"
                .to_string(),
        );
    }
    mark_goal_run_step_done(run, "goal_task_pool");
    mark_goal_run_step_running(run, "goal_dispatch");
    let no_active_claims = active_goal_task_claims(run).is_empty();
    if let Some(step) = run
        .steps
        .iter_mut()
        .find(|step| step.step_id == "goal_acceptance")
    {
        step.status = if no_active_claims {
            crate::orchestration::OrchestrationStepStatus::Pending
        } else {
            crate::orchestration::OrchestrationStepStatus::Running
        };
    }
    run.status = "running".to_string();
    run.updated_at = timestamp_string();
    run.control_commands
        .push(crate::orchestration::RunControlCommand::with_step(
            "provider_retry",
            Some("goal_acceptance".to_string()),
            format!(
                "goal advance classified provider failure for {} and released the claim for runtime retry policy",
                acceptance.agent_id
            ),
        ));
}

