    fn goal_acceptance_ready_run(mode: GoalAutomationMode) -> OrchestrationRun {
        let mut run = goal_dispatch_ready_run(mode);
        for step in &mut run.steps {
            step.status = match step.step_id.as_str() {
                "goal_acceptance" => OrchestrationStepStatus::Running,
                _ => OrchestrationStepStatus::Done,
            };
        }
        run
    }

