    #[test]
    fn stage_task_acceptance_scans_candidate_rubric_without_flagging_risk_rules_as_fabrication() {
        let inspection = agent_inspection_fixture_with_candidate_artifact(
            "literature_stage_acceptance_rubric.md",
            "# Stage Acceptance Rubric\n\n\
             required_output_artifact_type: `stage_acceptance_rubric`\n\n\
             ## Research Bottom Line\n\n\
             Every literature claim must be traceable to verifiable source metadata.\n\n\
             ## Expert Acceptance Target\n\n\
             Top-tier benchmark reviewers can audit why this literature stage supports a benchmark for LLM optimal decision-making under super-chaotic context.\n\n\
             ## Stage-Specific Pass Criteria\n\n\
             - rubric is stricter than minimum compliance\n\
             - rubric binds current stage context to next-stage dependencies\n\
             - rubric cannot waive system bottom-line rules\n\
             - rubric includes review-to-task and cleanup routing\n\
             - CandidateStageEvidencePlan contains concrete evidence_requirements the main agent can pass to record_stage_evidence_plan\n\
             - each evidence requirement names task_type, worker_role, objective, required_output_artifact_type, required_output_fields, acceptance_checks, failure_signals, and evidence_standard\n\
             - worker states that only the main agent may adopt or raise the candidate plan\n\n\
             ## CandidateStageEvidencePlan\n\n\
             stage_id: literature\n\
             stage_execution_id: stage_rubric\n\
             plan_source_refs: accepted_worker_evidence:acceptance standard setting\n\
             rationale: candidate plan only; main agent must decide adoption.\n\n\
             evidence_requirements:\n\
             - task_type: literature survey execution\n\
               worker_role: literature_survey_worker\n\
               objective: produce a source-grounded literature matrix for super-chaotic-context LLM decision benchmark design.\n\
               required_output_artifact_type: literature_matrix\n\
               required_output_fields: source entries, axis coverage counts, gap statement, downstream novelty binding\n\
               acceptance_checks: every entry has complete citation metadata; no fabricated citations are allowed; source rows are traceable\n\
               failure_signals: fabricated or placeholder citations detected; gap statement is vague; any source row is unverifiable\n\
               evidence_standard: source_grounding_required\n\n\
             ## Review-to-Task Routing\n\n\
             Fabricated citations must be rejected and routed to citation verification repair; missing gap precision routes to gap analysis repair.\n\n\
             ## DocFrame Evidence Refs\n\n\
             - worker candidate artifact: literature_stage_acceptance_rubric.md\n",
        );
        let stdout_ref = inspection.output_manifest.output_refs[0].r#ref.clone();
        fs::write(
            stdout_ref,
            "## Worker Output\n\n\
             Acceptance-check coverage: Pass - no fabricated citations, no placeholder entries, failure signals avoided.\n\
             CandidateStageEvidencePlan count summary: 1 evidence requirement with all required fields.\n",
        )
        .expect("stdout wrapper should write");
        let stage_task = GoalStageTaskMetadata {
            task_id: stage_task_id("stage_rubric", "acceptance standard setting"),
            stage_execution_id: "stage_rubric".to_string(),
            stage_id: "literature".to_string(),
            task_type: "acceptance standard setting".to_string(),
            worker_role: stage_worker_role("literature", "acceptance standard setting").to_string(),
            objective: "Draft strict literature acceptance criteria.".to_string(),
            input_artifact_refs: Vec::new(),
            required_canonical_artifacts: Vec::new(),
            required_output_artifact_type: "stage_acceptance_rubric".to_string(),
            required_output_fields: vec![
                "research bottom line".to_string(),
                "expert acceptance target".to_string(),
                "stage-specific pass criteria".to_string(),
                "CandidateStageEvidencePlan".to_string(),
                "evidence_requirements".to_string(),
                "task_type".to_string(),
                "worker_role".to_string(),
                "objective".to_string(),
                "required_output_artifact_type".to_string(),
                "required_output_fields".to_string(),
                "acceptance_checks".to_string(),
                "evidence_standard".to_string(),
                "failure_signals".to_string(),
                "review-to-task routing".to_string(),
                "DocFrame evidence refs".to_string(),
            ],
            acceptance_checks: vec![
                "rubric is stricter than minimum compliance".to_string(),
                "rubric binds current stage context to next-stage dependencies".to_string(),
                "rubric cannot waive system bottom-line rules".to_string(),
                "rubric includes review-to-task and cleanup routing".to_string(),
                "CandidateStageEvidencePlan contains concrete evidence_requirements the main agent can pass to record_stage_evidence_plan".to_string(),
                "each evidence requirement names task_type, worker_role, objective, required_output_artifact_type, required_output_fields, acceptance_checks, failure_signals, and evidence_standard".to_string(),
                "worker states that only the main agent may adopt or raise the candidate plan".to_string(),
            ],
            failure_signals: vec![
                "fabricated or placeholder citations detected".to_string(),
                "gap statement is vague".to_string(),
            ],
            depends_on_task_ids: Vec::new(),
            priority: 1,
            status: "claimed".to_string(),
            claimed_by_agent_id: Some(inspection.agent_id.clone()),
            output_artifact_refs: Vec::new(),
            review_findings_refs: Vec::new(),
            blocker_refs: Vec::new(),
            review_target_task_ids: Vec::new(),
            review_target_evidence_refs: Vec::new(),
            supersedes_task_ids: Vec::new(),
            replacement_of_task_ids: Vec::new(),
            current_evidence_set_id: None,
            consumed_input_required: false,
        };

        let acceptance = evaluate_stage_task_acceptance(&inspection, &stage_task);

        assert_eq!(acceptance.verdict, "accepted");
        assert!(
            acceptance
                .quality_profile
                .risks
                .iter()
                .all(|risk| !risk.contains("fabricated") && !risk.contains("placeholder")),
            "rubric risk rules and worker self-assessment must not become severe output risks: {:?}",
            acceptance.quality_profile.risks
        );
        assert_ne!(acceptance.quality_profile.level, "insufficient");
    }

