    #[test]
    fn loop_closure_projection_prioritizes_blocks_and_dispatchable_work() {
        let mut task_pool = GoalTaskPoolSnapshot {
            schema_version: "goal_task_pool_snapshot.v1".to_string(),
            authority_model: "test".to_string(),
            source: "test".to_string(),
            project_id: "project_loop_projection".to_string(),
            automation_mode: GoalAutomationMode::FullAuto,
            target_run: Some(GoalTargetRunSnapshot {
                run_id: "run_loop_projection".to_string(),
                objective: "Close the research loop".to_string(),
                status: "running".to_string(),
                progress_percent: 50,
                done_steps: 2,
                total_steps: 4,
                blocked_steps: 0,
                current_step_id: Some("goal_dispatch".to_string()),
                current_step_title: Some("Dispatch agent team work".to_string()),
            }),
            summary: GoalTaskPoolSummary {
                total: 2,
                ready_to_run: 1,
                running: 0,
                needs_approval: 0,
                needs_review: 0,
                waiting_on_dependencies: 0,
                blocked: 1,
            },
            entries: Vec::new(),
            next_recommended_action: "dispatch_next_allowed_goal_task".to_string(),
        };

        let blocked = loop_closure_projection(&task_pool, None, 0, false);
        assert_eq!(blocked.status, "blocked");
        assert!(!blocked.should_continue);
        assert_eq!(blocked.pause_reason.as_deref(), Some("blocked_goal_task"));
        assert_eq!(blocked.next_recommended_action, "resolve_blocked_goal_task");

        task_pool.summary.blocked = 0;
        task_pool.summary.ready_to_run = 1;
        let dispatchable = loop_closure_projection(&task_pool, None, 0, false);
        assert_eq!(dispatchable.status, "running");
        assert!(dispatchable.should_continue);
        assert_eq!(
            dispatchable.next_recommended_action,
            "dispatch_next_allowed_goal_task"
        );

        task_pool.automation_mode = GoalAutomationMode::HumanInTheLoop;
        let human_gate = loop_closure_projection(&task_pool, None, 0, false);
        assert_eq!(human_gate.status, "running");
        assert!(!human_gate.should_continue);
        assert_eq!(
            human_gate.pause_reason.as_deref(),
            Some("human_approval_mode")
        );

        task_pool.summary.ready_to_run = 0;
        if let Some(target_run) = task_pool.target_run.as_mut() {
            target_run.done_steps = target_run.total_steps;
            target_run.progress_percent = 100;
            target_run.current_step_id = None;
            target_run.current_step_title = None;
        }
        let completed = loop_closure_projection(&task_pool, None, 0, true);
        assert_eq!(completed.status, "completed");
        assert_eq!(
            completed.next_recommended_action,
            "summarize_goal_completion"
        );
        assert!(completed.accepted);
    }

    #[test]
    fn full_auto_loop_closure_continues_through_review_gate() {
        let mut task_pool = GoalTaskPoolSnapshot {
            schema_version: "goal_task_pool_snapshot.v1".to_string(),
            authority_model: "test".to_string(),
            source: "test".to_string(),
            project_id: "project_loop_review_gate".to_string(),
            automation_mode: GoalAutomationMode::FullAuto,
            target_run: Some(GoalTargetRunSnapshot {
                run_id: "run_loop_review_gate".to_string(),
                objective: "Let main agent inspect worker evidence".to_string(),
                status: "running".to_string(),
                progress_percent: 75,
                done_steps: 3,
                total_steps: 4,
                blocked_steps: 0,
                current_step_id: Some("goal_acceptance".to_string()),
                current_step_title: Some("Review worker evidence".to_string()),
            }),
            summary: GoalTaskPoolSummary {
                total: 1,
                needs_review: 1,
                ..GoalTaskPoolSummary::default()
            },
            entries: Vec::new(),
            next_recommended_action: "open_or_complete_review_gate".to_string(),
        };

        let full_auto = loop_closure_projection(&task_pool, None, 0, false);
        assert_eq!(full_auto.status, "running");
        assert!(full_auto.should_continue);
        assert_eq!(
            full_auto.next_recommended_action,
            "open_or_complete_review_gate"
        );
        assert_eq!(full_auto.pause_reason, None);

        task_pool.automation_mode = GoalAutomationMode::HumanInTheLoop;
        let human = loop_closure_projection(&task_pool, None, 0, false);
        assert_eq!(human.status, "needs_operator");
        assert!(!human.should_continue);
        assert_eq!(human.pause_reason.as_deref(), Some("review_gate_open"));
    }

