    #[test]
    fn status_projects_task_pool_snapshot_from_existing_runtime_state() {
        let workspace_root = temp_data_dir("goals_task_pool_snapshot");
        let data_dir = workspace_root.join(".pmcli");
        let project_id = "project_goal_pool_001";
        let frame = MissionFrame {
            frame_id: "mission_frame".to_string(),
            version: 1,
            project_id: project_id.to_string(),
            project_max_goal: "Drive a research goal loop".to_string(),
            milestone_goal: "Project the goal task pool".to_string(),
            current_implementation_goal: "Keep the task pool derived from live state".to_string(),
            priority_rule: PRIORITY_RULE.to_string(),
            non_goals: vec![],
            success_criteria: vec!["goal status includes a task pool".to_string()],
            evidence_refs: vec![],
            risk_notes: vec![],
            automation_mode: GoalAutomationMode::HighAutonomy,
            updated_at: "1".to_string(),
        };
        write_frame(&data_dir, &frame).expect("frame should write");
        let mut run = OrchestrationRun::new(
            "run_goal_pool_001",
            "Drive a research goal loop",
            "approved",
        );
        run.status = "running".to_string();
        run.automation_mode = GoalAutomationMode::HighAutonomy;
        run.steps = vec![
            OrchestrationStep::new(
                "step_ready",
                "Prepare next task",
                OrchestrationStepStatus::Pending,
            ),
            OrchestrationStep::new(
                "step_running",
                "Run current task",
                OrchestrationStepStatus::Running,
            ),
            OrchestrationStep::new(
                "step_blocked",
                "Resolve gate",
                OrchestrationStepStatus::Blocked,
            ),
        ];
        crate::orchestration::save_run(&data_dir, &run).expect("run should save");

        let status = status(&data_dir, &workspace_root, project_id).expect("goal status");

        assert_eq!(
            status.task_pool.schema_version,
            "goal_task_pool_snapshot.v1"
        );
        assert_eq!(status.task_pool.project_id, project_id);
        assert_eq!(
            status.task_pool.automation_mode,
            GoalAutomationMode::HighAutonomy
        );
        assert_eq!(status.task_pool.summary.ready_to_run, 2);
        assert_eq!(status.task_pool.summary.running, 1);
        assert_eq!(status.task_pool.summary.blocked, 1);
        assert_eq!(
            status.task_pool.summary.total,
            status.task_pool.entries.len()
        );
        assert!(status.task_pool.entries.iter().any(|entry| entry
            .entry_id
            .contains("orchestration_step::run_goal_pool_001::step_ready")));
        assert!(status.task_pool.entries.iter().any(|entry| {
            entry
                .entry_id
                .contains("automation_policy::high_autonomy::dispatch_agent_task")
        }));
        let policy = run.automation_policy_projection();
        assert_eq!(
            policy.action_policy("external_publish"),
            Some("hard_blocked")
        );
        assert!(status
            .task_pool
            .entries
            .iter()
            .all(|entry| !entry.entry_id.contains("external_publish")));
        assert!(status
            .task_pool
            .entries
            .iter()
            .any(|entry| entry.bucket_id == "needs_approval" || entry.bucket_id == "needs_review"));
        assert!(
            !status.task_pool.next_recommended_action.trim().is_empty(),
            "task pool should provide a next action"
        );
    }

