    #[test]
    fn resolved_repair_review_that_was_consumed_in_run_is_not_projected_as_running() {
        let workspace_root = temp_data_dir("goals_consumed_repair_review_projection");
        let data_dir = workspace_root.join(".pmcli");
        let project_id = "project_consumed_repair_review_projection";
        let frame = mission_frame_with_mode(project_id, GoalAutomationMode::FullAuto);
        write_frame(&data_dir, &frame).expect("frame should write");
        let review = crate::reviews::open(
            &data_dir,
            crate::reviews::ReviewOpenRequest {
                target_paths: vec!["research/stages/literature/literature_matrix.md".to_string()],
                objective: "blocked repair review fixture".to_string(),
                reviewer_role: "repair_reviewer".to_string(),
                review_model: "test-review-model".to_string(),
                blind_context: Vec::new(),
                review_materials: Vec::new(),
                executor_summary: None,
                evidence_required: Vec::new(),
                compare_against: None,
                retry_of: None,
                retry_attempt: 0,
                verdict: Some("blocked".to_string()),
                response_text: Some("blocked".to_string()),
            },
        )
        .expect("review should open");
        let repair = GoalRepairReviewRef {
            agent_id: "agent_consumed_fixture".to_string(),
            review_id: review.packet.review_id.clone(),
        };
        let mut run = goal_dispatch_ready_run(GoalAutomationMode::FullAuto);
        if let Some(step) = run
            .steps
            .iter_mut()
            .find(|step| step.step_id == "goal_acceptance")
        {
            step.status = OrchestrationStepStatus::Blocked;
            push_unique(
                &mut step.artifacts,
                format!("goal_repair_review::agent:{}", repair.agent_id),
            );
            push_unique(
                &mut step.artifacts,
                goal_repair_review_link_ref(&repair.agent_id, &repair.review_id),
            );
            push_unique(
                &mut step.artifacts,
                goal_repair_review_failed_ref(&repair, &review.trace.verdict),
            );
        }
        run.status = "running".to_string();
        crate::orchestration::save_run(&data_dir, &run).expect("run should save");

        let status = status(&data_dir, &workspace_root, project_id).expect("status should build");

        assert_eq!(status.task_pool.summary.running, 1);
        assert_eq!(
            status
                .task_pool
                .entries
                .iter()
                .filter(|entry| entry.source.source_kind == "review_packet")
                .count(),
            0
        );
    }

