    #[test]
    fn retired_same_type_evidence_does_not_block_board_task_adoption() {
        let task = GoalStageTaskMetadata {
            task_id: "research_stage_task::stage_literature_1::synthesis_retry".to_string(),
            stage_execution_id: "stage_literature_1".to_string(),
            stage_id: "literature".to_string(),
            task_type: "stage artifact synthesis".to_string(),
            worker_role: "research_synthesizer".to_string(),
            objective: "Retry synthesis after rejecting the stale candidate.".to_string(),
            input_artifact_refs: Vec::new(),
            required_canonical_artifacts: Vec::new(),
            required_output_artifact_type: "literature_matrix".to_string(),
            required_output_fields: vec!["citation ledger".to_string()],
            acceptance_checks: vec!["all rows have canonical source metadata".to_string()],
            failure_signals: Vec::new(),
            depends_on_task_ids: Vec::new(),
            priority: 1,
            status: "ready".to_string(),
            claimed_by_agent_id: None,
            output_artifact_refs: Vec::new(),
            review_findings_refs: Vec::new(),
            blocker_refs: Vec::new(),
            review_target_task_ids: Vec::new(),
            review_target_evidence_refs: Vec::new(),
            supersedes_task_ids: Vec::new(),
            replacement_of_task_ids: Vec::new(),
            current_evidence_set_id: None,
            consumed_input_required: false,
        };
        let mut entry = serde_json::json!({
            "agent_id": "agent_source_verification_accepted",
            "task_id": task.task_id.clone(),
            "task_type": task.task_type.clone(),
            "worker_role": task.worker_role.clone(),
            "required_output_artifact_type": task.required_output_artifact_type.clone(),
            "main_agent_decision_ref": "main_agent_worker_artifact_decision::fixture",
            "active_status": "active",
            "semantic_review": {
                "verdict": "pass",
                "score": 88,
                "reviewer_role": "literature_semantic_reviewer",
                "execution_mode": "openai_chat_completions_stream"
            }
        });
        assert!(
            accepted_worker_evidence_entry_is_adoption_ready_for_board_task(&entry, &task, None)
        );

        for retired_status in ["rejected", "deferred", "inactive", "superseded"] {
            entry["active_status"] = serde_json::json!(retired_status);
            assert!(
                !accepted_worker_evidence_entry_is_adoption_ready_for_board_task(
                    &entry, &task, None
                ),
                "{retired_status} evidence must not keep a board task waiting on adoption"
            );
        }
    }

