    #[test]
    fn stale_failed_agent_task_does_not_block_after_later_success_for_same_stage_task() {
        let workspace_root = temp_data_dir("goals_stale_failed_agent_retry_success");
        let data_dir = workspace_root.join(".pmcli");
        let project_id = "project_stale_failed_agent_retry_success";
        let frame = autonomous_research_frame_with_mode(project_id, GoalAutomationMode::FullAuto);
        write_frame(&data_dir, &frame).expect("frame should write");
        let mut run = goal_acceptance_ready_run(GoalAutomationMode::FullAuto);
        let retried_task_id =
            "research_stage_task::stage_literature_1::rubric_reviewable_repair_v2";
        let old_failed_agent = "agent_1779780234235396";
        let later_success_agent = "agent_1779780533061935";
        let unrelated_failed_task_id =
            "research_stage_task::stage_literature_1::unrelated_failed_task";
        let unrelated_failed_agent = "agent_1779780234235390";
        let dispatch_step = run
            .steps
            .iter_mut()
            .find(|step| step.step_id == "goal_dispatch")
            .expect("goal_dispatch step should exist");
        dispatch_step
            .artifacts
            .push(goal_task_claim_ref(retried_task_id, old_failed_agent));
        dispatch_step.artifacts.push(goal_task_claim_closed_ref(
            retried_task_id,
            old_failed_agent,
            "provider_execution_failed",
        ));
        dispatch_step
            .artifacts
            .push(goal_task_claim_ref(retried_task_id, later_success_agent));
        dispatch_step.artifacts.push(goal_task_claim_closed_ref(
            retried_task_id,
            later_success_agent,
            "accepted",
        ));
        dispatch_step.artifacts.push(goal_task_claim_ref(
            unrelated_failed_task_id,
            unrelated_failed_agent,
        ));
        dispatch_step.artifacts.push(goal_task_claim_closed_ref(
            unrelated_failed_task_id,
            unrelated_failed_agent,
            "provider_execution_failed",
        ));
        run.steps
            .iter_mut()
            .find(|step| step.step_id == "goal_acceptance")
            .expect("goal_acceptance step should exist")
            .artifacts
            .push(format!("goal_acceptance::agent:{later_success_agent}"));
        crate::orchestration::save_run(&data_dir, &run).expect("run should save");
        write_stage_task_agent_projection_fixture(
            &data_dir,
            &workspace_root,
            old_failed_agent,
            "failed",
            "failed",
            "invalid",
            "1779780234235",
            retried_task_id,
        );
        write_stage_task_agent_projection_fixture(
            &data_dir,
            &workspace_root,
            later_success_agent,
            "succeeded",
            "complete",
            "valid",
            "1779780533062",
            retried_task_id,
        );
        write_stage_task_agent_projection_fixture(
            &data_dir,
            &workspace_root,
            unrelated_failed_agent,
            "failed",
            "failed",
            "invalid",
            "1779780234235",
            unrelated_failed_task_id,
        );

        let status = status(&data_dir, &workspace_root, project_id).expect("status should build");

        assert!(
            status
                .task_pool
                .entries
                .iter()
                .all(|entry| entry.entry_id != format!("agent_task::{old_failed_agent}")),
            "a failed worker must not keep blocking once a later worker for the same stage task succeeds"
        );
        let unrelated_failed_entry = status
            .task_pool
            .entries
            .iter()
            .find(|entry| entry.entry_id == format!("agent_task::{unrelated_failed_agent}"))
            .expect("unrelated failed agent should still project");
        assert_eq!(unrelated_failed_entry.bucket_id, "blocked");
    }

