    #[test]
    fn advance_full_auto_dispatches_provider_agent_worker_in_background() {
        std::env::set_var("OPENAI_API_KEY", "sk-test");
        std::env::remove_var("RESEARCH_CLI_LIVE_PROVIDER");
        let workspace_root = temp_git_workspace("goals_full_auto_provider_dispatch");
        let data_dir = workspace_root.join(".pmcli");
        let project_id = "project_goal_dispatch_provider";
        let frame = mission_frame_with_mode(project_id, GoalAutomationMode::FullAuto);
        write_frame(&data_dir, &frame).expect("frame should write");
        save_agent_team_worker_policy(
            &data_dir,
            &GoalAgentTeamWorkerPolicy::new("provider", "test", None)
                .with_route(Some("openai".to_string()), Some("gpt-5.5".to_string())),
        )
        .expect("worker policy should write");
        crate::orchestration::save_run(
            &data_dir,
            &goal_dispatch_ready_run(GoalAutomationMode::FullAuto),
        )
        .expect("run should save");

        let result = advance(&data_dir, &workspace_root, project_id).expect("advance should work");
        let dispatch = result.dispatch.expect("dispatch should occur");

        assert_eq!(dispatch.runner_kind, "provider");
        let inspection =
            crate::agents::inspect(&data_dir, &dispatch.agent_id).expect("agent should inspect");
        assert_eq!(
            inspection.task_packet.runner_kind.as_deref(),
            Some("provider")
        );
        assert_eq!(inspection.runtime_record.lifecycle_status, "running");
        assert_eq!(inspection.output_manifest.status, "running");
        assert_eq!(inspection.output_manifest.validation_status, "pending");
        assert!(inspection
            .output_manifest
            .output_refs
            .iter()
            .any(|output| output.kind == "provider_worker_pending"));
        let identity_ref = inspection
            .runtime_record
            .runtime_identity_ref
            .as_ref()
            .expect("provider worker identity ref should exist");
        let identity: crate::agents::AgentRuntimeIdentity =
            serde_json::from_str(&fs::read_to_string(identity_ref).expect("identity should read"))
                .expect("identity should parse");
        assert_eq!(identity.runner_kind, "provider_agent_worker");
        assert_eq!(identity.authority_scope, "worker_evidence_only");
        assert_eq!(identity.provider_id.as_deref(), Some("openai"));
        assert_eq!(identity.lifecycle_status, "running");
        assert!(inspection
            .runtime_record
            .status_ref
            .as_ref()
            .and_then(|path| fs::read_to_string(path).ok())
            .map(|status| status.contains("supervisor_pid:"))
            .unwrap_or(false));
    }

    #[test]
    fn advance_full_auto_dispatches_multiple_distinct_goal_tasks() {
        let workspace_root = temp_git_workspace("goals_full_auto_multi_dispatch");
        let data_dir = workspace_root.join(".pmcli");
        let project_id = "project_goal_multi_dispatch";
        let frame = mission_frame_with_mode(project_id, GoalAutomationMode::FullAuto);
        write_frame(&data_dir, &frame).expect("frame should write");
        crate::research::record(
            &data_dir,
            project_id,
            crate::research::ResearchRecordRequest {
                kind: "goal".to_string(),
                title: "Seed pending research work".to_string(),
                stage_id: "implement-solution".to_string(),
                mode: "ready_to_execute".to_string(),
                decisions: Vec::new(),
                open_questions: Vec::new(),
                evidence_refs: Vec::new(),
            },
        )
        .expect("research record should create active thread");
        let span_id = crate::research::status(&data_dir, project_id)
            .expect("research status")
            .active_deliberation_span
            .expect("active span")
            .span_id;
        let mut span_value: serde_json::Value = serde_json::from_str(
            &fs::read_to_string(
                data_dir
                    .join("research")
                    .join("spans")
                    .join(format!("{span_id}.json")),
            )
            .expect("span should read"),
        )
        .expect("span should parse");
        span_value["pending_operations"] =
            serde_json::json!(["run_reference_scan", "run_patch_probe"]);
        fs::write(
            data_dir
                .join("research")
                .join("spans")
                .join(format!("{span_id}.json")),
            serde_json::to_string_pretty(&span_value).expect("span should serialize"),
        )
        .expect("span should write");
        let run = goal_dispatch_ready_run(GoalAutomationMode::FullAuto);
        crate::orchestration::save_run(&data_dir, &run).expect("run should save");

        let result = advance(&data_dir, &workspace_root, project_id).expect("advance should work");

        assert!(result.dispatches.len() > 1);
        assert!(result.dispatches.len() <= DEFAULT_MAX_FULL_AUTO_ACTIVE_GOAL_TASK_CLAIMS);
        assert_eq!(result.dispatch.as_ref(), result.dispatches.first());
        let mut entry_ids = result
            .dispatches
            .iter()
            .map(|dispatch| dispatch.task_pool_entry_id.clone())
            .collect::<Vec<_>>();
        entry_ids.sort();
        entry_ids.dedup();
        assert_eq!(entry_ids.len(), result.dispatches.len());
        assert_eq!(result.dispatches[0].active_claim_count_before_dispatch, 0);
        assert_eq!(result.dispatches[1].active_claim_count_before_dispatch, 1);
        assert_eq!(
            result
                .dispatches
                .last()
                .unwrap()
                .active_claim_count_before_dispatch,
            result.dispatches.len() - 1
        );
        assert!(result
            .dispatches
            .iter()
            .any(|dispatch| dispatch.task_pool_entry_id == "research_operation::0"));
        assert!(result
            .dispatches
            .iter()
            .any(|dispatch| dispatch.task_pool_entry_id == "research_operation::1"));
        let agents = crate::agents::list(&data_dir).expect("agents should list");
        assert_eq!(agents.total_count, result.dispatches.len());
        let loaded = crate::orchestration::load_active_run(&data_dir)
            .expect("run should load")
            .expect("run should exist");
        let active_claims = active_goal_task_claims(&loaded);
        assert!(active_claims.len() > 1);
        assert!(active_claims.len() <= result.dispatches.len());
        let repeat = advance(&data_dir, &workspace_root, project_id).expect("repeat advance");
        assert!(repeat.dispatches.is_empty());
        assert!(repeat.dispatch.is_none());
    }

    #[test]
    fn advance_reopens_blocked_acceptance_for_main_agent_published_ready_task() {
        let workspace_root = temp_git_workspace("goals_reopen_blocked_acceptance_dispatch");
        let data_dir = workspace_root.join(".pmcli");
        let project_id = "project_goal_reopen_blocked_acceptance";
        let frame = mission_frame_with_mode(project_id, GoalAutomationMode::FullAuto);
        write_frame(&data_dir, &frame).expect("frame should write");
        let record = crate::research::record(
            &data_dir,
            project_id,
            crate::research::ResearchRecordRequest {
                kind: "goal".to_string(),
                title: "Seed stage-local repair work".to_string(),
                stage_id: "literature".to_string(),
                mode: "ready_to_execute".to_string(),
                decisions: Vec::new(),
                open_questions: Vec::new(),
                evidence_refs: Vec::new(),
            },
        )
        .expect("research record should create active stage");
        let mut run = goal_dispatch_ready_run(GoalAutomationMode::FullAuto);
        for step in run.steps.iter_mut() {
            step.status = match step.step_id.as_str() {
                "goal_acceptance" => OrchestrationStepStatus::Blocked,
                _ => OrchestrationStepStatus::Done,
            };
        }
        run.status = "blocked".to_string();
        publish_main_agent_stage_task_fixture(
            &data_dir,
            &mut run,
            &record.stage_execution,
            "closest-family survey",
        );
        crate::orchestration::save_run(&data_dir, &run).expect("run should save");

        let result = advance(&data_dir, &workspace_root, project_id)
            .expect("blocked acceptance should reopen dispatch");

        assert!(
            !result.dispatches.is_empty(),
            "ready main-agent-published tasks should dispatch even if acceptance was blocked"
        );
        assert_eq!(result.action, "reopen_dispatch_for_ready_task");
        let loaded = crate::orchestration::load_active_run(&data_dir)
            .expect("run should load")
            .expect("run should exist");
        assert!(loaded.steps.iter().any(|step| {
            step.step_id == "goal_acceptance" && step.status == OrchestrationStepStatus::Running
        }));
        assert!(active_goal_task_claims(&loaded)
            .iter()
            .any(|claim| claim.entry_id.contains("closest-family_survey")));
    }

    #[test]
    fn full_auto_provider_worker_failure_releases_claim_without_repair_review() {
        let workspace_root = temp_git_workspace("goals_provider_worker_failure");
        let data_dir = workspace_root.join(".pmcli");
        let project_id = "project_goal_provider_worker_failure";
        let frame = autonomous_research_frame_with_mode(project_id, GoalAutomationMode::FullAuto);
        write_frame(&data_dir, &frame).expect("frame should write");
        let record = crate::research::record(
            &data_dir,
            project_id,
            crate::research::ResearchRecordRequest {
                kind: "goal".to_string(),
                title: "Seed provider worker failure task".to_string(),
                stage_id: "literature".to_string(),
                mode: "ready_to_execute".to_string(),
                decisions: Vec::new(),
                open_questions: Vec::new(),
                evidence_refs: Vec::new(),
            },
        )
        .expect("research record should create active stage");
        let mut run = goal_acceptance_ready_run(GoalAutomationMode::FullAuto);
        let task_id = publish_main_agent_stage_task_fixture(
            &data_dir,
            &mut run,
            &record.stage_execution,
            "closest-family survey",
        );
        let agent_id = "agent_goal_provider_failure";
        write_provider_failed_agent_fixture(
            &data_dir,
            &workspace_root,
            agent_id,
            "sjtu-glm",
            "glm-5.1",
            "provider returned HTTP 429: rate limit exceeded",
        );
        run.steps
            .iter_mut()
            .find(|step| step.step_id == "goal_dispatch")
            .expect("dispatch step should exist")
            .artifacts
            .push(goal_task_claim_ref(&task_id, agent_id));
        crate::orchestration::save_run(&data_dir, &run).expect("run should save");

        let result = advance(&data_dir, &workspace_root, project_id)
            .expect("advance should classify provider failure");

        let acceptance = result.acceptance.expect("acceptance should occur");
        assert_eq!(acceptance.status, "provider_failed");
        assert_eq!(acceptance.verdict, "provider_execution_failed");
        assert!(acceptance.provider_failure.is_some());
        assert_eq!(
            acceptance.claim_status.as_deref(),
            Some("closed_provider_execution_failed")
        );
        assert!(
            result.dispatch.is_none(),
            "provider failure acceptance should not dispatch another worker in the same advance; the autonomous research provider policy must record backoff/failover first"
        );
        let loaded = crate::orchestration::load_active_run(&data_dir)
            .expect("run should load")
            .expect("run should exist");
        assert!(loaded
            .steps
            .iter()
            .any(|step| step.step_id == "goal_acceptance"
                && step
                    .artifacts
                    .iter()
                    .any(|artifact| artifact.contains("goal_provider_failure::agent"))));
        assert!(!loaded
            .steps
            .iter()
            .any(|step| step.artifacts.iter().any(|artifact| {
                artifact.contains("goal_repair_review::agent:") && artifact.contains(agent_id)
            })));
        assert_eq!(loaded.status, "running");
        assert!(goal_task_claim_is_closed(&loaded, &task_id, agent_id));
        assert!(!active_goal_task_claims(&loaded)
            .iter()
            .any(|claim| claim.agent_id == agent_id));
        let status = status(&data_dir, &workspace_root, project_id).expect("status should build");
        assert!(
            status
                .task_pool
                .entries
                .iter()
                .all(|entry| entry.entry_id != format!("agent_task::{agent_id}")),
            "provider-failed workers already recorded by goal_provider_failure must not remain blocked task-pool items"
        );
    }

