    #[test]
    fn full_auto_accepts_valid_claim_before_earlier_failed_claim() {
        let workspace_root = temp_git_workspace("goals_accept_valid_before_failed_claim");
        let data_dir = workspace_root.join(".pmcli");
        let project_id = "project_goal_accept_valid_before_failed_claim";
        let frame = mission_frame_with_mode(project_id, GoalAutomationMode::FullAuto);
        write_frame(&data_dir, &frame).expect("frame should write");
        let failed_agent = crate::agents::start_local(
            &data_dir,
            &workspace_root,
            crate::agents::LocalAgentStartRequest {
                intent: "goal task dispatch: failed candidate".to_string(),
                role_profile: "goal_dispatcher".to_string(),
                message: "produce a failed output manifest".to_string(),
                command: "printf failed >&2; exit 2".to_string(),
                stage_task_contract: None,
            },
        )
        .expect("failed local agent record should write");
        let valid_agent = crate::agents::start_local(
            &data_dir,
            &workspace_root,
            crate::agents::LocalAgentStartRequest {
                intent: "goal task dispatch: valid candidate".to_string(),
                role_profile: "goal_dispatcher".to_string(),
                message: "produce a valid output manifest".to_string(),
                command: "mkdir -p .pmcli/goal-worker-output && printf ok > .pmcli/goal-worker-output/ok.txt".to_string(),
                stage_task_contract: None,
            },
        )
        .expect("valid local agent should run");
        let failed_entry_id = "board::failed_candidate";
        let valid_entry_id = "board::valid_candidate";
        let mut run = goal_acceptance_ready_run(GoalAutomationMode::FullAuto);
        let dispatch_step = run
            .steps
            .iter_mut()
            .find(|step| step.step_id == "goal_dispatch")
            .expect("dispatch step should exist");
        dispatch_step
            .artifacts
            .push(goal_task_claim_ref(failed_entry_id, &failed_agent.agent_id));
        dispatch_step
            .artifacts
            .push(goal_task_claim_ref(valid_entry_id, &valid_agent.agent_id));
        crate::orchestration::save_run(&data_dir, &run).expect("run should save");

        let result = advance(&data_dir, &workspace_root, project_id).expect("advance should work");
        let acceptance = result
            .acceptance
            .expect("valid claim should be accepted before failed claim is reviewed");

        assert_eq!(acceptance.status, "accepted");
        assert_eq!(acceptance.agent_id, valid_agent.agent_id);
        assert_eq!(
            acceptance.task_pool_entry_id.as_deref(),
            Some(valid_entry_id)
        );
        let loaded = crate::orchestration::load_active_run(&data_dir)
            .expect("run should load")
            .expect("run should exist");
        let active_claims = active_goal_task_claims(&loaded);
        assert!(
            active_claims
                .iter()
                .any(|claim| claim.agent_id == failed_agent.agent_id),
            "failed claim should remain for a later repair review"
        );
        assert!(
            !active_claims
                .iter()
                .any(|claim| claim.agent_id == valid_agent.agent_id),
            "accepted valid claim should be closed"
        );
        let acceptance_step = loaded
            .steps
            .iter()
            .find(|step| step.step_id == "goal_acceptance")
            .expect("acceptance step should exist");
        assert_eq!(acceptance_step.status, OrchestrationStepStatus::Running);
        assert!(acceptance_step.artifacts.iter().any(|artifact| {
            artifact
                == &goal_task_claim_closed_ref(valid_entry_id, &valid_agent.agent_id, "accepted")
        }));
        assert!(!acceptance_step.artifacts.iter().any(|artifact| {
            artifact.starts_with(&format!(
                "goal_repair_review::agent:{}",
                failed_agent.agent_id
            ))
        }));
    }

    #[test]
    fn failed_repair_review_keeps_acceptance_running_when_claims_remain() {
        let mut run = goal_acceptance_ready_run(GoalAutomationMode::FullAuto);
        let failed_entry_id = "board::failed_candidate";
        let remaining_entry_id = "board::remaining_candidate";
        let failed_agent_id = "agent_failed_candidate";
        let remaining_agent_id = "agent_remaining_candidate";
        let dispatch_step = run
            .steps
            .iter_mut()
            .find(|step| step.step_id == "goal_dispatch")
            .expect("dispatch step should exist");
        dispatch_step
            .artifacts
            .push(goal_task_claim_ref(failed_entry_id, failed_agent_id));
        dispatch_step
            .artifacts
            .push(goal_task_claim_ref(remaining_entry_id, remaining_agent_id));
        let repair = GoalRepairReviewRef {
            agent_id: failed_agent_id.to_string(),
            review_id: "rev_failed_candidate".to_string(),
        };

        record_goal_repair_review_failed(&mut run, &repair, "blocked", false);

        let acceptance_step = run
            .steps
            .iter()
            .find(|step| step.step_id == "goal_acceptance")
            .expect("acceptance step should exist");
        assert_eq!(acceptance_step.status, OrchestrationStepStatus::Running);
        assert!(goal_task_claim_is_closed(
            &run,
            failed_entry_id,
            failed_agent_id
        ));
        assert!(
            active_goal_task_claims(&run)
                .iter()
                .any(|claim| claim.agent_id == remaining_agent_id),
            "remaining claim must stay active for acceptance"
        );
        assert!(acceptance_step
            .continuation_points
            .iter()
            .any(|point| point.contains("continue accepting remaining active claims")));
    }

