    #[test]
    fn goal_review_parser_accepts_streamed_final_verdict_block() {
        let review_text = "I am checking the files now.verdict: pass\nscore: 84\nfailure class: none\nsuggested operation: accept\ncleanup requirement: required\n";

        let (verdict, score) = parse_goal_review_verdict(review_text);

        assert_eq!(verdict, "pass");
        assert_eq!(score, Some(84));
        assert_eq!(
            extract_goal_review_labeled_value(review_text, "suggested operation").as_deref(),
            Some("accept")
        );
        assert!(goal_review_cleanup_required(review_text));
    }

    #[test]
    fn goal_review_parser_ignores_inline_score_phrases() {
        let review_text = "verdict: pass\nscore: 92\n\n- Minor weakness prevents a perfect score: several rows rely on inherited audits, and Q02-Q04 remain opaque.\n";

        let (verdict, score) = parse_goal_review_verdict(review_text);

        assert_eq!(verdict, "pass");
        assert_eq!(score, Some(92));
        assert_eq!(
            extract_goal_review_labeled_value(review_text, "score").as_deref(),
            Some("92")
        );
        assert_eq!(
            parse_goal_review_score(
                "several rows rely on inherited audits, and Q02-Q04 remain opaque"
            ),
            None
        );
    }

    #[test]
    fn full_auto_blocks_stage_task_when_semantic_review_fails() {
        let workspace_root = temp_git_workspace("goals_stage_task_semantic_review_rejected");
        let data_dir = workspace_root.join(".pmcli");
        let project_id = "project_goal_stage_task_semantic_review_rejected";
        let frame = autonomous_research_frame_with_mode(project_id, GoalAutomationMode::FullAuto);
        write_frame(&data_dir, &frame).expect("frame should write");
        crate::research::record(
            &data_dir,
            project_id,
            crate::research::ResearchRecordRequest {
                kind: "goal".to_string(),
                title: "Reject semantically invalid stage worker output".to_string(),
                stage_id: "monitor".to_string(),
                mode: "ready_to_execute".to_string(),
                decisions: Vec::new(),
                open_questions: Vec::new(),
                evidence_refs: Vec::new(),
            },
        )
        .expect("research record should create active stage");
        let stage_execution_id = crate::research::status(&data_dir, project_id)
            .expect("research status")
            .active_stage_execution
            .expect("active stage")
            .execution_id;
        let agent = crate::agents::start_local(
            &data_dir,
            &workspace_root,
            crate::agents::LocalAgentStartRequest {
                intent: "goal task dispatch: semantically invalid monitor metric extraction"
                    .to_string(),
                role_profile: "result_analyst".to_string(),
                message: "monitor output with all structure but an unresolved semantic blocker"
                    .to_string(),
                command: "mkdir -p .pmcli/goal-worker-output/actions && cat > .pmcli/goal-worker-output/actions/semantic_monitor.md <<'EOF'\nexperiment_report\nmetric extraction\nmetric table\nraw result refs: research/semantic_monitor.md\nparsing script or command: cat research/semantic_monitor.md\nanomaly list: unresolved blocking defect in metric interpretation\nmissing run list: none\nbaseline comparison: observed metric row compared to baseline\nstatistical or repeated-run notes: one repeated-run note recorded\nrecommended reruns or repairs: repair metric interpretation\nmetrics parsed from raw refs\nanomalies and missing runs explained\naction_schema_version: astra.goal_worker_action.v1\n.pmcli/goal-worker-output/actions\nraw result refs\nresearch/semantic_monitor.md\nEOF\ncat .pmcli/goal-worker-output/actions/semantic_monitor.md".to_string(),
                stage_task_contract: None,
            },
        )
        .expect("local agent should run");
        let entry_id = stage_task_id(&stage_execution_id, "metric extraction");
        let mut run = goal_acceptance_ready_run(GoalAutomationMode::FullAuto);
        run.steps
            .iter_mut()
            .find(|step| step.step_id == "goal_dispatch")
            .expect("dispatch step should exist")
            .artifacts
            .push(goal_task_claim_ref(&entry_id, &agent.agent_id));
        crate::orchestration::save_run(&data_dir, &run).expect("run should save");

        let result = advance(&data_dir, &workspace_root, project_id).expect("advance should work");
        let acceptance = result
            .acceptance
            .expect("stage task semantic review rejection should occur");
        let stage_task_acceptance = acceptance
            .stage_task_acceptance
            .expect("stage task acceptance details should be present");
        let semantic_review = stage_task_acceptance
            .semantic_review
            .as_ref()
            .expect("semantic review should be recorded");

        assert_eq!(acceptance.status, "blocked");
        assert_eq!(acceptance.verdict, "local_acceptance_preflight_failed");
        assert_eq!(stage_task_acceptance.verdict, "accepted");
        assert!(stage_task_acceptance.missing_required_fields.is_empty());
        assert!(stage_task_acceptance.missing_acceptance_checks.is_empty());
        assert!(stage_task_acceptance.missing_quality_signals.is_empty());
        assert_eq!(semantic_review.verdict, "fail");
        assert_eq!(
            semantic_review.failure_class.as_deref(),
            Some("stage_task_semantic_failure")
        );
        assert!(acceptance.review_packet_refs.is_empty());
        assert!(acceptance
            .diagnostic_refs
            .iter()
            .any(|diagnostic_ref| diagnostic_ref == &semantic_review.review_packet_ref));
        let loaded = crate::orchestration::load_active_run(&data_dir)
            .expect("run should load")
            .expect("run should exist");
        assert!(
            goal_task_claim_is_blocked(&loaded, &entry_id, &agent.agent_id),
            "failed semantic preflight must block the claim so the main agent can route repair work"
        );
        let acceptance_step = loaded
            .steps
            .iter()
            .find(|step| step.step_id == "goal_acceptance")
            .expect("goal acceptance step should exist");
        assert_eq!(
            acceptance_step.status,
            OrchestrationStepStatus::Blocked,
            "Astra protocol should block for main-agent repair routing instead of runtime dispatch"
        );
        assert!(acceptance_step.artifacts.iter().any(|artifact| {
            artifact == &format!("goal_acceptance_diagnostic::agent:{}", agent.agent_id)
        }));
        assert!(acceptance_step.artifacts.iter().any(|artifact| {
            artifact.contains("goal_task_claim_blocked::") && artifact.contains(&agent.agent_id)
        }));
        assert!(acceptance_step
            .continuation_points
            .iter()
            .any(|point| point.contains("local acceptance preflight")));
        let status = status(&data_dir, &workspace_root, project_id).expect("goal status");
        assert!(status
            .task_pool
            .entries
            .iter()
            .any(|entry| entry.source.source_kind == "goal_task_claim"));
        assert!(status.task_pool.entries.iter().any(|entry| {
            entry.source.source_kind == "orchestration_step"
                && entry.entry_id.contains("goal_acceptance")
                && entry.bucket_id == "blocked"
        }));
    }

    #[test]
    fn full_auto_blocks_runtime_scaffold_as_completed_literature_research() {
        let workspace_root = temp_git_workspace("goals_stage_task_structured_acceptance");
        let data_dir = workspace_root.join(".pmcli");
        let project_id = "project_goal_stage_task_structured";
        let frame = autonomous_research_frame_with_mode(project_id, GoalAutomationMode::FullAuto);
        write_frame(&data_dir, &frame).expect("frame should write");
        let record = crate::research::record(
            &data_dir,
            project_id,
            crate::research::ResearchRecordRequest {
                kind: "goal".to_string(),
                title: "Accept structured stage worker output".to_string(),
                stage_id: "literature".to_string(),
                mode: "ready_to_execute".to_string(),
                decisions: Vec::new(),
                open_questions: Vec::new(),
                evidence_refs: Vec::new(),
            },
        )
        .expect("research record should create active stage");
        let stage = record.stage_execution;
        let stage_execution_id = stage.execution_id.clone();
        let mut run = goal_dispatch_ready_run(GoalAutomationMode::FullAuto);
        run.steps
            .iter_mut()
            .find(|step| step.step_id == "goal_acceptance")
            .expect("acceptance step should exist")
            .artifacts
            .push(goal_task_claim_closed_ref(
                &stage_task_id(&stage_execution_id, "acceptance standard setting"),
                "agent_rubric_already_tested",
                "test_skip",
            ));
        publish_main_agent_stage_task_fixture(&data_dir, &mut run, &stage, "paper search");
        crate::orchestration::save_run(&data_dir, &run).expect("run should save");

        let dispatch_result =
            advance(&data_dir, &workspace_root, project_id).expect("advance should dispatch");
        assert!(!dispatch_result.dispatches.is_empty());
        assert!(
            dispatch_result.acceptance.is_none(),
            "fresh dispatches are accepted on the next advance so worker state is durably visible first"
        );
        let mut result =
            advance(&data_dir, &workspace_root, project_id).expect("advance should review");
        for _ in 0..3 {
            if result
                .acceptance
                .as_ref()
                .and_then(|acceptance| acceptance.stage_task_acceptance.as_ref())
                .is_some()
            {
                break;
            }
            result =
                advance(&data_dir, &workspace_root, project_id).expect("advance should review");
        }
        let acceptance = result
            .acceptance
            .expect("runtime scaffold should be reviewed and blocked");
        let stage_task_acceptance = acceptance
            .stage_task_acceptance
            .expect("stage task acceptance details should be present");

        assert_eq!(acceptance.status, "blocked");
        assert_eq!(acceptance.verdict, "local_acceptance_preflight_failed");
        assert_eq!(stage_task_acceptance.verdict, "accepted");
        assert!(stage_task_acceptance.required_output_artifact_type_matched);
        assert!(stage_task_acceptance.missing_required_fields.is_empty());
        assert!(stage_task_acceptance.missing_acceptance_checks.is_empty());
        assert!(stage_task_acceptance.missing_evidence_refs.is_empty());
        assert!(stage_task_acceptance.missing_quality_signals.is_empty());
        assert!(!stage_task_acceptance.matched_required_fields.is_empty());
        assert!(!stage_task_acceptance.matched_acceptance_checks.is_empty());
        assert!(!stage_task_acceptance.matched_quality_signals.is_empty());
        assert!(matches!(
            stage_task_acceptance.quality_profile.level.as_str(),
            "strong" | "partial"
        ));
        assert!(
            stage_task_acceptance.quality_profile.score >= 70,
            "accepted stage task should carry non-weak quality evidence"
        );
        let semantic_review = stage_task_acceptance
            .semantic_review
            .as_ref()
            .expect("blocked stage task should carry semantic review");
        assert_eq!(semantic_review.verdict, "fail");
        assert_eq!(
            semantic_review.failure_class.as_deref(),
            Some("stage_task_semantic_failure")
        );
        assert!(semantic_review.findings.iter().any(|finding| {
            finding.contains(
                "literature worker research has not produced reviewable source-grounded evidence",
            ) && finding.contains("agent-team completion marker")
                && finding.contains("agent-team source matrix or source entries")
                && finding.contains("concrete source refs")
                && finding.contains("closest-family coverage")
        }));
        assert_eq!(semantic_review.execution_mode, "local_acceptance_preflight");
        assert!(acceptance.review_packet_refs.is_empty());
        assert!(acceptance
            .diagnostic_refs
            .iter()
            .any(|diagnostic_ref| diagnostic_ref == &semantic_review.review_packet_ref));
        let loaded = crate::orchestration::load_active_run(&data_dir)
            .expect("run should load")
            .expect("run should exist");
        let claim = acceptance
            .task_pool_entry_id
            .as_deref()
            .zip(Some(acceptance.agent_id.as_str()))
            .expect("blocked preflight should preserve claim identity");
        assert!(
            goal_task_claim_is_blocked(&loaded, claim.0, claim.1),
            "local preflight failure must block the claim for main-agent repair routing"
        );
    }

    #[test]
    fn full_auto_stage_worker_probe_scans_real_project_artifacts() {
        let workspace_root = temp_git_workspace("goals_stage_worker_real_probe");
        fs::create_dir_all(workspace_root.join("papers")).expect("papers dir should create");
        fs::write(
            workspace_root.join("papers").join("refs.bib"),
            "@article{fixture2026,title={Fixture Paper}}\n",
        )
        .expect("bib fixture should write");
        let add = Command::new("git")
            .current_dir(&workspace_root)
            .args(["add", "papers/refs.bib"])
            .status()
            .expect("git add fixture should run");
        assert!(add.success());
        let commit = Command::new("git")
            .current_dir(&workspace_root)
            .args(["commit", "-q", "-m", "add literature fixture"])
            .status()
            .expect("git commit fixture should run");
        assert!(commit.success());

        let data_dir = workspace_root.join(".pmcli");
        let project_id = "project_goal_stage_worker_real_probe";
        let frame = autonomous_research_frame_with_mode(project_id, GoalAutomationMode::FullAuto);
        write_frame(&data_dir, &frame).expect("frame should write");
        let record = crate::research::record(
            &data_dir,
            project_id,
            crate::research::ResearchRecordRequest {
                kind: "goal".to_string(),
                title: "Scan real project literature artifacts".to_string(),
                stage_id: "literature".to_string(),
                mode: "ready_to_execute".to_string(),
                decisions: Vec::new(),
                open_questions: Vec::new(),
                evidence_refs: Vec::new(),
            },
        )
        .expect("research record should create active stage");
        let stage = record.stage_execution;
        let stage_execution_id = stage.execution_id.clone();
        let mut run = goal_dispatch_ready_run(GoalAutomationMode::FullAuto);
        run.steps
            .iter_mut()
            .find(|step| step.step_id == "goal_acceptance")
            .expect("acceptance step should exist")
            .artifacts
            .push(goal_task_claim_closed_ref(
                &stage_task_id(&stage_execution_id, "acceptance standard setting"),
                "agent_rubric_already_tested",
                "test_skip",
            ));
        publish_main_agent_stage_task_fixture(&data_dir, &mut run, &stage, "paper search");
        crate::orchestration::save_run(&data_dir, &run).expect("run should save");

        let result = advance(&data_dir, &workspace_root, project_id).expect("advance should work");
        let dispatch = result.dispatch.expect("dispatch should occur");
        assert_eq!(
            dispatch
                .source_entry
                .stage_task
                .as_ref()
                .expect("dispatch should carry stage task metadata")
                .task_type,
            "paper search"
        );
        let inspection =
            crate::agents::inspect(&data_dir, &dispatch.agent_id).expect("agent should inspect");
        let contract = inspection
            .task_packet
            .stage_task_contract
            .as_ref()
            .expect("worker task packet should carry main-agent stage task contract");
        assert_eq!(contract.task_id, dispatch.task_pool_entry_id);
        assert_eq!(contract.stage_execution_id, stage_execution_id);
        assert_eq!(contract.stage_id, "literature");
        assert_eq!(contract.task_type, "paper search");
        assert_eq!(
            contract.worker_role,
            dispatch
                .source_entry
                .stage_task
                .as_ref()
                .expect("dispatch should retain stage task metadata")
                .worker_role
        );
        assert!(!contract.required_output_fields.is_empty());
        assert!(!contract.acceptance_checks.is_empty());
        assert!(!contract.failure_signals.is_empty());
        let output_text = stage_worker_output_text(&inspection);

        assert!(output_text.contains("probe_schema_version"));
        assert!(output_text.contains("literature_probe_status"));
        assert!(!output_text.contains("retrieval-grounded autonomous literature synthesis"));
        assert!(!output_text.contains("stage acceptance rubric manifest"));
        assert!(!output_text.contains("rubric_contract_only_no_source_acceptance"));
        assert!(output_text.contains("literature matrix: `.pmcli/goal-worker-output/actions/"));
        assert!(output_text
            .contains("literature retrieval manifest: `.pmcli/goal-worker-output/actions/"));
        assert!(output_text
            .contains("literature research obligations: `.pmcli/goal-worker-output/actions/"));
        assert!(output_text.contains("literature matrix rows:"));
        assert!(output_text.contains("closest-family coverage matrix:"));
        assert!(output_text.contains("closest-family comparisons:"));
        assert!(output_text.contains("reviewer-ready literature matrix:"));
        assert!(output_text.contains("reviewer-ready closest-family comparison:"));
        assert!(output_text.contains("research ownership boundary"));
        assert!(output_text.contains("literature worker research required: `true`"));
        assert!(
            output_text.contains("method family: `literature-worker defined families required`"),
            "runtime must not generate topic families:\n{output_text}"
        );
        assert!(
            output_text.contains("runtime scaffold only; no source-grounded rows accepted"),
            "runtime scaffold must not pretend source-grounded literature rows exist"
        );
        assert!(
            output_text.contains("papers/refs.bib"),
            "real worker probe should cite the committed local bib file:\n{output_text}"
        );
        assert!(
            output_text.contains("missing-source risks"),
            "worker probe should preserve explicit missing-source risk field"
        );
        assert!(!output_text.contains("export.arxiv.org/api/query"));
        assert!(!output_text.contains("curl -fsSL"));
        assert!(!output_text.contains("all:large+AND"));
        assert!(!output_text.contains("LLM benchmark and evaluation suites"));
        assert!(!output_text.contains("adversarial prompting and prompt-injection robustness"));
    }

