    #[test]
    fn artifact_repair_dispatch_contract_includes_stage_required_fields() {
        let stage_task = GoalStageTaskMetadata {
            task_id: "research_stage_task::stage_novelty::novelty_repair_v1".to_string(),
            stage_execution_id: "stage_novelty".to_string(),
            stage_id: "novelty".to_string(),
            task_type: "artifact_repair".to_string(),
            worker_role: "research_synthesizer".to_string(),
            objective: "Repair the canonical novelty report after failed review.".to_string(),
            input_artifact_refs: Vec::new(),
            required_canonical_artifacts: Vec::new(),
            required_output_artifact_type: "novelty_report".to_string(),
            required_output_fields: vec![
                "closest_prior_table".to_string(),
                "explicit_bottom_line_state".to_string(),
            ],
            acceptance_checks: vec!["address failed review".to_string()],
            failure_signals: Vec::new(),
            depends_on_task_ids: Vec::new(),
            priority: 100,
            status: "ready".to_string(),
            claimed_by_agent_id: None,
            output_artifact_refs: Vec::new(),
            review_findings_refs: Vec::new(),
            blocker_refs: Vec::new(),
            review_target_task_ids: Vec::new(),
            review_target_evidence_refs: Vec::new(),
            supersedes_task_ids: Vec::new(),
            replacement_of_task_ids: Vec::new(),
            current_evidence_set_id: None,
            consumed_input_required: true,
        };

        let contract = agent_stage_task_contract_from_goal_stage_task(&stage_task);
        let rendered = render_stage_task_dispatch_contract(&stage_task);

        for field in [
            "closest prior table",
            "overlap analysis",
            "novelty risks",
            "what appears new",
            "what is explicitly not new",
            "rejected novelty angles",
            "reviewer attack points",
        ] {
            assert!(
                contract
                    .required_output_fields
                    .iter()
                    .any(|item| normalize_match_text(item).contains(&normalize_match_text(field))),
                "dispatch packet should include canonical stage field `{field}`"
            );
            assert!(
                rendered.contains(field),
                "worker-facing dispatch text should include canonical stage field `{field}`"
            );
        }
        assert!(
            contract
                .required_output_fields
                .iter()
                .any(|item| item == "explicit_bottom_line_state"),
            "main-agent task-specific fields must be preserved"
        );
    }

