    fn accepted_run_does_not_reopen_for_policy_only_dispatch_hint() {
        let run = {
            let mut run = goal_dispatch_ready_run(GoalAutomationMode::FullAuto);
            run.status = "accepted".to_string();
            for step in &mut run.steps {
                step.status = OrchestrationStepStatus::Done;
            }
            run
        };
        let policy_entry = GoalTaskPoolEntry::new(
            "automation_policy::full_auto::dispatch_agent_task",
            "ready_to_run",
            "dispatch_agent_task",
            "policy-visible only",
            GoalTaskPoolEntrySource::new("goal_run_automation_policy", "policy"),
        )
        .with_status("allowed")
        .with_action_policy("allowed");
        let task_pool = GoalTaskPoolSnapshot {
            schema_version: "goal_task_pool_snapshot.v1".to_string(),
            authority_model: "test".to_string(),
            source: "test".to_string(),
            project_id: "project_policy_only".to_string(),
            automation_mode: GoalAutomationMode::FullAuto,
            target_run: Some(GoalTargetRunSnapshot {
                run_id: "run_policy_only".to_string(),
                objective: "Finished run".to_string(),
                status: "accepted".to_string(),
                progress_percent: 100,
                done_steps: 4,
                total_steps: 4,
                blocked_steps: 0,
                current_step_id: None,
                current_step_title: None,
            }),
            summary: GoalTaskPoolSummary {
                total: 1,
                ready_to_run: 1,
                ..GoalTaskPoolSummary::default()
            },
            entries: vec![policy_entry],
            next_recommended_action: "dispatch_next_allowed_goal_task".to_string(),
        };

        assert!(!goal_run_needs_dispatch_reopen(&run, &task_pool));
        let closure = loop_closure_projection(&task_pool, None, 0, false);
        assert_eq!(closure.status, "completed");
        assert_eq!(closure.task_pool_summary.total, 0);
    }

    #[test]
    fn idle_acceptance_running_reblocks_on_blocked_task_pool_without_active_claims() {
        let mut run = goal_dispatch_ready_run(GoalAutomationMode::FullAuto);
        run.status = "running".to_string();
        for step in &mut run.steps {
            step.status = match step.step_id.as_str() {
                "goal_scope" | "goal_task_pool" | "goal_dispatch" => OrchestrationStepStatus::Done,
                "goal_acceptance" => OrchestrationStepStatus::Running,
                _ => step.status.clone(),
            };
        }
        let blocked_entry = GoalTaskPoolEntry::new(
            "board::stage_1::stale_dependency",
            "blocked",
            "stale dependency",
            "main-agent-published task has stale dependency",
            GoalTaskPoolEntrySource::new("main_agent_published_task", "task"),
        )
        .with_status("contract_invalid")
        .with_action_policy("requires_main_agent_update");
        let task_pool = GoalTaskPoolSnapshot {
            schema_version: "goal_task_pool_snapshot.v1".to_string(),
            authority_model: "test".to_string(),
            source: "test".to_string(),
            project_id: "project_idle_acceptance".to_string(),
            automation_mode: GoalAutomationMode::FullAuto,
            target_run: None,
            summary: GoalTaskPoolSummary {
                total: 1,
                blocked: 1,
                ..GoalTaskPoolSummary::default()
            },
            entries: vec![blocked_entry],
            next_recommended_action: "resolve_blocked_goal_task".to_string(),
        };

        assert!(mark_idle_acceptance_blocked_by_task_pool(
            &mut run, &task_pool
        ));
        let acceptance = run
            .steps
            .iter()
            .find(|step| step.step_id == "goal_acceptance")
            .expect("goal_acceptance step should exist");
        assert_eq!(run.status, "blocked");
        assert_eq!(acceptance.status, OrchestrationStepStatus::Blocked);
        assert!(acceptance.continuation_points.iter().any(|point| {
            point.contains("no active worker claim") && point.contains("blocked task-pool")
        }));
    }

    #[test]
    fn full_auto_implementation_worker_runs_bounded_local_test_action() {
        let workspace_root = temp_git_workspace("goals_stage_worker_test_action");
        fs::write(
            workspace_root.join("Cargo.toml"),
            "[package]\nname = \"fixture\"\nversion = \"0.1.0\"\nedition = \"2021\"\n\n[lib]\npath = \"src/lib.rs\"\n",
        )
        .expect("Cargo.toml should write");
        fs::create_dir_all(workspace_root.join("src")).expect("src dir should create");
        fs::write(
            workspace_root.join("src").join("lib.rs"),
            "pub fn add(left: i32, right: i32) -> i32 { left + right }\n\n#[cfg(test)]\nmod tests {\n    use super::*;\n    #[test]\n    fn add_works() { assert_eq!(add(1, 2), 3); }\n}\n",
        )
        .expect("lib fixture should write");
        let add = Command::new("git")
            .current_dir(&workspace_root)
            .args(["add", "Cargo.toml", "src/lib.rs"])
            .status()
            .expect("git add fixture should run");
        assert!(add.success());
        let commit = Command::new("git")
            .current_dir(&workspace_root)
            .args(["commit", "-q", "-m", "add cargo fixture"])
            .status()
            .expect("git commit fixture should run");
        assert!(commit.success());

        let data_dir = workspace_root.join(".pmcli");
        let project_id = "project_goal_stage_worker_test_action";
        let frame = autonomous_research_frame_with_mode(project_id, GoalAutomationMode::FullAuto);
        write_frame(&data_dir, &frame).expect("frame should write");
        let record = crate::research::record(
            &data_dir,
            project_id,
            crate::research::ResearchRecordRequest {
                kind: "goal".to_string(),
                title: "Run bounded implementation test action".to_string(),
                stage_id: "implement-solution".to_string(),
                mode: "ready_to_execute".to_string(),
                decisions: Vec::new(),
                open_questions: Vec::new(),
                evidence_refs: Vec::new(),
            },
        )
        .expect("research record should create active stage");
        let stage = record.stage_execution;
        let stage_execution_id = stage.execution_id.clone();
        let mut run = goal_dispatch_ready_run(GoalAutomationMode::FullAuto);
        run.steps
            .iter_mut()
            .find(|step| step.step_id == "goal_acceptance")
            .expect("acceptance step should exist")
            .artifacts
            .push(goal_task_claim_closed_ref(
                &stage_task_id(&stage_execution_id, "acceptance standard setting"),
                "agent_rubric_already_tested",
                "test_skip",
            ));
        publish_main_agent_stage_task_fixture(&data_dir, &mut run, &stage, "method implementation");
        crate::orchestration::save_run(&data_dir, &run).expect("run should save");

        let result = advance(&data_dir, &workspace_root, project_id).expect("advance should work");
        let dispatch = result.dispatch.expect("dispatch should occur");
        assert_eq!(
            dispatch
                .source_entry
                .stage_task
                .as_ref()
                .expect("dispatch should carry stage task metadata")
                .task_type,
            "method implementation"
        );
        let inspection =
            crate::agents::inspect(&data_dir, &dispatch.agent_id).expect("agent should inspect");
        let output_text = stage_worker_output_text(&inspection);

        assert!(output_text.contains("action_schema_version"));
        assert!(output_text.contains("tests and smoke commands: `cargo test --quiet`"));
        assert!(output_text.contains("bounded_test_exit_code: `0`"));
        assert!(output_text.contains("status or typed failure: `passed`"));
    }

