    #[test]
    fn full_auto_accepted_goal_output_consumes_low_risk_stage_decision() {
        let workspace_root = temp_git_workspace("goals_stage_decision_needed");
        let data_dir = workspace_root.join(".pmcli");
        let project_id = "project_goal_stage_decision";
        let frame = mission_frame_with_mode(project_id, GoalAutomationMode::FullAuto);
        write_frame(&data_dir, &frame).expect("frame should write");
        crate::research::record(
            &data_dir,
            project_id,
            crate::research::ResearchRecordRequest {
                kind: "goal".to_string(),
                title: "Advance accepted goal work into research stage".to_string(),
                stage_id: "implement-solution".to_string(),
                mode: "ready_to_execute".to_string(),
                decisions: vec![],
                open_questions: vec![],
                evidence_refs: vec!["docs/spec.md".to_string()],
            },
        )
        .expect("research record should create active stage");
        let stage_id = crate::research::status(&data_dir, project_id)
            .expect("research status")
            .active_stage_execution
            .expect("active stage")
            .execution_id;
        let agent = crate::agents::start_local(
            &data_dir,
            &workspace_root,
            crate::agents::LocalAgentStartRequest {
                intent: "goal task dispatch: dispatch_agent_task".to_string(),
                role_profile: "goal_dispatcher".to_string(),
                message: "produce a valid output manifest".to_string(),
                command: "mkdir -p .pmcli/goal-worker-output && printf ok > .pmcli/goal-worker-output/ok.txt".to_string(),
                stage_task_contract: None,
            },
        )
        .expect("local agent should run");
        let entry_id = "automation_policy::full_auto::dispatch_agent_task";
        let mut run = goal_acceptance_ready_run(GoalAutomationMode::FullAuto);
        run.steps
            .iter_mut()
            .find(|step| step.step_id == "goal_dispatch")
            .expect("dispatch step should exist")
            .artifacts
            .push(goal_task_claim_ref(entry_id, &agent.agent_id));
        crate::orchestration::save_run(&data_dir, &run).expect("run should save");

        let result = advance(&data_dir, &workspace_root, project_id).expect("advance should work");
        let acceptance = result.acceptance.expect("acceptance should occur");
        let stage_decision = result
            .stage_decision
            .expect("stage decision should auto-advance");

        assert_eq!(
            acceptance.research_stage_execution_ref.as_deref(),
            Some(stage_id.as_str())
        );
        assert_eq!(stage_decision.stage_execution_id, stage_id);
        assert_eq!(stage_decision.agent_id, agent.agent_id);
        assert_eq!(stage_decision.status, "auto_approved_low_risk_advance");
        let loaded = crate::orchestration::load_active_run(&data_dir)
            .expect("run should load")
            .expect("run should exist");
        let acceptance_step = loaded
            .steps
            .iter()
            .find(|step| step.step_id == "goal_acceptance")
            .expect("acceptance step should exist");
        assert!(acceptance_step.artifacts.iter().any(|artifact| {
            artifact == &goal_research_stage_decision_needed_ref(&stage_id, &agent.agent_id)
        }));
        assert!(acceptance_step
            .artifacts
            .iter()
            .any(|artifact| { artifact.starts_with("goal_research_stage_decision_consumed::") }));
        let status = status(&data_dir, &workspace_root, project_id).expect("goal status");
        assert!(!status
            .task_pool
            .entries
            .iter()
            .any(|entry| entry.source.source_kind == "goal_research_stage_decision"));
        let research_status =
            crate::research::status(&data_dir, project_id).expect("research status");
        let active_stage = research_status
            .active_stage_execution
            .expect("active stage should advance");
        assert_eq!(active_stage.operation, "advance");
        assert_ne!(active_stage.execution_id, stage_id);
    }

