    #[test]
    fn advance_full_auto_failed_agent_output_records_acceptance_diagnostic_once() {
        let workspace_root = temp_git_workspace("goals_full_auto_acceptance_diagnostic");
        let data_dir = workspace_root.join(".pmcli");
        let project_id = "project_goal_acceptance_diagnostic";
        let frame = mission_frame_with_mode(project_id, GoalAutomationMode::FullAuto);
        write_frame(&data_dir, &frame).expect("frame should write");
        let agent = crate::agents::start_local(
            &data_dir,
            &workspace_root,
            crate::agents::LocalAgentStartRequest {
                intent: "goal task dispatch: failing task".to_string(),
                role_profile: "goal_worker".to_string(),
                message: "produce a failed output manifest".to_string(),
                command: "printf failure >&2; exit 7".to_string(),
                stage_task_contract: None,
            },
        )
        .expect("local agent should run");
        assert_eq!(agent.runtime_record.lifecycle_status, "failed");
        let entry_id = "automation_policy::full_auto::dispatch_agent_task";
        let mut run = goal_acceptance_ready_run(GoalAutomationMode::FullAuto);
        run.steps
            .iter_mut()
            .find(|step| step.step_id == "goal_dispatch")
            .expect("dispatch step should exist")
            .artifacts
            .push(goal_task_claim_ref(entry_id, &agent.agent_id));
        crate::orchestration::save_run(&data_dir, &run).expect("run should save");

        let result = advance(&data_dir, &workspace_root, project_id).expect("advance should work");
        let acceptance = result.acceptance.expect("diagnostic should record");

        assert_eq!(acceptance.status, "blocked");
        assert_eq!(acceptance.verdict, "worker_output_repair_required");
        assert_eq!(acceptance.agent_id, agent.agent_id);
        assert_eq!(acceptance.task_pool_entry_id.as_deref(), Some(entry_id));
        assert_eq!(
            acceptance.claim_ref.as_deref(),
            Some(goal_task_claim_ref(entry_id, &agent.agent_id).as_str())
        );
        assert_eq!(
            acceptance.claim_status.as_deref(),
            Some("blocked_worker_output_repair_required")
        );
        assert!(acceptance.review_packet_refs.is_empty());
        assert_eq!(acceptance.diagnostic_refs.len(), 1);
        assert!(acceptance.diagnostic_refs[0].contains("acceptance-diagnostics"));
        let reviews = crate::reviews::list(&data_dir, None, None).expect("reviews should list");
        assert_eq!(reviews.total_count, 0);
        let loaded = crate::orchestration::load_active_run(&data_dir)
            .expect("run should load")
            .expect("run should exist");
        assert_eq!(loaded.status, "blocked");
        let acceptance_step = loaded
            .steps
            .iter()
            .find(|step| step.step_id == "goal_acceptance")
            .expect("acceptance step should exist");
        assert_eq!(acceptance_step.status, OrchestrationStepStatus::Blocked);
        assert!(acceptance_step
            .artifacts
            .iter()
            .any(|artifact| artifact
                == &format!("goal_acceptance_diagnostic::agent:{}", agent.agent_id)));
        assert!(acceptance_step.artifacts.iter().any(|artifact| {
            artifact
                == &goal_task_claim_blocked_ref(
                    entry_id,
                    &agent.agent_id,
                    "worker_output_repair_required",
                )
        }));
        assert_eq!(active_goal_task_claims(&loaded).len(), 1);
        assert!(goal_task_claim_is_blocked(
            &loaded,
            entry_id,
            &agent.agent_id
        ));

        for _ in 0..2 {
            let repeat = advance(&data_dir, &workspace_root, project_id).expect("repeat advance");
            assert!(repeat.acceptance.is_none());
        }
        let reviews = crate::reviews::list(&data_dir, None, None).expect("reviews should list");
        assert_eq!(reviews.total_count, 0);
        let loaded = crate::orchestration::load_active_run(&data_dir)
            .expect("run should load")
            .expect("run should exist");
        let diagnostic_agent_ref = format!("goal_acceptance_diagnostic::agent:{}", agent.agent_id);
        let diagnostic_agent_ref_count = loaded
            .steps
            .iter()
            .flat_map(|step| step.artifacts.iter())
            .filter(|artifact| *artifact == &diagnostic_agent_ref)
            .count();
        assert_eq!(diagnostic_agent_ref_count, 1);
    }

    #[test]
    fn full_auto_provider_repair_review_resolves_to_followup_without_pending_human_gate() {
        let workspace_root = temp_git_workspace("goals_provider_repair_review_followup");
        let data_dir = workspace_root.join(".pmcli");
        let project_id = "project_goal_provider_repair_review_followup";
        let frame = mission_frame_with_mode(project_id, GoalAutomationMode::FullAuto);
        write_frame(&data_dir, &frame).expect("frame should write");
        save_stage_task_semantic_review_policy(
            &data_dir,
            &GoalStageTaskSemanticReviewPolicy::new(
                "provider",
                "test_provider_unavailable",
                Some("job_test".to_string()),
            ),
        )
        .expect("provider repair review policy should write");
        crate::research::record(
            &data_dir,
            project_id,
            crate::research::ResearchRecordRequest {
                kind: "goal".to_string(),
                title: "Provider repair review should not wait for human".to_string(),
                stage_id: "literature".to_string(),
                mode: "ready_to_execute".to_string(),
                decisions: Vec::new(),
                open_questions: Vec::new(),
                evidence_refs: Vec::new(),
            },
        )
        .expect("research record should create active stage");
        let stage_execution_id = crate::research::status(&data_dir, project_id)
            .expect("research status")
            .active_stage_execution
            .expect("active stage")
            .execution_id;
        let agent = crate::agents::start_local(
            &data_dir,
            &workspace_root,
            crate::agents::LocalAgentStartRequest {
                intent: "goal task dispatch: weak acceptance standard setting".to_string(),
                role_profile: "stage_standard_setter".to_string(),
                message: "produce weak placeholder rubric evidence".to_string(),
                command: "mkdir -p .pmcli/goal-worker-output/actions && cat > .pmcli/goal-worker-output/actions/weak_rubric.md <<'EOF'\nstage_acceptance_rubric\nresearch bottom line\nexpert acceptance target\nstage-specific pass criteria\nfailure signals\nreview-to-task routing\nDocFrame evidence refs\nplaceholder scaffold not implemented\nmissing-source risk remains open\nEOF\ncat .pmcli/goal-worker-output/actions/weak_rubric.md".to_string(),
                stage_task_contract: None,
            },
        )
        .expect("local agent should run");
        let entry_id = stage_task_id(&stage_execution_id, "acceptance standard setting");
        let mut run = goal_acceptance_ready_run(GoalAutomationMode::FullAuto);
        run.steps
            .iter_mut()
            .find(|step| step.step_id == "goal_dispatch")
            .expect("dispatch step should exist")
            .artifacts
            .push(goal_task_claim_ref(&entry_id, &agent.agent_id));
        crate::orchestration::save_run(&data_dir, &run).expect("run should save");

        let result = advance(&data_dir, &workspace_root, project_id).expect("advance should work");
        let acceptance = result.acceptance.expect("acceptance should exist");

        assert_eq!(acceptance.status, "blocked");
        assert_eq!(acceptance.verdict, "stage_task_repair_review_opened");
        let reviews = crate::reviews::list(&data_dir, None, None).expect("reviews should list");
        assert_eq!(reviews.total_count, 1);
        assert_eq!(reviews.reviews[0].status, "resolved");
        assert_eq!(reviews.reviews[0].verdict, "blocked");
        let status = status(&data_dir, &workspace_root, project_id).expect("goal status");
        let followup = status
            .task_pool
            .entries
            .iter()
            .find(|entry| entry.source.source_kind == "goal_repair_followup_task")
            .expect("resolved provider repair review should create follow-up task");
        assert_eq!(followup.bucket_id, "ready_to_run");
        let followup_stage_task = followup
            .stage_task
            .as_ref()
            .expect("follow-up should preserve stage task metadata");
        assert_eq!(followup_stage_task.stage_execution_id, stage_execution_id);
        assert_eq!(followup_stage_task.stage_id, "literature");
        assert!(followup_stage_task
            .task_type
            .contains("acceptance standard setting"));
    }

    #[test]
    fn literature_stage_task_roles_use_specialized_role_packages() {
        assert_eq!(
            stage_worker_role("literature", "paper search"),
            "literature_researcher"
        );
        assert_eq!(
            stage_worker_role("literature", "source verification"),
            "citation_auditor"
        );
        assert_eq!(
            stage_worker_role("literature", "citation verification"),
            "citation_auditor"
        );
        assert_eq!(
            stage_worker_role("literature", "paper clustering"),
            "literature_comparison_researcher"
        );
        assert_eq!(
            stage_worker_role("literature", "closest-family survey"),
            "literature_comparison_researcher"
        );
        assert_eq!(
            stage_worker_role("literature", "method comparison"),
            "literature_comparison_researcher"
        );
        assert_eq!(
            stage_worker_role("literature", "open-problem extraction"),
            "literature_gap_analyst"
        );
        assert_eq!(
            stage_worker_role("literature", "stage artifact synthesis"),
            "research_synthesizer"
        );
        assert!(stage_research_task_types_for_stage("literature")
            .iter()
            .any(|task_type| *task_type == "stage artifact synthesis"));
    }

    #[test]
    fn advance_consumes_resolved_repair_review_and_closes_blocked_claim() {
        let workspace_root = temp_git_workspace("goals_full_auto_repair_review_resolved");
        let data_dir = workspace_root.join(".pmcli");
        let project_id = "project_goal_repair_review_resolved";
        let frame = mission_frame_with_mode(project_id, GoalAutomationMode::FullAuto);
        write_frame(&data_dir, &frame).expect("frame should write");
        let agent = crate::agents::start_local(
            &data_dir,
            &workspace_root,
            crate::agents::LocalAgentStartRequest {
                intent: "goal task dispatch: failing task".to_string(),
                role_profile: "goal_worker".to_string(),
                message: "produce a failed output manifest".to_string(),
                command: "printf failure >&2; exit 7".to_string(),
                stage_task_contract: None,
            },
        )
        .expect("local agent should run");
        let entry_id = "automation_policy::full_auto::dispatch_agent_task";
        let mut run = goal_acceptance_ready_run(GoalAutomationMode::FullAuto);
        run.steps
            .iter_mut()
            .find(|step| step.step_id == "goal_dispatch")
            .expect("dispatch step should exist")
            .artifacts
            .push(goal_task_claim_ref(entry_id, &agent.agent_id));
        let inspection =
            crate::agents::inspect(&data_dir, &agent.agent_id).expect("agent should inspect");
        let review = crate::reviews::open(
            &data_dir,
            crate::reviews::ReviewOpenRequest {
                target_paths: goal_repair_review_targets(&inspection),
                objective: format!("Repair failed goal worker output from {}", agent.agent_id),
                reviewer_role: "repair_reviewer".to_string(),
                review_model: "test-reviewer".to_string(),
                blind_context: vec![format!("agent_id: {}", agent.agent_id)],
                review_materials: Vec::new(),
                executor_summary: Some(
                    "test fixture opened a real pending repair review".to_string(),
                ),
                evidence_required: vec!["safe next action".to_string()],
                compare_against: None,
                retry_of: None,
                retry_attempt: 0,
                verdict: None,
                response_text: None,
            },
        )
        .expect("pending repair review should open");
        let acceptance = GoalTaskAcceptanceResult {
            schema_version: "goal_task_acceptance_result.v1".to_string(),
            status: "blocked".to_string(),
            automation_mode: GoalAutomationMode::FullAuto,
            agent_id: agent.agent_id.clone(),
            task_packet_ref: agent.task_packet_path.clone(),
            output_manifest_ref: agent.output_manifest_path.clone(),
            trace_refs: agent.runtime_record.trace_refs.clone(),
            worker_artifact_candidate_refs: worker_artifact_candidate_refs(&inspection),
            verdict: "repair_review_opened".to_string(),
            review_packet_refs: vec![review.packet_path.clone()],
            diagnostic_refs: Vec::new(),
            stage_task_acceptance: None,
            research_stage_execution_ref: None,
            task_pool_entry_id: Some(entry_id.to_string()),
            claim_ref: Some(goal_task_claim_ref(entry_id, &agent.agent_id)),
            claim_status: Some("blocked_repair_review_opened".to_string()),
            provider_failure: None,
        };
        record_goal_repair_review_artifact(&mut run, &frame, &acceptance, &review);
        crate::orchestration::save_run(&data_dir, &run).expect("run should save");
        let reviews = crate::reviews::list(&data_dir, None, None).expect("reviews should list");
        let review_id = reviews.reviews[0].review_id.clone();
        crate::reviews::resolve(
            &data_dir,
            &review_id,
            crate::reviews::ReviewResolveRequest {
                verdict: "pass".to_string(),
                response_text: "safe to continue after repair review".to_string(),
            },
        )
        .expect("review should resolve");

        let consumed = advance(&data_dir, &workspace_root, project_id)
            .expect("resolved repair review should be consumed");

        assert_eq!(consumed.action, "consume_resolved_repair_review");
        assert!(consumed.dispatch.is_none());
        assert!(consumed.acceptance.is_none());
        assert_eq!(consumed.run.status, "running");
        let followup_entry = consumed
            .task_pool
            .entries
            .iter()
            .find(|entry| entry.source.source_kind == "goal_repair_followup_task")
            .expect("repair follow-up task should be projected");
        assert_eq!(followup_entry.bucket_id, "ready_to_run");
        assert_eq!(followup_entry.action_policy.as_deref(), Some("allowed"));
        assert_eq!(followup_entry.source.source_id, review_id);
        assert!(followup_entry
            .summary
            .contains("safe to continue after repair review"));
        let loaded = crate::orchestration::load_active_run(&data_dir)
            .expect("run should load")
            .expect("run should exist");
        assert!(!run_has_pending_goal_repair_review(&loaded));
        assert!(active_goal_task_claims(&loaded).is_empty());
        let acceptance_step = loaded
            .steps
            .iter()
            .find(|step| step.step_id == "goal_acceptance")
            .expect("acceptance step should exist");
        assert_eq!(acceptance_step.status, OrchestrationStepStatus::Pending);
        assert!(acceptance_step.artifacts.iter().any(|artifact| {
            artifact
                == &goal_task_claim_closed_ref(entry_id, &agent.agent_id, "repair_review_passed")
        }));
        assert!(acceptance_step.artifacts.iter().any(|artifact| {
            artifact
                == &goal_repair_followup_task_ref(&GoalRepairReviewRef {
                    agent_id: agent.agent_id.clone(),
                    review_id: review_id.clone(),
                })
        }));
        let dispatch_step = loaded
            .steps
            .iter()
            .find(|step| step.step_id == "goal_dispatch")
            .expect("dispatch step should exist");
        assert_eq!(dispatch_step.status, OrchestrationStepStatus::Pending);
        let repair = GoalRepairReviewRef {
            agent_id: agent.agent_id.clone(),
            review_id,
        };
        assert!(acceptance_step.artifacts.iter().any(|artifact| {
            artifact == &goal_repair_review_consumed_ref(&repair, "pass", "passed")
        }));

        let dispatched = advance(&data_dir, &workspace_root, project_id)
            .expect("repair follow-up should dispatch on next advance");
        let dispatch = dispatched.dispatch.expect("dispatch should occur");
        assert_eq!(dispatched.action, "start_pending_step");
        assert_eq!(
            dispatch.source_entry.source.source_kind,
            "goal_repair_followup_task"
        );
        assert_eq!(dispatch.source_entry.source.source_id, repair.review_id);
        assert!(dispatch
            .task_pool_entry_id
            .starts_with("goal_repair_followup::"));

        let accepted = advance(&data_dir, &workspace_root, project_id)
            .expect("repair follow-up output should be accepted");
        let acceptance = accepted.acceptance.expect("acceptance should occur");
        assert!(matches!(
            accepted.action.as_str(),
            "start_pending_step" | "refresh_goal_state"
        ));
        assert_eq!(acceptance.status, "accepted");
        assert_eq!(
            acceptance.task_pool_entry_id,
            Some(dispatch.task_pool_entry_id)
        );
        assert_eq!(accepted.run.status, "accepted");
    }

    #[test]
    fn nested_repair_followup_preserves_original_stage_task_type() {
        let workspace_root = temp_git_workspace("goals_nested_stage_repair_followup");
        let data_dir = workspace_root.join(".pmcli");
        let project_id = "project_goal_nested_stage_repair_followup";
        crate::research::record(
            &data_dir,
            project_id,
            crate::research::ResearchRecordRequest {
                kind: "goal".to_string(),
                title: "Preserve original stage task through nested repair".to_string(),
                stage_id: "literature".to_string(),
                mode: "ready_to_execute".to_string(),
                decisions: Vec::new(),
                open_questions: Vec::new(),
                evidence_refs: Vec::new(),
            },
        )
        .expect("research record should create active stage");
        let stage_execution_id = crate::research::status(&data_dir, project_id)
            .expect("research status")
            .active_stage_execution
            .expect("active stage")
            .execution_id;
        let original_entry_id = stage_task_id(&stage_execution_id, "paper search");
        let original_agent_id = "agent_original_paper_search";
        let first_repair_review_id = "review_original_paper_search";
        let first_repair_entry_id = goal_repair_followup_entry_id(&GoalRepairReviewRef {
            agent_id: original_agent_id.to_string(),
            review_id: first_repair_review_id.to_string(),
        });
        let repair_agent_id = "agent_repair_attempt";

        let mut run = goal_acceptance_ready_run(GoalAutomationMode::FullAuto);
        let dispatch_step = run
            .steps
            .iter_mut()
            .find(|step| step.step_id == "goal_dispatch")
            .expect("dispatch step should exist");
        dispatch_step
            .artifacts
            .push(goal_task_claim_ref(&original_entry_id, original_agent_id));
        dispatch_step
            .artifacts
            .push(goal_task_claim_ref(&first_repair_entry_id, repair_agent_id));
        let acceptance_step = run
            .steps
            .iter_mut()
            .find(|step| step.step_id == "goal_acceptance")
            .expect("acceptance step should exist");
        acceptance_step
            .artifacts
            .push(goal_repair_followup_task_ref(&GoalRepairReviewRef {
                agent_id: original_agent_id.to_string(),
                review_id: first_repair_review_id.to_string(),
            }));

        let nested_repair = GoalRepairReviewRef {
            agent_id: repair_agent_id.to_string(),
            review_id: "review_nested_repair_failure".to_string(),
        };
        let stage_task = repair_followup_stage_task_for_failed_agent(
            &data_dir,
            &run,
            &nested_repair,
            "repair still failed",
        )
        .expect("nested repair should resolve the original stage task");

        assert_eq!(stage_task.stage_execution_id, stage_execution_id);
        assert_eq!(stage_task.stage_id, "literature");
        assert_eq!(stage_task.task_type, "paper search");
        assert_eq!(
            stage_task.task_id,
            goal_repair_followup_entry_id(&nested_repair)
        );
        assert!(stage_task
            .objective
            .contains("goal_repair_followup::review:review_original_paper_search"));
    }

    #[test]
    fn repair_followup_claim_resolves_stage_task_during_acceptance() {
        let workspace_root = temp_git_workspace("goals_repair_followup_acceptance_stage_task");
        let data_dir = workspace_root.join(".pmcli");
        let project_id = "project_goal_repair_followup_acceptance_stage_task";
        let frame = mission_frame_with_mode(project_id, GoalAutomationMode::FullAuto);
        write_frame(&data_dir, &frame).expect("frame should write");
        crate::research::record(
            &data_dir,
            project_id,
            crate::research::ResearchRecordRequest {
                kind: "goal".to_string(),
                title: "Resolve repair follow-up as original stage task during acceptance"
                    .to_string(),
                stage_id: "literature".to_string(),
                mode: "ready_to_execute".to_string(),
                decisions: Vec::new(),
                open_questions: Vec::new(),
                evidence_refs: Vec::new(),
            },
        )
        .expect("research record should create active stage");
        let stage_execution_id = crate::research::status(&data_dir, project_id)
            .expect("research status")
            .active_stage_execution
            .expect("active stage")
            .execution_id;
        let original_agent_id = "agent_original_paper_search";
        let repair = GoalRepairReviewRef {
            agent_id: original_agent_id.to_string(),
            review_id: "review_original_paper_search".to_string(),
        };
        let repair_entry_id = goal_repair_followup_entry_id(&repair);
        let repair_agent_id = "agent_repair_attempt";

        let mut run = goal_acceptance_ready_run(GoalAutomationMode::FullAuto);
        let dispatch_step = run
            .steps
            .iter_mut()
            .find(|step| step.step_id == "goal_dispatch")
            .expect("dispatch step should exist");
        dispatch_step.artifacts.push(goal_task_claim_ref(
            &stage_task_id(&stage_execution_id, "paper search"),
            original_agent_id,
        ));
        dispatch_step
            .artifacts
            .push(goal_task_claim_ref(&repair_entry_id, repair_agent_id));
        run.steps
            .iter_mut()
            .find(|step| step.step_id == "goal_acceptance")
            .expect("acceptance step should exist")
            .artifacts
            .push(goal_repair_followup_task_ref(&repair));

        let claim = GoalTaskClaim {
            entry_id: repair_entry_id.clone(),
            agent_id: repair_agent_id.to_string(),
        };
        let stage_task =
            stage_task_for_claim(&data_dir, &workspace_root, project_id, &frame, &run, &claim)
                .expect("repair follow-up claim should resolve original stage task metadata");

        assert_eq!(stage_task.stage_execution_id, stage_execution_id);
        assert_eq!(stage_task.stage_id, "literature");
        assert_eq!(stage_task.task_type, "paper search");
        assert_eq!(stage_task.task_id, repair_entry_id);
        assert_eq!(
            stage_task.claimed_by_agent_id.as_deref(),
            Some(repair_agent_id)
        );
        assert!(stage_task
            .acceptance_checks
            .iter()
            .any(|check| check.contains("blocking review findings")));
    }

